//! Direct AST to Rust source code generation.
//!
//! This module generates Rust source code directly from the Clang AST,
//! without going through an intermediate MIR representation.
//! This produces cleaner, more idiomatic Rust code.

use crate::ast::{
    AccessSpecifier, BinaryOp, CastKind, ClangNode, ClangNodeKind, ConstructorKind, CoroutineInfo,
    CoroutineKind, TemplateSpecializationKind, UnaryOp,
};
use crate::types::{normalize_rusty_type_alias_to_std, parse_template_args, CppType};
use std::borrow::Cow;
use std::cell::RefCell;
use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};
use std::fmt::Write;
use std::sync::Arc;

/// Convert C++ access specifier to Rust visibility prefix.
/// - Public → "pub "
/// - Protected → "pub(crate) " (accessible within crate, roughly matches protected semantics)
/// - Private → "" (no visibility prefix, private by default in Rust)
fn access_to_visibility(access: AccessSpecifier) -> &'static str {
    match access {
        AccessSpecifier::Public => "pub ",
        AccessSpecifier::Protected => "pub(crate) ",
        AccessSpecifier::Private => "",
    }
}

/// Strip numeric literal suffixes (i32, u64, f32, etc.) from a string.
/// Used when Rust can infer the type from context.
fn strip_literal_suffix(s: &str) -> String {
    // Check for integer suffixes: i8, i16, i32, i64, i128, isize, u8, u16, u32, u64, u128, usize
    // Check for float suffixes: f32, f64
    let suffixes = [
        "i128", "u128", "isize", "usize", // longest first
        "i64", "u64", "i32", "u32", "i16", "u16", "i8", "u8", "f64", "f32",
    ];
    for suffix in suffixes {
        if let Some(prefix) = s.strip_suffix(suffix) {
            // Make sure the prefix is a valid number (not ending with a letter)
            if !prefix.is_empty() && prefix.chars().last().is_some_and(|c| c.is_ascii_digit()) {
                return prefix.to_string();
            }
        }
    }
    s.to_string()
}

/// Check if a string is an integer literal (possibly with suffix).
/// Returns true for: "0", "123", "0i32", "456u64", etc.
fn is_integer_literal_str(s: &str) -> bool {
    let stripped = strip_literal_suffix(s);
    // Check if it's a valid integer (optionally with leading minus)
    let s = stripped.strip_prefix('-').unwrap_or(&stripped);
    !s.is_empty() && s.chars().all(|c| c.is_ascii_digit())
}

/// Check if a string is a zero integer literal (possibly with suffix).
fn is_zero_integer_literal_str(s: &str) -> bool {
    is_integer_literal_str(s) && strip_literal_suffix(s).trim_start_matches('-') == "0"
}

/// Check if a string is a one integer literal (possibly with suffix).
fn is_one_integer_literal_str(s: &str) -> bool {
    is_integer_literal_str(s) && strip_literal_suffix(s) == "1"
}

/// Parse an integer literal string (optionally parenthesized and/or suffixed) to i128.
fn parse_integer_literal_value_str(s: &str) -> Option<i128> {
    let mut raw = s.trim();
    while is_fully_parenthesized_expr(raw) && raw.len() >= 2 {
        raw = raw[1..raw.len() - 1].trim();
    }
    if !is_integer_literal_str(raw) {
        return None;
    }
    strip_literal_suffix(raw).parse::<i128>().ok()
}

/// Check whether a Rust primitive type string is an unsigned integer.
fn is_unsigned_rust_int_type(ty: &str) -> bool {
    matches!(ty, "u8" | "u16" | "u32" | "u64" | "u128" | "usize")
}

/// Check whether a Rust primitive type string is an integral type (excluding bool).
fn is_rust_integral_non_bool_type(ty: &str) -> bool {
    matches!(
        ty,
        "i8" | "i16"
            | "i32"
            | "i64"
            | "i128"
            | "isize"
            | "u8"
            | "u16"
            | "u32"
            | "u64"
            | "u128"
            | "usize"
    )
}

/// Check whether a Rust type string is an Option-wrapped function pointer.
fn is_option_fn_rust_type(ty: &str) -> bool {
    ty.starts_with("Option<fn(")
        || ty.starts_with("Option<unsafe fn(")
        || ty.starts_with("Option<extern \"C\" fn(")
        || ty.starts_with("Option<unsafe extern \"C\" fn(")
}

/// Conservative check for C++ types that are trivially copyable in generated Rust.
fn is_copy_like_cpp_type(ty: &CppType) -> bool {
    match ty {
        CppType::Bool
        | CppType::Char { .. }
        | CppType::Short { .. }
        | CppType::Int { .. }
        | CppType::Long { .. }
        | CppType::LongLong { .. }
        | CppType::Float
        | CppType::Double => true,
        CppType::Pointer { .. } | CppType::Reference { .. } | CppType::Function { .. } => true,
        CppType::Array { element, .. } => is_copy_like_cpp_type(element),
        CppType::Void
        | CppType::Named(_)
        | CppType::TemplateParam { .. }
        | CppType::DependentType { .. }
        | CppType::ParameterPack { .. } => false,
    }
}

/// Convert a negative integer literal into an explicit cast for unsigned targets.
/// Example: "-5" + "u64" -> "(-5i32 as u64)".
fn cast_negative_literal_to_unsigned(lit: &str, unsigned_ty: &str) -> Option<String> {
    if !is_unsigned_rust_int_type(unsigned_ty) {
        return None;
    }
    let value = parse_integer_literal_value_str(lit.trim())?;
    if value >= 0 {
        return None;
    }
    let abs_val = value.checked_abs().unwrap_or(i128::MAX);
    let signed_src_ty = if abs_val <= i32::MAX as i128 {
        "i32"
    } else if abs_val <= i64::MAX as i128 {
        "i64"
    } else {
        "i128"
    };
    Some(format!("({}{} as {})", value, signed_src_ty, unsigned_ty))
}

/// Detect unsigned integer suffix for a standalone integer literal string.
/// Supports optional leading `-` and outer parentheses.
fn unsigned_integer_literal_suffix(s: &str) -> Option<&'static str> {
    let mut raw = s.trim();
    while is_fully_parenthesized_expr(raw) && raw.len() >= 2 {
        raw = raw[1..raw.len() - 1].trim();
    }
    let digits = raw.strip_prefix('-').unwrap_or(raw);
    if digits.is_empty() {
        return None;
    }
    for unsigned_ty in ["usize", "u128", "u64", "u32", "u16", "u8"] {
        if let Some(prefix) = digits.strip_suffix(unsigned_ty) {
            if !prefix.is_empty() && prefix.chars().all(|c| c.is_ascii_digit()) {
                return Some(unsigned_ty);
            }
        }
    }
    None
}

/// Normalize standalone negative unsigned literals (e.g. `-1u64`) to
/// signed-source cast forms Rust accepts.
fn cast_negative_unsigned_literal_expr(expr: &str) -> Option<String> {
    let mut raw = expr.trim();
    while is_fully_parenthesized_expr(raw) && raw.len() >= 2 {
        raw = raw[1..raw.len() - 1].trim();
    }
    if !raw.starts_with('-') {
        return None;
    }
    let unsigned_ty = unsigned_integer_literal_suffix(raw)?;
    cast_negative_literal_to_unsigned(raw, unsigned_ty)
}

/// Normalize unary-minus applied to an unsigned literal operand into
/// a signed-source cast form that Rust accepts.
/// Example: operand `1u64` -> `(-1i32 as u64)`.
fn cast_unary_minus_unsigned_literal_operand(operand: &str) -> Option<String> {
    let raw = operand.trim();
    if raw.starts_with('-') {
        return None;
    }
    let unsigned_ty = unsigned_integer_literal_suffix(raw)?;
    if let Some(stripped) = raw.strip_suffix(unsigned_ty) {
        let digits = stripped.trim().trim_matches(|c| c == '(' || c == ')');
        if !digits.is_empty() && digits.chars().all(|c| c.is_ascii_digit()) {
            let neg_lit = format!("-{}{}", digits, unsigned_ty);
            return cast_negative_literal_to_unsigned(&neg_lit, unsigned_ty);
        }
    }
    None
}

/// Split a comma-delimited list while respecting (), [], and {} nesting.
fn split_top_level_comma_list(src: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut start = 0usize;
    let mut paren_depth = 0usize;
    let mut bracket_depth = 0usize;
    let mut brace_depth = 0usize;
    for (idx, ch) in src.char_indices() {
        match ch {
            '(' => paren_depth += 1,
            ')' => {
                if paren_depth > 0 {
                    paren_depth -= 1;
                }
            }
            '[' => bracket_depth += 1,
            ']' => {
                if bracket_depth > 0 {
                    bracket_depth -= 1;
                }
            }
            '{' => brace_depth += 1,
            '}' => {
                if brace_depth > 0 {
                    brace_depth -= 1;
                }
            }
            ',' if paren_depth == 0 && bracket_depth == 0 && brace_depth == 0 => {
                out.push(src[start..idx].to_string());
                start = idx + 1;
            }
            _ => {}
        }
    }
    out.push(src[start..].to_string());
    out
}

/// Split by a top-level binary operator character while respecting (), [], and {} nesting.
fn split_top_level_by_operator(src: &str, op: char) -> Vec<String> {
    let mut out = Vec::new();
    let mut start = 0usize;
    let mut paren_depth = 0usize;
    let mut bracket_depth = 0usize;
    let mut brace_depth = 0usize;
    for (idx, ch) in src.char_indices() {
        match ch {
            '(' => paren_depth += 1,
            ')' => {
                if paren_depth > 0 {
                    paren_depth -= 1;
                }
            }
            '[' => bracket_depth += 1,
            ']' => {
                if bracket_depth > 0 {
                    bracket_depth -= 1;
                }
            }
            '{' => brace_depth += 1,
            '}' => {
                if brace_depth > 0 {
                    brace_depth -= 1;
                }
            }
            _ if ch == op && paren_depth == 0 && bracket_depth == 0 && brace_depth == 0 => {
                out.push(src[start..idx].to_string());
                start = idx + ch.len_utf8();
            }
            _ => {}
        }
    }
    out.push(src[start..].to_string());
    out
}

/// Rewrite integer suffixes (e.g. `10u64`) to a new suffix when they are numeric literals.
fn rewrite_numeric_literal_suffix(expr: &str, from: &str, to: &str) -> String {
    let mut out = String::new();
    let mut idx = 0usize;
    while idx < expr.len() {
        if expr[idx..].starts_with(from) {
            let prev = expr[..idx].chars().last();
            let next = expr[idx + from.len()..].chars().next();
            let prev_is_digit = prev.is_some_and(|c| c.is_ascii_digit());
            let next_is_ident = next.is_some_and(|c| c.is_ascii_alphanumeric() || c == '_');
            if prev_is_digit && !next_is_ident {
                out.push_str(to);
                idx += from.len();
                continue;
            }
        }
        let ch = expr[idx..].chars().next().unwrap();
        out.push(ch);
        idx += ch.len_utf8();
    }
    out
}

/// Normalize `(-N) as uX` forms so Rust sees a signed-source literal cast.
fn normalize_parenthesized_negative_casts_to_unsigned(expr: &str, unsigned_ty: &str) -> String {
    let mut out = String::new();
    let mut idx = 0usize;
    let mut last = 0usize;
    while idx < expr.len() {
        if expr[idx..].starts_with("(-") {
            let mut digits_end = idx + 2;
            while digits_end < expr.len()
                && expr[digits_end..]
                    .chars()
                    .next()
                    .is_some_and(|c| c.is_ascii_digit())
            {
                digits_end += expr[digits_end..].chars().next().unwrap().len_utf8();
            }
            if digits_end > idx + 2 && expr[digits_end..].starts_with(')') {
                let mut as_idx = digits_end + 1;
                while as_idx < expr.len()
                    && expr[as_idx..]
                        .chars()
                        .next()
                        .is_some_and(|c| c.is_whitespace())
                {
                    as_idx += expr[as_idx..].chars().next().unwrap().len_utf8();
                }
                if expr[as_idx..].starts_with("as") {
                    as_idx += 2;
                    while as_idx < expr.len()
                        && expr[as_idx..]
                            .chars()
                            .next()
                            .is_some_and(|c| c.is_whitespace())
                    {
                        as_idx += expr[as_idx..].chars().next().unwrap().len_utf8();
                    }
                    if expr[as_idx..].starts_with(unsigned_ty) {
                        let lit = &expr[idx + 1..digits_end];
                        if let Some(casted) = cast_negative_literal_to_unsigned(lit, unsigned_ty) {
                            out.push_str(&expr[last..idx]);
                            out.push_str(&casted);
                            idx = as_idx + unsigned_ty.len();
                            last = idx;
                            continue;
                        }
                    }
                }
            }
        }
        idx += expr[idx..].chars().next().unwrap().len_utf8();
    }
    out.push_str(&expr[last..]);
    out
}

/// Normalize `(-N as uX)` forms where the negative literal is parenthesized
/// together with the cast expression rather than as a standalone `(-N)`.
fn normalize_inline_negative_casts_to_unsigned(expr: &str, unsigned_ty: &str) -> String {
    let mut out = String::new();
    let mut idx = 0usize;
    let mut last = 0usize;
    while idx < expr.len() {
        if expr[idx..].starts_with("(-") {
            let mut digits_end = idx + 2;
            while digits_end < expr.len()
                && expr[digits_end..]
                    .chars()
                    .next()
                    .is_some_and(|c| c.is_ascii_digit())
            {
                digits_end += expr[digits_end..].chars().next().unwrap().len_utf8();
            }
            if digits_end > idx + 2 {
                let mut as_idx = digits_end;
                while as_idx < expr.len()
                    && expr[as_idx..]
                        .chars()
                        .next()
                        .is_some_and(|c| c.is_whitespace())
                {
                    as_idx += expr[as_idx..].chars().next().unwrap().len_utf8();
                }
                if expr[as_idx..].starts_with("as") {
                    as_idx += 2;
                    while as_idx < expr.len()
                        && expr[as_idx..]
                            .chars()
                            .next()
                            .is_some_and(|c| c.is_whitespace())
                    {
                        as_idx += expr[as_idx..].chars().next().unwrap().len_utf8();
                    }
                    if expr[as_idx..].starts_with(unsigned_ty) {
                        let mut close_idx = as_idx + unsigned_ty.len();
                        while close_idx < expr.len()
                            && expr[close_idx..]
                                .chars()
                                .next()
                                .is_some_and(|c| c.is_whitespace())
                        {
                            close_idx += expr[close_idx..].chars().next().unwrap().len_utf8();
                        }
                        if expr[close_idx..].starts_with(')') {
                            let lit = format!("-{}", &expr[idx + 2..digits_end]);
                            if let Some(casted) = cast_negative_literal_to_unsigned(&lit, unsigned_ty)
                            {
                                out.push_str(&expr[last..idx]);
                                out.push_str(&casted);
                                idx = close_idx + 1;
                                last = idx;
                                continue;
                            }
                        }
                    }
                }
            }
        }
        idx += expr[idx..].chars().next().unwrap().len_utf8();
    }
    out.push_str(&expr[last..]);
    out
}

/// Normalize `[u128; N]` aggregate initializer text so all numeric constants are valid u128 forms.
fn normalize_u128_array_initializer_expr(expr: &str) -> String {
    fn normalize_u128_wrapping_mul_expr(expr: &str) -> String {
        let mut core = expr.trim();
        while is_fully_parenthesized_expr(core) && core.len() >= 2 {
            core = core[1..core.len() - 1].trim();
        }
        let factors = split_top_level_by_operator(core, '*');
        if factors.len() <= 1 {
            return core.to_string();
        }
        let mut iter = factors
            .into_iter()
            .map(|f| normalize_u128_wrapping_mul_expr(f.as_str()));
        let first = iter.next().unwrap();
        let mut acc = format!("({})", first);
        for factor in iter {
            let rhs = factor.trim();
            let rhs = if is_integer_literal_str(rhs) {
                format!("({}) as u128", strip_literal_suffix(rhs))
            } else {
                format!("({})", rhs)
            };
            acc = format!("({}).wrapping_mul({})", acc, rhs);
        }
        acc
    }

    let trimmed = expr.trim();
    let Some(inner) = trimmed.strip_prefix('[').and_then(|s| s.strip_suffix(']')) else {
        return trimmed.to_string();
    };
    let elems = split_top_level_comma_list(inner)
        .into_iter()
        .map(|elem| {
            let mut normalized =
                normalize_parenthesized_negative_casts_to_unsigned(elem.trim(), "u128");
            normalized = rewrite_numeric_literal_suffix(&normalized, "u64", "u128");
            normalized = normalize_u128_wrapping_mul_expr(&normalized);
            let normalized_trimmed = normalized.trim();
            if is_integer_literal_str(normalized_trimmed) {
                format!("({}) as u128", strip_literal_suffix(normalized_trimmed))
            } else {
                normalized
            }
        })
        .collect::<Vec<_>>();
    format!("[{}]", elems.join(", "))
}

/// Convert an integer literal string to a float literal.
/// E.g., "0" -> "0.0", "123i32" -> "123.0", "-5" -> "-5.0"
/// Special values like "inf", "NaN" are converted to proper Rust constants.
fn int_literal_to_float(s: &str) -> String {
    let stripped = strip_literal_suffix(s);
    // Handle special float values
    if stripped == "inf" {
        return "f64::INFINITY".to_string();
    } else if stripped == "-inf" {
        return "-f64::INFINITY".to_string();
    } else if stripped.to_lowercase() == "nan" {
        return "f64::NAN".to_string();
    }
    // If it's already a float literal (contains '.'), return as-is
    if stripped.contains('.') {
        return stripped;
    }
    format!("{}.0", stripped)
}

/// Wrap an expression in parentheses if it's an unsafe block, or wrap it in
/// `unsafe { }` if it dereferences a raw pointer (e.g., `*obj.op_index(idx)`).
fn wrap_unsafe_for_binop(expr: &str) -> String {
    let trimmed = expr.trim();
    if trimmed.starts_with("unsafe {") && trimmed.ends_with('}') {
        format!("({})", expr)
    } else if trimmed.starts_with('*') && trimmed.contains(".op_index(") {
        // Raw pointer dereference from subscript operator — needs unsafe
        format!("(unsafe {{ {} }})", expr)
    } else {
        expr.to_string()
    }
}

/// Wrap expressions that need parentheses before an `as` cast.
fn wrap_for_as_cast(expr: &str) -> String {
    let trimmed = expr.trim();
    if trimmed.starts_with("unsafe {")
        || trimmed.starts_with("if ")
        || trimmed.starts_with("match ")
    {
        format!("({})", expr)
    } else {
        expr.to_string()
    }
}

/// Returns true when an expression is wrapped by one outer-most pair of
/// parentheses that encloses the full expression.
fn is_fully_parenthesized_expr(expr: &str) -> bool {
    let trimmed = expr.trim();
    if !(trimmed.starts_with('(') && trimmed.ends_with(')')) {
        return false;
    }

    let mut depth = 0usize;
    for (idx, ch) in trimmed.char_indices() {
        match ch {
            '(' => depth += 1,
            ')' => {
                if depth == 0 {
                    return false;
                }
                depth -= 1;
                if depth == 0 && idx + ch.len_utf8() != trimmed.len() {
                    return false;
                }
            }
            _ => {}
        }
    }

    depth == 0
}

/// If an expression is wrapped as an outer `unsafe { ... }` block (optionally parenthesized),
/// return the inner expression.
fn unwrap_outer_unsafe_expr(expr: &str) -> Option<String> {
    let trimmed = expr.trim();
    if let Some(inner) = trimmed
        .strip_prefix("unsafe { ")
        .and_then(|s| s.strip_suffix(" }"))
    {
        return Some(inner.to_string());
    }
    if let Some(inner) = trimmed
        .strip_prefix("(unsafe { ")
        .and_then(|s| s.strip_suffix(" })"))
    {
        return Some(inner.to_string());
    }
    None
}

/// Clone an expression safely, avoiding move-out-of-raw-pointer patterns like
/// `unsafe { *ptr }.clone()` which are invalid for non-Copy types.
fn clone_expr(expr: &str) -> String {
    let trimmed = expr.trim();
    if let Some(inner) = trimmed
        .strip_prefix("unsafe { *")
        .and_then(|s| s.strip_suffix(" }"))
    {
        format!("unsafe {{ (&*{}).clone() }}", inner.trim())
    } else {
        format!("({}).clone()", expr)
    }
}

/// Borrow an expression for a reference parameter.
/// For raw-pointer dereference expressions (e.g. `unsafe { *ptr }`), place
/// the borrow inside the unsafe block to avoid moving from `*ptr`.
fn borrow_expr_for_reference(expr: &str, is_const: bool) -> String {
    let prefix = if is_const { "&" } else { "&mut " };
    let trimmed = expr.trim();

    if let Some(inner) = unwrap_outer_unsafe_expr(trimmed) {
        let inner = inner.trim();
        if inner.starts_with('*') {
            return format!("unsafe {{ {}{} }}", prefix, inner);
        }
    } else if trimmed.starts_with('*') {
        return format!("unsafe {{ {}{} }}", prefix, trimmed);
    }

    format!("{}{}", prefix, expr)
}

/// Convert a C string literal to a fixed Rust byte array literal with trailing NUL.
fn string_literal_to_char_array_init(
    s: &str,
    signed: bool,
    size: Option<&usize>,
) -> Option<String> {
    let suffix = if signed { "i8" } else { "u8" };
    let decoded = decode_c_string_escapes_to_bytes(s);
    let mut elems: Vec<String> = decoded
        .iter()
        .map(|b| {
            if signed {
                format!("{}{}", i8::from_ne_bytes([*b]), suffix)
            } else {
                format!("{}{}", *b, suffix)
            }
        })
        .collect();
    elems.push(format!("0{}", suffix));

    if let Some(n) = size {
        let target = *n as usize;
        if elems.len() > target {
            elems.truncate(target);
        } else {
            while elems.len() < target {
                elems.push(format!("0{}", suffix));
            }
        }
    }

    Some(format!("[{}]", elems.join(", ")))
}

/// Decode common C string escapes from libclang string-literal payloads into raw bytes.
fn decode_c_string_escapes_to_bytes(s: &str) -> Vec<u8> {
    let mut out = Vec::new();
    let mut chars = s.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch != '\\' {
            let mut encoded = [0u8; 4];
            let utf8 = ch.encode_utf8(&mut encoded);
            out.extend_from_slice(utf8.as_bytes());
            continue;
        }

        let Some(esc) = chars.next() else {
            out.push(b'\\');
            break;
        };

        match esc {
            'n' => out.push(b'\n'),
            'r' => out.push(b'\r'),
            't' => out.push(b'\t'),
            'a' => out.push(0x07),
            'b' => out.push(0x08),
            'f' => out.push(0x0c),
            'v' => out.push(0x0b),
            '\\' => out.push(b'\\'),
            '\'' => out.push(b'\''),
            '"' => out.push(b'"'),
            '?' => out.push(b'?'),
            '0'..='7' => {
                let mut val = esc.to_digit(8).unwrap_or(0);
                for _ in 0..2 {
                    if let Some(next) = chars.peek().copied() {
                        if let Some(d) = next.to_digit(8) {
                            chars.next();
                            val = (val << 3) + d;
                        } else {
                            break;
                        }
                    }
                }
                out.push(val as u8);
            }
            'x' => {
                let mut val: u32 = 0;
                let mut seen = 0usize;
                while let Some(next) = chars.peek().copied() {
                    if let Some(d) = next.to_digit(16) {
                        chars.next();
                        val = (val << 4) + d;
                        seen += 1;
                    } else {
                        break;
                    }
                }
                if seen == 0 {
                    out.push(b'x');
                } else {
                    out.push(val as u8);
                }
            }
            other => out.push(other as u8),
        }
    }
    out
}

/// Escape arbitrary bytes for a Rust byte-string literal (`b"..."`).
/// Uses `\xNN` for non-printable/non-ASCII bytes and C-style escapes where available.
fn escape_bytes_for_rust_byte_string(bytes: &[u8]) -> String {
    let mut out = String::new();
    for &b in bytes {
        for escaped in std::ascii::escape_default(b) {
            out.push(escaped as char);
        }
    }
    out
}

/// Check if a name looks like a C++ AST class name that was incorrectly encoded as an identifier.
/// The C++ AST exporter encodes unknown expression types as DeclRefExpr with the class name
/// (e.g., "CXXDependentScopeMemberExpr", "UnresolvedMemberExpr") as the identifier.
/// These are template-dependent expressions that can't be fully resolved.
fn is_cpp_ast_class_name(name: &str) -> bool {
    // Known C++ AST class names that appear as unresolved expressions
    const CPP_AST_NAMES: &[&str] = &[
        "CXXDependentScopeMemberExpr",
        "CXXUnresolvedConstructExpr",
        "UnresolvedMemberExpr",
        "UnresolvedLookupExpr",
        "DependentScopeDeclRefExpr",
        "PackExpansionExpr",
        "SizeOfPackExpr",
        "TypeTraitExpr",
        "CXXNoexceptExpr",
        "SubstNonTypeTemplateParmExpr",
        "ExprWithCleanups",
        "MaterializeTemporaryExpr",
        "CXXBindTemporaryExpr",
        "CXXDefaultArgExpr",
        "CXXDefaultInitExpr",
        "CXXStdInitializerListExpr",
        "CXXPseudoDestructorExpr",
        "CXXTypeidExpr",
        "CXXUuidofExpr",
        "CXXThrowExpr",
        "CXXScalarValueInitExpr",
        "CXXNullPtrLiteralExpr",
        "CXXBoolLiteralExpr",
        "UserDefinedLiteral",
        "CompoundLiteralExpr",
        "AtomicExpr",
        "GenericSelectionExpr",
        "PseudoObjectExpr",
        "OpaqueValueExpr",
        "TypoExpr",
        "RecoveryExpr",
        "ArrayTypeTraitExpr",
        "ExpressionTraitExpr",
        "FunctionParmPackExpr",
        "CXXFoldExpr",
        "ConceptSpecializationExpr",
        "RequiresExpr",
    ];

    CPP_AST_NAMES.contains(&name)
}

/// Rust reserved keywords that need raw identifier syntax.
const RUST_KEYWORDS: &[&str] = &[
    "as", "async", "await", "break", "const", "continue", "crate", "dyn", "else", "enum", "extern",
    "false", "fn", "for", "if", "impl", "in", "let", "loop", "match", "mod", "move", "mut", "pub",
    "ref", "return", "self", "Self", "static", "struct", "super", "trait", "true", "type",
    "unsafe", "use", "where", "while", "abstract", "become", "box", "do", "final", "macro",
    "override", "priv", "try", "typeof", "unsized", "virtual", "yield",
];

/// Sanitize identifier for use in composite names (like function_method).
/// Returns just the sanitized name without the r# prefix.
fn sanitize_identifier_for_composite(name: &str) -> String {
    let result = sanitize_identifier(name);
    // Strip r# prefix if present - composite names like X_vtable_type are already valid
    if result.starts_with("r#") {
        result[2..].to_string()
    } else {
        result
    }
}

/// Extract base C++ class name from a mangled Rust struct name.
///
/// The goal is to extract the class name (like "map", "vector", "__tree_node_base")
/// from mangled names like "std_map_int__int", "std_vector_int".
///
/// Examples:
/// - "std_map_int__int" -> "map"
/// - "std___tree_node_base_void__" -> "__tree_node_base"
/// - "std_vector_int" -> "vector"
/// - "std___1___map_value_compare_int__int" -> "__map_value_compare"
/// - "MyClass" -> "MyClass"
fn extract_cpp_base_class_name(rust_name: &str) -> String {
    // Strip "std_" prefix if present
    let name = rust_name.strip_prefix("std_").unwrap_or(rust_name);

    // Strip inline namespace prefix like "__1_"
    let name = name.strip_prefix("__1_").unwrap_or(name);

    // Known primitive types to skip
    let primitives = [
        "int", "void", "char", "bool", "long", "short", "float", "double", "i8", "i16", "i32",
        "i64", "i128", "u8", "u16", "u32", "u64", "u128", "usize", "isize", "f32", "f64",
    ];

    // Handle internal names (starting with __)
    // e.g., "__tree_node_base_void__" -> "__tree_node_base"
    if name.starts_with("__") {
        // Find the end of the internal name - it ends before a primitive type
        let mut end_idx = name.len();
        for prim in &primitives {
            if let Some(idx) = name.find(&format!("_{}_", prim)) {
                end_idx = end_idx.min(idx);
            } else if let Some(idx) = name.find(&format!("_{}__", prim)) {
                end_idx = end_idx.min(idx);
            } else if name.ends_with(&format!("_{}", prim)) {
                end_idx = end_idx.min(name.len() - prim.len() - 1);
            }
        }
        return name[..end_idx].to_string();
    }

    // Otherwise, the class name is the first non-primitive segment
    // e.g., "map_int__int" -> "map", "vector_int" -> "vector"
    let parts: Vec<&str> = name.split('_').collect();
    for part in &parts {
        if part.is_empty() {
            continue;
        }
        // Skip primitives
        if primitives.contains(part) {
            continue;
        }
        // Skip numeric parts (like template arg indices)
        if part.chars().all(|c| c.is_numeric()) {
            continue;
        }
        return (*part).to_string();
    }

    // Fallback: return original
    rust_name.to_string()
}

/// Convert a sanitized Rust method name back to C++ operator form for LibTooling lookup.
///
/// Examples:
/// - "op_index" -> "operator[]"
/// - "op_call" -> "operator()"
/// - "op_deref" -> "operator*"
/// - "op_plus" -> "operator+"
/// - "size" -> "size" (unchanged)
fn rust_method_name_to_cpp(rust_name: &str) -> String {
    match rust_name {
        "op_index" => "operator[]".to_string(),
        "op_call" => "operator()".to_string(),
        "op_deref" => "operator*".to_string(),
        "op_arrow" => "operator->".to_string(),
        "op_plus" => "operator+".to_string(),
        "op_minus" => "operator-".to_string(),
        "op_mul" => "operator*".to_string(),
        "op_div" => "operator/".to_string(),
        "op_mod" => "operator%".to_string(),
        "op_eq" => "operator==".to_string(),
        "op_ne" => "operator!=".to_string(),
        "op_lt" => "operator<".to_string(),
        "op_gt" => "operator>".to_string(),
        "op_le" => "operator<=".to_string(),
        "op_ge" => "operator>=".to_string(),
        "op_plus_assign" => "operator+=".to_string(),
        "op_minus_assign" => "operator-=".to_string(),
        "op_mul_assign" => "operator*=".to_string(),
        "op_div_assign" => "operator/=".to_string(),
        "op_assign" => "operator=".to_string(),
        "op_pre_inc" | "op_post_inc" => "operator++".to_string(),
        "op_pre_dec" | "op_post_dec" => "operator--".to_string(),
        "op_neg" => "operator-".to_string(),
        "op_not" => "operator!".to_string(),
        "op_bitnot" => "operator~".to_string(),
        "op_bitand" => "operator&".to_string(),
        "op_bitor" => "operator|".to_string(),
        "op_bitxor" => "operator^".to_string(),
        "op_shl" => "operator<<".to_string(),
        "op_shr" => "operator>>".to_string(),
        "op_and" => "operator&&".to_string(),
        "op_or" => "operator||".to_string(),
        _ => rust_name.to_string(),
    }
}

/// Information about a virtual method for vtable generation.
/// This represents a single entry in a C++ vtable.
#[derive(Clone, Debug)]
struct VTableEntry {
    /// Method name (e.g., "what", "~exception")
    name: String,
    /// Return type of the method
    return_type: CppType,
    /// Parameters (excluding implicit this/self)
    params: Vec<(String, CppType)>,
    /// True if method is const (affects self mutability)
    is_const: bool,
    /// True if method is pure virtual (= 0)
    is_pure_virtual: bool,
    /// Class where this method was originally declared (for override tracking)
    declaring_class: String,
    /// Index in the vtable (assigned during vtable construction)
    vtable_index: usize,
}

/// Backward compatibility alias for existing code
type VirtualMethodInfo = VTableEntry;

/// Complete vtable information for a polymorphic C++ class.
/// This includes both inherited and declared virtual methods.
#[derive(Clone, Debug)]
struct ClassVTableInfo {
    /// Class name this vtable is for
    class_name: String,
    /// All vtable entries (inherited + declared), in vtable order
    entries: Vec<VTableEntry>,
    /// Direct polymorphic base class name (for single inheritance chain)
    /// For multiple inheritance, see secondary_vtables
    base_class: Option<String>,
    /// True if class is abstract (has any pure virtual methods)
    is_abstract: bool,
    /// Secondary vtables for multiple inheritance (base class -> vtable entries)
    /// These are separate vtables for non-primary polymorphic bases
    #[allow(dead_code)]
    secondary_vtables: Vec<(String, Vec<VTableEntry>)>,
}

#[derive(Clone)]
struct BaseInfo {
    name: String,
    is_virtual: bool,
}

#[derive(Debug)]
enum BaseAccess {
    DirectField(String),
    FieldChain(String),
    VirtualPtr(String),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ModuleDeclVisibility {
    Public,
    Crate,
    Super,
    Private,
}

/// Information about a single bit field within a packed group.
#[derive(Clone, Debug)]
struct BitFieldInfo {
    /// Name of the original field
    field_name: String,
    /// Original type (for return type in accessor)
    original_type: CppType,
    /// Width in bits
    width: u32,
    /// Offset within the storage unit (in bits)
    offset: u32,
    /// Access specifier
    access: AccessSpecifier,
}

/// A group of consecutive bit fields packed into a single storage unit.
#[derive(Clone, Debug)]
struct BitFieldGroup {
    /// Fields in this group
    fields: Vec<BitFieldInfo>,
    /// Total bits used
    total_bits: u32,
    /// Index of this group (for generating _bitfield_0, _bitfield_1, etc.)
    group_index: usize,
}

impl BitFieldGroup {
    /// Get the smallest Rust unsigned integer type that can hold all bits.
    fn storage_type(&self) -> &'static str {
        match self.total_bits {
            0..=8 => "u8",
            9..=16 => "u16",
            17..=32 => "u32",
            33..=64 => "u64",
            _ => "u128",
        }
    }
}

#[derive(Clone, Debug)]
struct MethodOverloadInfo {
    rust_name: String,
    param_types: Vec<CppType>,
    return_type: CppType,
    is_const: bool,
    is_static: bool,
}

#[derive(Clone, Debug)]
struct FunctionOverloadInfo {
    rust_name: String,
    param_types: Vec<CppType>,
    return_type: CppType,
    is_variadic: bool,
}

/// Rust code generator that works directly with Clang AST.
pub struct AstCodeGen {
    output: String,
    indent: usize,
    /// Diagnostic mode: when enabled, log problematic AST nodes and type conversions
    /// Enable via FRAGILE_DIAGNOSTIC=1 environment variable
    diagnostic_mode: bool,
    /// Track variable names that are declared as reference types
    ref_vars: HashSet<String>,
    /// Track variables bound to const reference/pointer receivers. Used to recover
    /// const member-call preference when intermediate AST nodes drop qualifiers.
    const_receiver_vars: HashSet<String>,
    /// Track variable names that are declared as pointer types
    ptr_vars: HashSet<String>,
    /// Track variable names that are declared as array types
    arr_vars: HashSet<String>,
    /// When true, skip type suffixes for numeric literals (e.g., 5 instead of 5i32)
    skip_literal_suffix: bool,
    /// Current class being generated (for inherited member access)
    current_class: Option<String>,
    /// Classes that have virtual methods (need trait generation)
    polymorphic_classes: HashSet<String>,
    /// Map from class name to its base class names (supports multiple inheritance)
    class_bases: HashMap<String, Vec<BaseInfo>>,
    /// Map from class name to its transitive virtual bases
    virtual_bases: HashMap<String, Vec<String>>,
    /// Map from class name to its virtual methods
    virtual_methods: HashMap<String, Vec<VirtualMethodInfo>>,
    /// Complete vtable information per polymorphic class
    /// Built during analysis phase, used during code generation
    vtables: HashMap<String, ClassVTableInfo>,
    /// Track which methods are overridden in derived classes
    /// Key: (class_name, method_name), Value: original declaring class
    method_overrides: HashMap<(String, String), String>,
    /// Map from (class_name, member_name) to global variable name for static members
    static_members: HashMap<(String, String), String>,
    /// Track global variable names (require unsafe access)
    global_vars: HashSet<String>,
    /// Map from original variable name to prefixed global variable name
    /// This is needed to resolve DeclRefExpr references to globals with __gv_ prefix
    global_var_mapping: HashMap<String, String>,
    /// Namespace path where each generated global variable symbol (`__gv_*`) is defined.
    /// Used to qualify global references from sibling/child namespaces.
    global_var_namespace_paths: HashMap<String, Vec<String>>,
    /// Declared C++ type for each generated global variable name (`__gv_*`).
    global_var_types: HashMap<String, CppType>,
    /// Local variables in current function (parameters and locals)
    /// Used to determine whether a DeclRefExpr should use local or global variable
    local_vars: HashSet<String>,
    /// Lexically scoped local-variable activation counts (used for shadowing-sensitive
    /// lookup decisions such as function-static vs local DeclRefExpr resolution).
    scoped_local_var_counts: HashMap<String, usize>,
    /// Stack of local names declared in each active lexical scope.
    scoped_local_scope_stack: Vec<Vec<String>>,
    /// Per-identifier pointer-typed local declaration state stack.
    /// The last entry is the currently visible pointer-ness for that local name.
    scoped_local_ptr_state: HashMap<String, Vec<bool>>,
    /// Stack of identifier names that had pointer-state hints declared in each scope.
    scoped_local_ptr_scope_stack: Vec<Vec<String>>,
    /// Function-scope static local variables in current function: source name -> generated static name.
    /// These require `unsafe` access just like globals.
    function_static_var_mapping: HashMap<String, String>,
    /// Current function identifier used for generating unique local-static symbol names.
    current_function_ident: Option<String>,
    /// Monotonic counter for local-static symbol uniqueness.
    function_static_counter: usize,
    /// Current namespace path during code generation (for relative path computation)
    /// Each entry is (namespace_name, is_inline) where is_inline indicates C++ inline namespaces
    current_namespace: Vec<(String, bool)>,
    /// When true, use __self instead of self for this expressions
    use_ctor_self: bool,
    /// Current method return type (for reference return handling)
    current_return_type: Option<CppType>,
    /// Map from class name to its field names (for constructor generation)
    class_fields: HashMap<String, Vec<(String, CppType)>>,
    /// Map from class name to its constructor signatures: class_name -> [(ctor_suffix, param_types)]
    /// e.g., "_Bit_iterator_base" -> [("new_2", [Pointer<u64>, u64])]
    constructor_signatures: HashMap<String, Vec<(String, Vec<CppType>)>>,
    /// Collected std::variant types: maps enum name (e.g., "Variant_i32_f64") to its Rust type arguments (e.g., ["i32", "f64"])
    variant_types: HashMap<String, Vec<String>>,
    /// Counter for generating unique anonymous namespace names
    anon_namespace_counter: usize,
    /// Track already generated struct names to avoid duplicates from template instantiation
    generated_structs: HashSet<String>,
    /// Track generated enums (for CXXConstructExpr to avoid generating ::new_N())
    generated_enums: HashSet<String>,
    /// Map (enum_name, integer_value) → variant_name for switch-case generation
    enum_variant_map: HashMap<(String, i128), String>,
    /// Map enum name spellings to emitted Rust repr type (e.g., `u32`).
    /// Used for integral->enum cast lowering.
    enum_repr_types: HashMap<String, String>,
    /// Track already generated type aliases to avoid duplicates
    generated_aliases: HashSet<String>,
    /// Constructor parameter types: (class_name, num_args) → param types
    /// Used to add &mut for reference params at CXXConstructExpr call sites
    constructor_param_types: HashMap<(String, usize), Vec<CppType>>,
    /// Track type aliases that resolve to primitive types (e.g., pthread_mutex_t = usize)
    /// These need special handling since they can't have ::new_N() constructors
    primitive_aliases: HashSet<String>,
    /// Type alias resolution map: alias name -> resolved Rust target type.
    /// Used to resolve aggregate field layouts through typedef aliases.
    type_alias_targets: HashMap<String, String>,
    /// Track already generated module names to avoid duplicates (e.g., inline namespaces)
    generated_modules: HashSet<String>,
    /// Type names defined at the translation-unit (top) scope.
    /// Used to prevent auto-alias collisions with true global definitions.
    global_type_names: HashSet<String>,
    /// Top-level aliases for types defined in non-flattened namespaces.
    /// Key: unqualified Rust type name, Value: fully-qualified Rust path.
    namespace_type_alias_targets: HashMap<String, String>,
    /// Names that are defined in multiple namespaces and therefore can't be
    /// auto-aliased safely.
    namespace_type_alias_conflicts: HashSet<String>,
    /// Map from class/struct name to its bit field groups
    bit_field_groups: HashMap<String, Vec<BitFieldGroup>>,
    /// Track generated function signatures to handle overloads: name -> count
    generated_functions: HashMap<String, usize>,
    /// Internal helper/template signatures already emitted in this TU.
    /// Prevents re-emitting helper/template concrete bodies as faux overloads
    /// when multiple equivalent declarations/instantiations are visited.
    generated_helper_template_signatures: HashSet<String>,
    /// Global/free function overload metadata for call-site overload resolution.
    /// Key: base function name, Value: emitted overload entries.
    function_overloads: HashMap<String, Vec<FunctionOverloadInfo>>,
    /// Function names that have a definition in this translation unit.
    /// Used to suppress emitting duplicate extern declarations.
    defined_function_names: HashSet<String>,
    /// Function signatures that have a definition in this translation unit.
    /// Keyed by mangled symbol when available, otherwise by `(name + param lane)`.
    /// Used to avoid suppressing declaration-only overloads that differ by signature.
    defined_function_signatures: HashSet<String>,
    /// Global variable names that have a non-extern definition in this translation unit.
    /// Used to suppress emitting duplicate extern-style declarations from headers.
    defined_global_var_names: HashSet<String>,
    /// Function names seen as non-definition declarations in this translation unit.
    /// Used to identify externally declared C symbols that should be exported with C ABI.
    declared_function_names: HashSet<String>,
    /// Declared function parameter types keyed by `(function_name, arity)`.
    /// Used as a fallback when call-site function type metadata is degraded.
    declared_function_param_types: HashMap<(String, usize), Vec<CppType>>,
    /// Generated function parameter Rust types keyed by `(function_name, arity)`.
    /// Used when template-instantiated helper functions are emitted directly in
    /// this TU and call-site AST type metadata is degraded.
    generated_function_param_rust_types: HashMap<(String, usize), Vec<String>>,
    /// C extern declarations already emitted in this translation unit.
    emitted_extern_c_functions: HashSet<String>,
    /// Declaration symbols already emitted as extern wrappers in this TU.
    /// Uses mangled-name identity when available, otherwise `(name, arity)`.
    emitted_extern_c_decl_symbols: HashSet<String>,
    /// Exported link symbols already emitted in this translation unit.
    /// Prevents duplicate `#[no_mangle]`/`#[export_name]` function emissions.
    emitted_exported_function_symbols: HashSet<String>,
    /// Track actual Rust module nesting depth (excludes flattened namespaces like std, __)
    module_depth: usize,
    /// Track method names within current struct impl to handle overloads: name -> count
    current_struct_methods: HashMap<String, usize>,
    /// Per-class method overload metadata used to resolve member call suffixes.
    /// Key: class name (C++/Rust variants), Value: base method name -> overloads.
    class_method_overloads: HashMap<String, HashMap<String, Vec<MethodOverloadInfo>>>,
    /// Per-class method declaration parameter metadata used for argument
    /// normalization when method definitions appear later in TU order.
    /// Key: class name (C++/Rust variants), Value: base method name -> param lists.
    class_method_decl_param_types: HashMap<String, HashMap<String, Vec<Vec<CppType>>>>,
    /// Out-of-line class method definitions collected from top-level/namespace scope.
    /// Key: owning class name, Value: method-definition nodes.
    out_of_line_method_defs: HashMap<String, Vec<ClangNode>>,
    /// Function namespace path candidates collected from the AST.
    /// Key: unqualified function name, Value: namespace paths where it is defined.
    function_namespace_paths: HashMap<String, Vec<Vec<String>>>,
    /// Whether the currently-generated method is `const` in C++ terms.
    current_method_is_const: bool,
    /// Whether the currently-generated method is `static` in C++ terms.
    current_method_is_static: bool,
    /// Merged namespace contents: path -> list of child node indices from all occurrences
    /// Used for two-pass namespace merging (C++ can reopen namespaces, Rust cannot)
    merged_namespace_children: HashMap<String, Vec<usize>>,
    /// Reference to the original AST nodes (stored as indices into a collected vec)
    collected_nodes: Vec<Option<ClangNode>>,
    /// Template definitions: template name -> (template params, children nodes)
    /// Used to generate structs for template instantiations
    template_definitions: HashMap<String, (Vec<String>, Vec<ClangNode>)>,
    /// Template instantiations that need struct generation: full type name (e.g., "MyVec<int>")
    pending_template_instantiations: HashSet<String>,
    /// Function template definitions: template name -> (template params, return_type, params, body_node)
    fn_template_definitions: HashMap<String, FnTemplateInfo>,
    /// Cache of whether a function-template definition references template params
    /// in parameter type positions. Used in hot call-site matching paths.
    fn_template_param_dependency_cache: HashMap<String, bool>,
    /// Cache of function-template inference shape metadata used by
    /// `infer_fn_template_type_args` in hot call-site matching paths.
    fn_template_inference_shape_cache: RefCell<HashMap<String, Arc<FnTemplateInferenceShape>>>,
    /// Cache of whether function-template resolution for a template key can
    /// depend on call-argument literal bounds (non-type array-ref candidates).
    fn_template_requires_call_arg_bounds_cache: HashMap<String, bool>,
    /// Cache of normalized concrete signature shapes for function-template
    /// matching keyed by `(template_key, concrete_type_args)`.
    fn_template_concrete_match_shape_cache: HashMap<String, Arc<FnTemplateConcreteMatchShape>>,
    /// Cache of resolved function-template call candidates keyed by
    /// call-site signature shape.
    fn_template_call_resolution_cache: HashMap<String, Option<(String, Vec<String>)>>,
    /// Cache of function-template candidate-key vectors keyed by
    /// `(fn_name, namespace_path)` call-site lookup shape.
    fn_template_candidate_keys_cache: RefCell<HashMap<String, Arc<Vec<String>>>>,
    /// Cache of definition-backed function-template candidate-key vectors keyed by
    /// `(fn_name, namespace_path)` call-site lookup shape.
    fn_template_candidate_keys_with_defs_cache: RefCell<HashMap<String, Arc<Vec<String>>>>,
    /// Cache of whether definition-backed function-template candidate sets for
    /// a `(fn_name, namespace_path)` lookup shape require call-argument bound
    /// hashing in call-resolution keys.
    fn_template_candidate_requires_call_arg_bounds_cache: RefCell<HashMap<String, bool>>,
    /// Function-template keys indexed by unqualified leaf name to avoid scanning
    /// the full definition map for every call-site candidate lookup.
    fn_template_keys_by_leaf: HashMap<String, Vec<String>>,
    /// Pending function template instantiations: mangled name (e.g., "add_i32") -> (template_name, type_args)
    pending_fn_instantiations: HashMap<String, (String, Vec<String>, FnTemplateInfo)>,
    /// Class names for which we should skip vtable constant generation
    /// (because they have hand-written vtable stubs in the preamble)
    skip_vtable_generation: HashSet<String>,
    /// In variadic functions, maps the C va_list variable name to the Rust variadic parameter
    /// e.g., if C code has `va_list args`, this maps "args" -> "__va_args"
    va_list_mapping: Option<String>,
    /// Variadic template instantiations: mangled name -> instantiation node
    /// These are fully expanded functions from variadic templates (e.g., sum<int, int, int>)
    variadic_template_instantiations: HashMap<String, ClangNode>,
    /// Types used in the code that might need stub definitions generated
    /// Maps Rust type name -> C++ original name
    used_types: HashMap<String, String>,
    /// Generated opaque types for unresolved template parameters
    /// Maps opaque type name (e.g., "__Opaque_Key") to original param name (e.g., "_Key")
    opaque_types: HashMap<String, String>,
    /// Inline namespace aliases: maps parent namespace path to full path with inline namespace
    /// e.g., "std" -> "std::__1" means std::map should resolve to std::__1::map
    inline_namespace_aliases: HashMap<String, String>,
    /// LibTooling AST context for template method bodies
    /// Key: (class_name, method_name), Value: method info (params + body)
    libtooling_method_bodies: HashMap<(String, String), Vec<crate::libtooling::MethodInfo>>,
    /// Resolved field types from LibTooling template specializations
    /// Key: qualified type name (e.g., "std::pair"), Value: field info
    specialization_field_types: HashMap<String, crate::libtooling::SpecializationFieldInfo>,
    /// Resolved method signatures from LibTooling template specializations
    /// Key: qualified type name (e.g., "std::unique_ptr<int, std::default_delete<int>>")
    specialization_methods: HashMap<String, Vec<crate::libtooling::MethodSignature>>,
    /// Set of struct names that have been defined (to track for stub generation)
    defined_structs: HashSet<String>,
    /// Set of struct names that are referenced but not defined (need stub generation)
    referenced_but_undefined_structs: HashSet<String>,
    /// Function names that require unsafe calls (currently variadic C functions).
    unsafe_function_names: HashSet<String>,
    /// Top-level const names already emitted (used to deduplicate unnamed-enum constants).
    generated_top_level_consts: HashSet<String>,
    /// Anonymous union definitions discovered inside local var declarations.
    /// Key: generated Rust type name, Value: (field_name, field_type) list.
    anon_union_defs: HashMap<String, Vec<(String, CppType)>>,
    /// Set of Rust union type names generated in this translation unit.
    union_types: HashSet<String>,
    /// Union types whose fields require ManuallyDrop/non-Copy handling.
    /// Used to prevent deriving Copy on records embedding these unions.
    non_copy_union_types: HashSet<String>,
    /// Record/alias names known to be non-Clone in generated output.
    /// Used to avoid deriving Clone on aggregates that embed move-only fields.
    non_clone_record_types: HashSet<String>,
    /// Recovered member layouts for unnamed unions referenced by type but lacking
    /// explicit UnionDecl definitions in the AST.
    /// Key: generated Rust union type name, Value: (field_name, field_type) list.
    missing_union_member_types: HashMap<String, Vec<(String, CppType)>>,
    /// Current nested loop depth (`while`, `for`, `do`, range-for).
    loop_depth: usize,
    /// Stack of loop depths at each enclosing switch statement entry.
    /// Used to distinguish `break` for switch from `break` for nested loops.
    switch_loop_depth_stack: Vec<usize>,
    /// Stack of synthetic per-match-arm loop depths.
    /// A switch-level `break` lowers to `break;` from this synthetic loop so
    /// it can skip the rest of the current arm without exiting enclosing loops.
    switch_arm_loop_depth_stack: Vec<usize>,
    /// Active goto target rewrites inside the current function body.
    /// Maps C label names to Rust labeled-loop break targets.
    active_goto_break_labels: HashMap<String, String>,
    /// Unresolved non-local variable references seen while lowering the current
    /// function body. These are synthesized as function-scope fallback statics.
    current_function_unresolved_static_refs: RefCell<HashMap<String, CppType>>,
    /// Insertion point just after current function signature opening brace.
    /// Used to inject fallback statics ahead of body statements.
    current_function_body_insert_pos: Option<usize>,
}

/// Information about a function template definition
#[derive(Clone)]
struct FnTemplateInfo {
    /// Template type parameters (e.g., ["T", "U"])
    template_params: Vec<String>,
    /// Return type (may contain template parameter references)
    return_type: CppType,
    /// Parameter names and types
    params: Vec<(String, CppType)>,
    /// The function body (CompoundStmt node), if available
    body: Option<ClangNode>,
    /// Whether the function is noexcept (reserved for future use)
    #[allow(dead_code)]
    is_noexcept: bool,
}

#[derive(Clone)]
struct FnTemplateInferenceShape {
    /// Earliest parameter position where each template parameter appears.
    template_param_first_param_positions: Vec<Option<usize>>,
    /// Whether each template parameter appears in the return type but not in
    /// parameter patterns.
    template_param_appears_in_return: Vec<bool>,
    has_parameter_pack: bool,
    has_unsized_array_ref_param: bool,
    has_non_type_param_candidate: bool,
}

#[derive(Clone)]
struct FnTemplateConcreteMatchShape {
    param_types_normalized: Vec<String>,
    return_type_normalized: String,
}

#[derive(Clone)]
struct SwitchArm<'a> {
    values: Vec<i128>,
    body: Vec<&'a ClangNode>,
    is_default: bool,
}

