    /// Drop degraded `();` artifact lines that are emitted as pseudo-fields
    /// inside `let mut __self = Self { ... }` literals.
    fn normalize_struct_literal_unit_entry_artifacts(code: &str) -> String {
        if !code.contains("let mut __self = Self {") || !code.contains("();") {
            return code.to_string();
        }

        let lines: Vec<&str> = code.lines().collect();
        if lines.is_empty() {
            return code.to_string();
        }
        let mut out = String::with_capacity(code.len());
        let mut in_self_literal = false;
        let mut literal_depth: i32 = 0;

        for line in lines {
            let trimmed = line.trim();
            if !in_self_literal && line.contains("let mut __self = Self {") {
                in_self_literal = true;
                literal_depth = 1;
                out.push_str(line);
                out.push('\n');
                continue;
            }

            if in_self_literal {
                if trimmed != "();" {
                    out.push_str(line);
                    out.push('\n');
                }
                literal_depth += line.chars().filter(|c| *c == '{').count() as i32;
                literal_depth -= line.chars().filter(|c| *c == '}').count() as i32;
                if literal_depth <= 0 || trimmed.ends_with("};") {
                    in_self_literal = false;
                    literal_depth = 0;
                }
                continue;
            }

            out.push_str(line);
            out.push('\n');
        }

        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    /// Repair malformed reserve-call cast artifacts like
    /// `vec.reserve((unsafe { (*x) as i32).size() });`.
    fn normalize_malformed_unsafe_deref_size_casts(code: &str) -> String {
        if !code.contains(".reserve((unsafe { (*") || !code.contains(") as i32).size() });") {
            return code.to_string();
        }

        let mut out = String::with_capacity(code.len());
        for line in code.lines() {
            let mut rewritten = line.to_string();
            let marker = ".reserve((unsafe { (*";
            let suffix = ") as i32).size() });";
            if let Some(start) = rewritten.find(marker) {
                let expr_start = start + marker.len();
                if let Some(expr_rel_end) = rewritten[expr_start..].find(suffix) {
                    let expr_end = expr_start + expr_rel_end;
                    let expr = rewritten[expr_start..expr_end].trim();
                    if !expr.is_empty() {
                        let replace_end = expr_end + suffix.len();
                        let replacement =
                            format!(".reserve(unsafe {{ (*{}).size() }});", expr);
                        rewritten.replace_range(start..replace_end, &replacement);
                    }
                }
            }
            out.push_str(&rewritten);
            out.push('\n');
        }
        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    fn normalize_unresolved_compare_calls_to_compare_u64(code: &str) -> String {
        if code.contains("fn compare(")
            || !code.contains("compare(")
            || !code.contains("fn compare_u64(")
        {
            return code.to_string();
        }
        let mut out = String::with_capacity(code.len());
        for line in code.lines() {
            let mut rewritten = String::with_capacity(line.len());
            let mut idx = 0usize;
            while let Some(rel) = line[idx..].find("compare(") {
                let start = idx + rel;
                let left_ok = if start == 0 {
                    true
                } else {
                    let prev = line[..start].chars().next_back().unwrap();
                    !Self::is_identifier_char(prev) && prev != ':' && prev != '.'
                };
                rewritten.push_str(&line[idx..start]);
                if left_ok {
                    rewritten.push_str("compare_u64(");
                } else {
                    rewritten.push_str("compare(");
                }
                idx = start + "compare(".len();
            }
            rewritten.push_str(&line[idx..]);
            out.push_str(&rewritten);
            out.push('\n');
        }
        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    fn ensure_compare_swap_helpers(code: &str) -> String {
        fn has_free_function_named(code: &str, name: &str) -> bool {
            let prefixes = [
                "pub fn ",
                "pub unsafe fn ",
                "fn ",
                "unsafe fn ",
                "pub extern \"C\" fn ",
                "pub unsafe extern \"C\" fn ",
            ];
            let needle = format!("{}(", name);
            for line in code.lines() {
                let trimmed = line.trim_start();
                let mut matched = false;
                for prefix in prefixes {
                    if let Some(rest) = trimmed.strip_prefix(prefix) {
                        if rest.starts_with(&needle) {
                            matched = true;
                            break;
                        }
                    }
                }
                if !matched {
                    continue;
                }
                // Methods inside impl blocks usually include `self` in params.
                let Some(open_idx) = trimmed.find('(') else {
                    continue;
                };
                let Some(close_idx) = AstCodeGen::find_matching_close_paren(trimmed, open_idx)
                else {
                    continue;
                };
                let params = &trimmed[open_idx + 1..close_idx];
                let is_method_like = params.split(',').any(|p| {
                    let t = p.trim();
                    t == "self" || t == "&self" || t == "&mut self"
                });
                if !is_method_like {
                    return true;
                }
            }
            false
        }

        let need_compare = code.contains("compare(") && !has_free_function_named(code, "compare");
        let need_swap = code.contains("swap(") && !has_free_function_named(code, "swap");
        let need_compare_u64 =
            code.contains("compare_u64(") && !has_free_function_named(code, "compare_u64");
        let need_compare_u64_u64 = code.contains("compare_u64_u64(")
            && !has_free_function_named(code, "compare_u64_u64");
        if !need_compare && !need_swap && !need_compare_u64 && !need_compare_u64_u64 {
            return code.to_string();
        }

        let mut helper = String::new();
        if need_compare {
            helper.push_str(
                "#[inline]\npub fn compare<T: PartialOrd>(a: T, b: T) -> i32 {\n    if a < b { -1 } else if a > b { 1 } else { 0 }\n}\n\n",
            );
        }
        if need_swap {
            helper.push_str("#[inline]\npub fn swap<T>(a: &mut T, b: &mut T) { std::mem::swap(a, b); }\n\n");
        }
        if need_compare_u64 {
            helper.push_str("#[inline]\npub fn compare_u64(a: u64, b: u64) -> i32 { compare(a, b) }\n\n");
        }
        if need_compare_u64_u64 {
            helper.push_str(
                "#[inline]\npub fn compare_u64_u64(a: u64, b: u64) -> i32 { compare(a, b) }\n\n",
            );
        }

        if let Some(insert_at) = code.find("use std::io::Write;") {
            let mut out = String::with_capacity(code.len() + helper.len());
            out.push_str(&code[..insert_at]);
            out.push_str(&helper);
            out.push_str(&code[insert_at..]);
            return out;
        }
        format!("{}{}", helper, code)
    }

    fn normalize_unresolved_size_helper_calls(code: &str) -> String {
        fn has_free_size_fn(code: &str) -> bool {
            let prefixes = [
                "pub fn size(",
                "pub unsafe fn size(",
                "fn size(",
                "unsafe fn size(",
                "pub extern \"C\" fn size(",
                "pub unsafe extern \"C\" fn size(",
            ];
            for line in code.lines() {
                let trimmed = line.trim_start();
                if !prefixes.iter().any(|p| trimmed.starts_with(p)) {
                    continue;
                }
                let Some(open_idx) = trimmed.find('(') else {
                    continue;
                };
                let Some(close_idx) = AstCodeGen::find_matching_close_paren(trimmed, open_idx)
                else {
                    continue;
                };
                let params = &trimmed[open_idx + 1..close_idx];
                let is_method_like = params.split(',').any(|p| {
                    let t = p.trim();
                    t == "self" || t == "&self" || t == "&mut self"
                });
                if !is_method_like {
                    return true;
                }
            }
            false
        }

        if (!code.contains("__gv_size(") || code.contains("fn __gv_size("))
            && (!code.contains("size(") || has_free_size_fn(code))
        {
            return code.to_string();
        }
        let mut out = String::with_capacity(code.len());
        for line in code.lines() {
            let mut rewritten = line.to_string();
            for helper_name in ["__gv_size", "size"] {
                if helper_name == "size" && has_free_size_fn(code) {
                    continue;
                }
                let mut idx = 0usize;
                let marker = format!("{}(", helper_name);
                while let Some(rel) = rewritten[idx..].find(&marker) {
                    let start = idx + rel;
                    let prefix = rewritten[..start].trim_end();
                    if prefix.ends_with("fn") {
                        idx = start + marker.len();
                        continue;
                    }
                    if helper_name == "size" {
                        let left_ok = if start == 0 {
                            true
                        } else {
                            let prev = rewritten[..start].chars().next_back().unwrap();
                            !Self::is_identifier_char(prev) && prev != ':' && prev != '.'
                        };
                        if !left_ok {
                            idx = start + marker.len();
                            continue;
                        }
                    }
                    let args_start = start + marker.len();
                    let Some(close_idx) = Self::find_matching_close_paren(&rewritten, args_start - 1)
                    else {
                        break;
                    };
                    let args = rewritten[args_start..close_idx].trim();
                    if args.is_empty() {
                        idx = close_idx + 1;
                        continue;
                    }
                    let replacement = if helper_name == "size"
                        && (args == "self"
                            || args == "&self"
                            || args == "&mut self"
                            || args.starts_with("self.")
                            || args.starts_with("(*self)."))
                    {
                        "self.size()".to_string()
                    } else {
                        format!("({}).size()", args)
                    };
                    rewritten.replace_range(start..close_idx + 1, &replacement);
                    idx = start + replacement.len();
                }
            }
            out.push_str(&rewritten);
            out.push('\n');
        }
        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    /// Repair degraded `sizeof(...)` artifacts that can collapse to a bare
    /// `size` token in `safe_size(...)` helpers.
    fn normalize_unresolved_size_constant_tokens(code: &str) -> String {
        if !code.contains("safe_size(") || !code.contains("size") {
            return code.to_string();
        }

        fn collect_param_names(signature_line: &str) -> HashSet<String> {
            let mut names = HashSet::new();
            let Some(open_idx) = signature_line.find('(') else {
                return names;
            };
            let Some(close_idx) = AstCodeGen::find_matching_close_paren(signature_line, open_idx)
            else {
                return names;
            };
            let params_src = &signature_line[open_idx + 1..close_idx];
            for param in AstCodeGen::split_top_level_list(params_src, ',') {
                let Some((lhs, _)) = param.split_once(':') else {
                    continue;
                };
                let mut name = lhs.trim();
                if let Some(stripped) = name.strip_prefix("mut ") {
                    name = stripped.trim();
                }
                if !name.is_empty() {
                    names.insert(name.trim_start_matches("r#").to_string());
                }
            }
            names
        }

        fn collect_local_let_names(lines: &[&str]) -> HashSet<String> {
            let mut names = HashSet::new();
            for line in lines {
                let trimmed = line.trim_start();
                let Some(after_let) = trimmed.strip_prefix("let ") else {
                    continue;
                };
                let mut rest = after_let.trim_start();
                if let Some(stripped) = rest.strip_prefix("mut ") {
                    rest = stripped.trim_start();
                }
                let ident: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c))
                    .collect();
                if !ident.is_empty() {
                    names.insert(ident.trim_start_matches("r#").to_string());
                }
            }
            names
        }

        fn replace_ident_token(line: &str, ident: &str, replacement: &str) -> String {
            if ident.is_empty() || !line.contains(ident) {
                return line.to_string();
            }
            let mut out = String::with_capacity(line.len() + replacement.len());
            let mut idx = 0usize;
            while let Some(rel) = line[idx..].find(ident) {
                let start = idx + rel;
                let end = start + ident.len();
                let left_ok = if start == 0 {
                    true
                } else {
                    !line[..start]
                        .chars()
                        .next_back()
                        .is_some_and(AstCodeGen::is_identifier_char)
                };
                let right_ok = if end >= line.len() {
                    true
                } else {
                    !line[end..]
                        .chars()
                        .next()
                        .is_some_and(AstCodeGen::is_identifier_char)
                };
                out.push_str(&line[idx..start]);
                if left_ok && right_ok {
                    out.push_str(replacement);
                } else {
                    out.push_str(ident);
                }
                idx = end;
            }
            out.push_str(&line[idx..]);
            out
        }

        let replacement = if code.contains("info_type") {
            "(std::mem::size_of::<info_type>() as u64)"
        } else {
            "(0u64)"
        };

        let lines: Vec<&str> = code.lines().collect();
        if lines.is_empty() {
            return code.to_string();
        }
        let mut out = String::with_capacity(code.len() + 32);
        let mut i = 0usize;
        while i < lines.len() {
            let line = lines[i];
            let trimmed = line.trim_end();
            let is_safe_size = (trimmed.contains(" fn safe_size(") || trimmed.starts_with("fn safe_size("))
                && trimmed.ends_with('{');
            if !is_safe_size {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let mut j = i;
            let mut depth = 0isize;
            while j < lines.len() {
                let current = lines[j];
                depth += current.chars().filter(|c| *c == '{').count() as isize;
                depth -= current.chars().filter(|c| *c == '}').count() as isize;
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            if j >= lines.len() || depth != 0 {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let body_lines: &[&str] = if j > i + 1 { &lines[i + 1..j] } else { &[] };
            let mut occupied = collect_param_names(trimmed);
            occupied.extend(collect_local_let_names(body_lines));

            out.push_str(line);
            out.push('\n');
            for body_line in body_lines {
                let rewritten = if occupied.contains("size") {
                    (*body_line).to_string()
                } else {
                    replace_ident_token(body_line, "size", replacement)
                };
                out.push_str(&rewritten);
                out.push('\n');
            }
            out.push_str(lines[j]);
            if j + 1 < lines.len() || code.ends_with('\n') {
                out.push('\n');
            }
            i = j + 1;
        }

        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    /// Degraded method-value lowering can emit `(obj.method).clone()` for
    /// no-arg methods. Rewrite these to direct method calls.
    fn normalize_noarg_method_clone_value_uses(code: &str) -> String {
        fn collect_noarg_method_names(code: &str) -> HashSet<String> {
            let mut out = HashSet::new();
            for line in code.lines() {
                let trimmed = line.trim_start();
                let is_fn = trimmed.starts_with("pub fn ")
                    || trimmed.starts_with("pub(crate) fn ")
                    || trimmed.starts_with("pub(super) fn ")
                    || trimmed.starts_with("fn ");
                if !is_fn {
                    continue;
                }
                let Some(fn_idx) = trimmed.find("fn ") else {
                    continue;
                };
                let name_src = &trimmed[fn_idx + "fn ".len()..];
                let name: String = name_src
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c))
                    .collect();
                if name.is_empty() {
                    continue;
                }
                let Some(open_idx_rel) = name_src.find('(') else {
                    continue;
                };
                let open_idx = fn_idx + "fn ".len() + open_idx_rel;
                let Some(close_idx) = AstCodeGen::find_matching_close_paren(trimmed, open_idx)
                else {
                    continue;
                };
                let params = trimmed[open_idx + 1..close_idx].trim();
                if params.is_empty()
                    || params == "self"
                    || params == "&self"
                    || params == "&mut self"
                {
                    out.insert(name);
                }
            }
            out
        }

        if !code.contains(".clone()") {
            return code.to_string();
        }
        let mut noarg_methods: Vec<String> =
            collect_noarg_method_names(code).into_iter().collect();
        if noarg_methods.is_empty() {
            return code.to_string();
        }
        noarg_methods.sort_by(|a, b| b.len().cmp(&a.len()).then(a.cmp(b)));

        let mut out = String::with_capacity(code.len());
        for line in code.lines() {
            let mut rewritten = line.to_string();
            for method in &noarg_methods {
                let pat_plain = format!(".{}).clone()", method);
                if rewritten.contains(&pat_plain) {
                    rewritten = rewritten.replace(&pat_plain, &format!(".{}())", method));
                }
                let pat_unsafe = format!(".{} }}).clone()", method);
                if rewritten.contains(&pat_unsafe) {
                    rewritten = rewritten.replace(&pat_unsafe, &format!(".{}() }})", method));
                }
                let pat_stmt = format!(".{};", method);
                if rewritten.contains(&pat_stmt) {
                    rewritten = rewritten.replace(&pat_stmt, &format!(".{}();", method));
                }
                let pat_block = format!(".{} }}", method);
                if rewritten.contains(&pat_block) {
                    rewritten = rewritten.replace(&pat_block, &format!(".{}() }}", method));
                }
                let pat_cast = format!(".{} as ", method);
                if rewritten.contains(&pat_cast) {
                    rewritten = rewritten.replace(&pat_cast, &format!(".{}() as ", method));
                }
                let pat_comma = format!(".{},", method);
                if rewritten.contains(&pat_comma) {
                    rewritten = rewritten.replace(&pat_comma, &format!(".{}(),", method));
                }
            }
            out.push_str(&rewritten);
            out.push('\n');
        }
        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    /// Cast direct `return` expressions to primitive numeric return types to
    /// recover width/sign mismatches from degraded lowering.
    fn normalize_primitive_numeric_return_casts(code: &str) -> String {
        fn is_numeric_primitive(ty: &str) -> bool {
            matches!(
                ty,
                "u8"
                    | "u16"
                    | "u32"
                    | "u64"
                    | "u128"
                    | "usize"
                    | "i8"
                    | "i16"
                    | "i32"
                    | "i64"
                    | "i128"
                    | "isize"
                    | "f32"
                    | "f64"
            )
        }

        fn parse_numeric_return_type(signature_line: &str) -> Option<String> {
            let arrow = signature_line.rfind("->")?;
            let mut ret_ty = signature_line[arrow + 2..].trim();
            ret_ty = ret_ty.trim_end_matches('{').trim();
            if ret_ty.is_empty() || ret_ty.contains(' ') {
                return None;
            }
            if is_numeric_primitive(ret_ty) {
                Some(ret_ty.to_string())
            } else {
                None
            }
        }

        let lines: Vec<&str> = code.lines().collect();
        if lines.is_empty() {
            return code.to_string();
        }

        let mut out = String::with_capacity(code.len());
        let mut i = 0usize;
        while i < lines.len() {
            let line = lines[i];
            let trimmed = line.trim_end();
            let is_fn_start =
                (trimmed.contains(" fn ") || trimmed.starts_with("fn ")) && trimmed.ends_with('{');
            if !is_fn_start {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let Some(ret_ty) = parse_numeric_return_type(trimmed) else {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            };

            let mut j = i;
            let mut depth = 0isize;
            while j < lines.len() {
                let current = lines[j];
                depth += current.chars().filter(|c| *c == '{').count() as isize;
                depth -= current.chars().filter(|c| *c == '}').count() as isize;
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            if j >= lines.len() || depth != 0 {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            out.push_str(lines[i]);
            out.push('\n');
            let body_lines: &[&str] = if j > i + 1 { &lines[i + 1..j] } else { &[] };
            let mut placeholder_locals: HashSet<String> = HashSet::new();
            for body_line in body_lines {
                let trimmed_body = body_line.trim();
                let Some(after_let) = trimmed_body.strip_prefix("let mut ") else {
                    continue;
                };
                let name: String = after_let
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c))
                    .collect();
                if name.is_empty() {
                    continue;
                }
                if trimmed_body.contains(": UnknownTagAutoType")
                    || trimmed_body.contains(": UnknownTagEnumType")
                    || trimmed_body.contains("= unsafe { std::mem::zeroed() }")
                {
                    placeholder_locals.insert(name);
                }
            }
            for body_line in body_lines {
                let trimmed_body = body_line.trim();
                let mut rewritten = body_line.to_string();
                if let Some(inner) = trimmed_body.strip_prefix("return (") {
                    if let Some(cast_pos) = inner.find(") as ") {
                        let local_name = inner[..cast_pos].trim();
                        if placeholder_locals.contains(local_name) {
                            let indent_len =
                                body_line.len().saturating_sub(body_line.trim_start().len());
                            rewritten =
                                format!("{}return Default::default();", &body_line[..indent_len]);
                            out.push_str(&rewritten);
                            out.push('\n');
                            continue;
                        }
                    }
                }
                if let Some(expr_src) = trimmed_body
                    .strip_prefix("return ")
                    .and_then(|s| s.strip_suffix(';'))
                {
                    let expr = expr_src.trim();
                    if !expr.is_empty()
                        && !expr.contains(" as ")
                        && !expr.contains('{')
                        && !expr.contains('}')
                        && !expr.contains("Default::default()")
                        && !expr.starts_with("std::ptr::")
                        && !expr.starts_with("unsafe {")
                    {
                        let indent_len = body_line.len().saturating_sub(body_line.trim_start().len());
                        rewritten = format!(
                            "{}return ({}) as {};",
                            &body_line[..indent_len],
                            expr,
                            ret_ty
                        );
                    }
                }
                out.push_str(&rewritten);
                out.push('\n');
            }
            out.push_str(lines[j]);
            if j + 1 < lines.len() || code.ends_with('\n') {
                out.push('\n');
            }
            i = j + 1;
        }

        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    /// Wrap arithmetic `&expr` operands in `__gv_min/__gv_max` calls as
    /// `&(expr)` so they lower to pointer arguments correctly.
    fn normalize_gv_min_max_reference_arguments(code: &str) -> String {
        fn is_simple_ref_target(expr: &str) -> bool {
            if expr.is_empty() {
                return true;
            }
            expr.chars().all(|ch| {
                AstCodeGen::is_identifier_char(ch)
                    || matches!(ch, ':' | '<' | '>' | '[' | ']' | '(' | ')' | '#')
            })
        }

        fn rewrite_call(line: &str, fn_name: &str) -> String {
            let marker = format!("{}(", fn_name);
            if !line.contains(&marker) {
                return line.to_string();
            }
            let mut rewritten = line.to_string();
            let mut idx = 0usize;
            while let Some(rel) = rewritten[idx..].find(&marker) {
                let start = idx + rel;
                let args_start = start + marker.len();
                let Some(close_idx) = AstCodeGen::find_matching_close_paren(&rewritten, args_start - 1)
                else {
                    break;
                };
                let args_src = rewritten[args_start..close_idx].trim();
                let args = AstCodeGen::split_top_level_list(args_src, ',');
                if args.is_empty() {
                    idx = close_idx + 1;
                    continue;
                }

                let mut changed = false;
                let mut normalized_args: Vec<String> = Vec::with_capacity(args.len());
                for arg in args {
                    let trimmed = arg.trim();
                    if let Some(rest) = trimmed.strip_prefix('&') {
                        let rest_trim = rest.trim();
                        let has_operator = rest_trim.chars().any(|ch| {
                            matches!(ch, '+' | '-' | '*' | '/' | '%' | '|' | '&' | '^')
                        }) || rest_trim.contains("<<")
                            || rest_trim.contains(">>");
                        if !rest_trim.starts_with('(') && has_operator && !is_simple_ref_target(rest_trim) {
                            normalized_args.push(format!("&({})", rest_trim));
                            changed = true;
                            continue;
                        }
                    }
                    normalized_args.push(trimmed.to_string());
                }
                if !changed {
                    idx = close_idx + 1;
                    continue;
                }
                let replacement = format!("{}({})", fn_name, normalized_args.join(", "));
                rewritten.replace_range(start..close_idx + 1, &replacement);
                idx = start + replacement.len();
            }
            rewritten
        }

        if !code.contains("__gv_min(") && !code.contains("__gv_max(") {
            return code.to_string();
        }
        let mut out = String::with_capacity(code.len());
        for line in code.lines() {
            let mut rewritten = rewrite_call(line, "__gv_min");
            rewritten = rewrite_call(&rewritten, "__gv_max");
            out.push_str(&rewritten);
            out.push('\n');
        }
        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    /// Normalize obvious method-surface mismatches using locally known binding
    /// types (for example array `.add(...)` and raw-pointer `.expect(...)`).
    fn normalize_typed_binding_method_surface_mismatches(code: &str) -> String {
        fn collect_typed_bindings(
            signature_line: &str,
            body_lines: &[&str],
        ) -> HashMap<String, String> {
            let mut out = HashMap::new();

            if let Some(open_idx) = signature_line.find('(') {
                if let Some(close_idx) = AstCodeGen::find_matching_close_paren(signature_line, open_idx)
                {
                    let params_src = &signature_line[open_idx + 1..close_idx];
                    for param in AstCodeGen::split_top_level_list(params_src, ',') {
                        let Some((lhs, rhs)) = param.split_once(':') else {
                            continue;
                        };
                        let mut name = lhs.trim();
                        if let Some(stripped) = name.strip_prefix("mut ") {
                            name = stripped.trim();
                        }
                        let name = name.trim_start_matches("r#").trim();
                        if name.is_empty() || matches!(name, "self" | "&self" | "&mut self") {
                            continue;
                        }
                        let ty = rhs.trim();
                        if !ty.is_empty() {
                            out.insert(name.to_string(), ty.to_string());
                        }
                    }
                }
            }

            for line in body_lines {
                let trimmed = line.trim_start();
                let Some(after_let) = trimmed.strip_prefix("let ") else {
                    continue;
                };
                let mut rest = after_let.trim_start();
                if let Some(stripped) = rest.strip_prefix("mut ") {
                    rest = stripped.trim_start();
                }
                let ident: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c))
                    .collect();
                if ident.is_empty() {
                    continue;
                }
                let Some(colon_idx) = rest.find(':') else {
                    continue;
                };
                let ty_src = rest[colon_idx + 1..]
                    .split('=')
                    .next()
                    .unwrap_or("")
                    .trim();
                if !ty_src.is_empty() {
                    out.insert(ident.trim_start_matches("r#").to_string(), ty_src.to_string());
                }
            }

            out
        }

        fn parse_struct_fields(code: &str) -> HashMap<String, HashSet<String>> {
            let lines: Vec<&str> = code.lines().collect();
            let mut out = HashMap::new();
            let mut i = 0usize;
            while i < lines.len() {
                let trimmed = lines[i].trim_start();
                let Some(rest) = trimmed
                    .strip_prefix("pub struct ")
                    .or_else(|| trimmed.strip_prefix("struct "))
                else {
                    i += 1;
                    continue;
                };
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                if name.is_empty() || !trimmed.ends_with('{') {
                    i += 1;
                    continue;
                }

                let mut fields: HashSet<String> = HashSet::new();
                let mut depth = 1isize;
                let mut j = i + 1;
                while j < lines.len() && depth > 0 {
                    let current = lines[j];
                    let current_trim = current.trim();
                    if depth == 1
                        && !current_trim.starts_with("//")
                        && !current_trim.starts_with("///")
                        && !current_trim.starts_with("#[")
                    {
                        let mut field_src = current_trim;
                        if let Some(rest) = field_src.strip_prefix("pub(") {
                            if let Some(close_idx) = rest.find(')') {
                                field_src = rest[close_idx + 1..].trim_start();
                            }
                        } else if let Some(rest) = field_src.strip_prefix("pub ") {
                            field_src = rest.trim_start();
                        }
                        if let Some((lhs, _)) = field_src.split_once(':') {
                            let field = lhs.trim().trim_start_matches("r#");
                            if !field.is_empty() {
                                fields.insert(field.to_string());
                            }
                        }
                    }
                    depth += current.chars().filter(|c| *c == '{').count() as isize;
                    depth -= current.chars().filter(|c| *c == '}').count() as isize;
                    j += 1;
                }
                out.insert(name.trim_start_matches("r#").to_string(), fields);
                i = j;
            }
            out
        }

        fn parse_struct_cell_fields(code: &str) -> HashMap<String, HashSet<String>> {
            let lines: Vec<&str> = code.lines().collect();
            let mut out = HashMap::new();
            let mut i = 0usize;
            while i < lines.len() {
                let trimmed = lines[i].trim_start();
                let Some(rest) = trimmed
                    .strip_prefix("pub struct ")
                    .or_else(|| trimmed.strip_prefix("struct "))
                else {
                    i += 1;
                    continue;
                };
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                if name.is_empty() || !trimmed.ends_with('{') {
                    i += 1;
                    continue;
                }

                let mut fields: HashSet<String> = HashSet::new();
                let mut depth = 1isize;
                let mut j = i + 1;
                while j < lines.len() && depth > 0 {
                    let current = lines[j];
                    let current_trim = current.trim();
                    if depth == 1
                        && !current_trim.starts_with("//")
                        && !current_trim.starts_with("///")
                        && !current_trim.starts_with("#[")
                    {
                        let mut field_src = current_trim;
                        if let Some(rest) = field_src.strip_prefix("pub(") {
                            if let Some(close_idx) = rest.find(')') {
                                field_src = rest[close_idx + 1..].trim_start();
                            }
                        } else if let Some(rest) = field_src.strip_prefix("pub ") {
                            field_src = rest.trim_start();
                        }
                        if let Some((lhs, rhs)) = field_src.split_once(':') {
                            let field = lhs.trim().trim_start_matches("r#");
                            let ty = rhs.trim().trim_end_matches(',').trim();
                            if !field.is_empty()
                                && (ty.contains("std::cell::Cell<")
                                    || ty.starts_with("rusty_Cell_"))
                            {
                                fields.insert(field.to_string());
                            }
                        }
                    }
                    depth += current.chars().filter(|c| *c == '{').count() as isize;
                    depth -= current.chars().filter(|c| *c == '}').count() as isize;
                    j += 1;
                }
                out.insert(name.trim_start_matches("r#").to_string(), fields);
                i = j;
            }
            out
        }

        fn parse_impl_target(line: &str) -> Option<String> {
            let trimmed = line.trim_start();
            let rest = trimmed.strip_prefix("impl ")?;
            if !trimmed.ends_with('{') {
                return None;
            }
            let target_src = rest.split('{').next()?.trim();
            let target_src = if let Some((_, rhs)) = target_src.split_once(" for ") {
                rhs.trim()
            } else {
                target_src
            };
            let token = target_src.split_whitespace().next().unwrap_or(target_src);
            let token = token.split('<').next().unwrap_or(token).trim();
            if token.is_empty() {
                None
            } else {
                Some(token.trim_start_matches("r#").to_string())
            }
        }

        fn collect_impl_target_per_line(lines: &[&str]) -> Vec<Option<String>> {
            let mut out = vec![None; lines.len()];
            let mut depth = 0i32;
            let mut stack: Vec<(i32, String)> = Vec::new();
            for (idx, line) in lines.iter().enumerate() {
                while stack
                    .last()
                    .is_some_and(|(start_depth, _)| *start_depth > depth)
                {
                    stack.pop();
                }
                out[idx] = stack.last().map(|(_, name)| name.clone());

                if let Some(target) = parse_impl_target(line) {
                    stack.push((depth + 1, target));
                }
                let open_count = line.chars().filter(|c| *c == '{').count() as i32;
                let close_count = line.chars().filter(|c| *c == '}').count() as i32;
                depth += open_count - close_count;
                if depth < 0 {
                    depth = 0;
                }
                while stack
                    .last()
                    .is_some_and(|(start_depth, _)| *start_depth > depth)
                {
                    stack.pop();
                }
            }
            out
        }

        fn canonical_type_name(raw: &str) -> Option<(String, bool)> {
            let mut ty = raw.trim();
            if ty.is_empty() {
                return None;
            }

            let mut pointer_like = false;
            loop {
                if let Some(rest) = ty.strip_prefix("&mut ") {
                    ty = rest.trim_start();
                    continue;
                }
                if let Some(rest) = ty.strip_prefix('&') {
                    ty = rest.trim_start();
                    continue;
                }
                if let Some(rest) = ty.strip_prefix("*mut ") {
                    ty = rest.trim_start();
                    pointer_like = true;
                    continue;
                }
                if let Some(rest) = ty.strip_prefix("*const ") {
                    ty = rest.trim_start();
                    pointer_like = true;
                    continue;
                }
                if let Some(rest) = ty.strip_prefix("mut ") {
                    ty = rest.trim_start();
                    continue;
                }
                break;
            }

            if let Some(open_idx) = ty.find('<') {
                let mut close_idx_opt: Option<usize> = None;
                let mut angle_depth = 0i32;
                for (idx, ch) in ty.char_indices().skip(open_idx) {
                    if ch == '<' {
                        angle_depth += 1;
                    } else if ch == '>' {
                        angle_depth -= 1;
                        if angle_depth == 0 {
                            close_idx_opt = Some(idx);
                            break;
                        }
                    }
                }
                if let Some(close_idx) = close_idx_opt {
                    let wrapper = ty[..open_idx]
                        .split_whitespace()
                        .last()
                        .unwrap_or("")
                        .trim();
                    let wrapper_leaf = wrapper
                        .rsplit("::")
                        .next()
                        .unwrap_or(wrapper)
                        .trim()
                        .trim_start_matches("r#");
                    let inner_src = &ty[open_idx + 1..close_idx];
                    let inner_ty = AstCodeGen::split_top_level_list(inner_src, ',')
                        .first()
                        .map(|s| s.trim())
                        .unwrap_or("");
                    if !inner_ty.is_empty() {
                        if matches!(
                            wrapper_leaf,
                            "Arc" | "Rc" | "Box" | "shared_ptr" | "unique_ptr" | "Weak"
                        ) {
                            if let Some((inner, _)) = canonical_type_name(inner_ty) {
                                return Some((inner, true));
                            }
                        } else if wrapper_leaf == "Option" {
                            if let Some((inner, inner_ptr_like)) = canonical_type_name(inner_ty) {
                                return Some((inner, pointer_like || inner_ptr_like));
                            }
                        }
                    }
                }
            }

            let token: String = ty
                .chars()
                .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == ':')
                .collect();
            if token.is_empty() {
                return None;
            }
            let leaf = token
                .rsplit("::")
                .next()
                .unwrap_or(token.as_str())
                .trim()
                .trim_start_matches("r#")
                .to_string();
            if leaf.is_empty() {
                None
            } else {
                Some((leaf, pointer_like))
            }
        }

        fn replace_receiver_call_with_value(
            line: &str,
            receiver: &str,
            method: &str,
            replacement: &str,
        ) -> String {
            let marker = format!("{}.{}(", receiver, method);
            if !line.contains(&marker) {
                return line.to_string();
            }
            let mut rewritten = line.to_string();
            let mut idx = 0usize;
            while let Some(rel) = rewritten[idx..].find(&marker) {
                let start = idx + rel;
                let open_idx = start + marker.len() - 1;
                let Some(close_idx) = AstCodeGen::find_matching_close_paren(&rewritten, open_idx)
                else {
                    break;
                };
                rewritten.replace_range(start..close_idx + 1, replacement);
                idx = start + replacement.len();
            }
            rewritten
        }

        fn replace_zero_arg_receiver_call_with_value(
            line: &str,
            receiver: &str,
            method: &str,
            replacement: &str,
        ) -> String {
            let marker = format!("{}.{}(", receiver, method);
            if !line.contains(&marker) {
                return line.to_string();
            }
            let mut rewritten = line.to_string();
            let mut idx = 0usize;
            while let Some(rel) = rewritten[idx..].find(&marker) {
                let start = idx + rel;
                let open_idx = start + marker.len() - 1;
                let Some(close_idx) = AstCodeGen::find_matching_close_paren(&rewritten, open_idx)
                else {
                    break;
                };
                let args_src = rewritten[open_idx + 1..close_idx].trim();
                if args_src.is_empty() {
                    rewritten.replace_range(start..close_idx + 1, replacement);
                    idx = start + replacement.len();
                } else {
                    idx = close_idx + 1;
                }
            }
            rewritten
        }

        let lines: Vec<&str> = code.lines().collect();
        if lines.is_empty() {
            return code.to_string();
        }
        let struct_fields = parse_struct_fields(code);
        let struct_cell_fields = parse_struct_cell_fields(code);
        let impl_targets = collect_impl_target_per_line(&lines);

        let mut out = String::with_capacity(code.len());
        let mut i = 0usize;
        while i < lines.len() {
            let line = lines[i];
            let trimmed = line.trim_end();
            let is_fn_start =
                (trimmed.contains(" fn ") || trimmed.starts_with("fn ")) && trimmed.ends_with('{');
            if !is_fn_start {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let mut j = i;
            let mut depth = 0isize;
            while j < lines.len() {
                let current = lines[j];
                depth += current.chars().filter(|c| *c == '{').count() as isize;
                depth -= current.chars().filter(|c| *c == '}').count() as isize;
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            if j >= lines.len() || depth != 0 {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let body_lines: &[&str] = if j > i + 1 { &lines[i + 1..j] } else { &[] };
            let bindings = collect_typed_bindings(trimmed, body_lines);
            let impl_target_name = impl_targets.get(i).and_then(|t| t.as_ref()).cloned();
            let mut binding_field_surfaces: Vec<(String, bool, Vec<String>, HashSet<String>)> =
                Vec::new();
            if let Some(target) = impl_target_name.as_deref() {
                if let Some(fields) = struct_fields.get(target) {
                    if !fields.is_empty() {
                        let mut field_list: Vec<String> = fields.iter().cloned().collect();
                        field_list.sort();
                        let cell_fields = struct_cell_fields
                            .get(target)
                            .cloned()
                            .unwrap_or_default();
                        binding_field_surfaces.push((
                            "self".to_string(),
                            false,
                            field_list,
                            cell_fields,
                        ));
                    }
                }
            }
            for (name, ty) in &bindings {
                let Some((canonical, pointer_like)) = canonical_type_name(ty) else {
                    continue;
                };
                let Some(fields) = struct_fields.get(&canonical) else {
                    continue;
                };
                if fields.is_empty() {
                    continue;
                }
                let mut field_list: Vec<String> = fields.iter().cloned().collect();
                field_list.sort();
                let cell_fields = struct_cell_fields
                    .get(&canonical)
                    .cloned()
                    .unwrap_or_default();
                binding_field_surfaces.push((name.clone(), pointer_like, field_list, cell_fields));
            }

            out.push_str(lines[i]);
            out.push('\n');
            for body_line in body_lines {
                let mut rewritten = body_line.to_string();
                for (name, ty) in &bindings {
                    let array_like = ty.starts_with('[');
                    let ptr_like = ty.starts_with("*mut ") || ty.starts_with("*const ");
                    if array_like {
                        rewritten = rewritten.replace(
                            &format!("{}.add(", name),
                            &format!("{}.as_mut_ptr().add(", name),
                        );
                        rewritten = rewritten.replace(
                            &format!("{}.sub(", name),
                            &format!("{}.as_mut_ptr().sub(", name),
                        );
                    }
                    if ptr_like {
                        rewritten =
                            rewritten.replace(&format!("{}.as_mut_ptr()", name), name.as_str());
                        rewritten =
                            rewritten.replace(&format!("{}.as_ptr()", name), name.as_str());
                        rewritten = replace_receiver_call_with_value(
                            &rewritten,
                            name,
                            "expect",
                            name,
                        );
                    }
                }
                for (name, pointer_like, fields, cell_fields) in &binding_field_surfaces {
                    for field in fields {
                        let direct_access = format!("{}.{}", name, field);
                        let direct_replacement = if cell_fields.contains(field) {
                            format!("{}.get()", direct_access)
                        } else {
                            direct_access
                        };
                        rewritten = replace_zero_arg_receiver_call_with_value(
                            &rewritten,
                            name,
                            field,
                            &direct_replacement,
                        );
                        let deref_receiver = format!("(*{})", name);
                        let deref_access = if *pointer_like || name == "self" {
                            format!("(*{}).{}", name, field)
                        } else {
                            format!("{}.{}", name, field)
                        };
                        let deref_replacement = if cell_fields.contains(field) {
                            format!("{}.get()", deref_access)
                        } else {
                            deref_access
                        };
                        rewritten = replace_zero_arg_receiver_call_with_value(
                            &rewritten,
                            &deref_receiver,
                            field,
                            &deref_replacement,
                        );
                    }
                }
                out.push_str(&rewritten);
                out.push('\n');
            }
            out.push_str(lines[j]);
            if j + 1 < lines.len() || code.ends_with('\n') {
                out.push('\n');
            }
            i = j + 1;
        }
        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    /// Rewrite parenthesized pointer-negation terms like `(!self.ptr_)` to
    /// explicit null checks. This complements `normalize_pointer_negation_conditions`
    /// for compound boolean expressions.
    fn normalize_parenthesized_pointer_negation_terms(code: &str) -> String {
        fn parse_struct_pointer_fields(code: &str) -> HashMap<String, HashSet<String>> {
            let lines: Vec<&str> = code.lines().collect();
            let mut out: HashMap<String, HashSet<String>> = HashMap::new();
            let mut i = 0usize;
            while i < lines.len() {
                let trimmed = lines[i].trim_start();
                let Some(rest) = trimmed
                    .strip_prefix("pub struct ")
                    .or_else(|| trimmed.strip_prefix("struct "))
                else {
                    i += 1;
                    continue;
                };
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                if name.is_empty() || !trimmed.ends_with('{') {
                    i += 1;
                    continue;
                }

                let mut depth = 1isize;
                let mut fields: HashSet<String> = HashSet::new();
                let mut j = i + 1;
                while j < lines.len() && depth > 0 {
                    let current = lines[j];
                    let current_trim = current.trim();
                    if depth == 1
                        && !current_trim.starts_with("//")
                        && !current_trim.starts_with("///")
                        && !current_trim.starts_with("#[")
                    {
                        let mut field_src = current_trim;
                        if let Some(rest) = field_src.strip_prefix("pub(") {
                            if let Some(close_idx) = rest.find(')') {
                                field_src = rest[close_idx + 1..].trim_start();
                            }
                        } else if let Some(rest) = field_src.strip_prefix("pub ") {
                            field_src = rest.trim_start();
                        }
                        if let Some((lhs, rhs)) = field_src.split_once(':') {
                            let field_name = lhs.trim().trim_start_matches("r#");
                            let field_ty = rhs.trim().trim_end_matches(',').trim();
                            if !field_name.is_empty()
                                && (field_ty.starts_with("*mut ")
                                    || field_ty.starts_with("*const "))
                            {
                                fields.insert(field_name.to_string());
                            }
                        }
                    }
                    depth += current.chars().filter(|c| *c == '{').count() as isize;
                    depth -= current.chars().filter(|c| *c == '}').count() as isize;
                    j += 1;
                }
                if !fields.is_empty() {
                    out.insert(name.trim_start_matches("r#").to_string(), fields);
                }
                i = j;
            }
            out
        }

        fn parse_impl_target(line: &str) -> Option<String> {
            let trimmed = line.trim_start();
            let rest = trimmed.strip_prefix("impl ")?;
            if !trimmed.ends_with('{') {
                return None;
            }
            let target_src = rest.split('{').next()?.trim();
            let target_src = if let Some((_, rhs)) = target_src.split_once(" for ") {
                rhs.trim()
            } else {
                target_src
            };
            let token = target_src.split_whitespace().next().unwrap_or(target_src);
            let token = token.split('<').next().unwrap_or(token).trim();
            if token.is_empty() {
                None
            } else {
                Some(token.trim_start_matches("r#").to_string())
            }
        }

        fn collect_impl_target_per_line(lines: &[&str]) -> Vec<Option<String>> {
            let mut out = vec![None; lines.len()];
            let mut depth = 0i32;
            let mut stack: Vec<(i32, String)> = Vec::new();
            for (idx, line) in lines.iter().enumerate() {
                while stack
                    .last()
                    .is_some_and(|(start_depth, _)| *start_depth > depth)
                {
                    stack.pop();
                }
                out[idx] = stack.last().map(|(_, name)| name.clone());

                if let Some(target) = parse_impl_target(line) {
                    stack.push((depth + 1, target));
                }

                let open_count = line.chars().filter(|c| *c == '{').count() as i32;
                let close_count = line.chars().filter(|c| *c == '}').count() as i32;
                depth += open_count - close_count;
                if depth < 0 {
                    depth = 0;
                }
                while stack
                    .last()
                    .is_some_and(|(start_depth, _)| *start_depth > depth)
                {
                    stack.pop();
                }
            }
            out
        }

        fn collect_pointer_bindings(signature_line: &str, body_lines: &[&str]) -> HashSet<String> {
            let mut out = HashSet::new();
            let Some(open_idx) = signature_line.find('(') else {
                return out;
            };
            let Some(close_idx) = AstCodeGen::find_matching_close_paren(signature_line, open_idx)
            else {
                return out;
            };
            let params_src = &signature_line[open_idx + 1..close_idx];
            for param in AstCodeGen::split_top_level_list(params_src, ',') {
                let Some((lhs, rhs)) = param.split_once(':') else {
                    continue;
                };
                let mut name = lhs.trim();
                if let Some(stripped) = name.strip_prefix("mut ") {
                    name = stripped.trim();
                }
                name = name.trim_start_matches("r#");
                let ty = rhs.trim();
                if !name.is_empty() && (ty.starts_with("*mut ") || ty.starts_with("*const ")) {
                    out.insert(name.to_string());
                }
            }
            for line in body_lines {
                let trimmed = line.trim_start();
                let Some(after_let) = trimmed.strip_prefix("let ") else {
                    continue;
                };
                let mut rest = after_let.trim_start();
                if let Some(stripped) = rest.strip_prefix("mut ") {
                    rest = stripped.trim_start();
                }
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                let Some(colon_idx) = rest.find(':') else {
                    continue;
                };
                let ty = rest[colon_idx + 1..]
                    .split('=')
                    .next()
                    .unwrap_or("")
                    .trim();
                if !name.is_empty() && (ty.starts_with("*mut ") || ty.starts_with("*const ")) {
                    out.insert(name.trim_start_matches("r#").to_string());
                }
            }
            out
        }

        fn is_pointer_expr(
            expr: &str,
            pointer_bindings: &HashSet<String>,
            pointer_fields: &HashSet<String>,
        ) -> bool {
            let mut trimmed = expr.trim();
            while is_fully_parenthesized_expr(trimmed) && trimmed.len() >= 2 {
                trimmed = trimmed[1..trimmed.len() - 1].trim();
            }
            if trimmed.is_empty() {
                return false;
            }
            if trimmed.contains(" as *mut ") || trimmed.contains(" as *const ") {
                return true;
            }
            let binding = trimmed.trim_start_matches("r#");
            if pointer_bindings.contains(binding) {
                return true;
            }
            if let Some(rest) = trimmed.strip_prefix("self.") {
                let field: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                return pointer_fields.contains(field.trim_start_matches("r#"));
            }
            if let Some(rest) = trimmed.strip_prefix("(*self).") {
                let field: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                return pointer_fields.contains(field.trim_start_matches("r#"));
            }
            false
        }

        let lines: Vec<&str> = code.lines().collect();
        if lines.is_empty() {
            return code.to_string();
        }
        let impl_targets = collect_impl_target_per_line(&lines);
        let struct_pointer_fields = parse_struct_pointer_fields(code);

        let mut out = String::with_capacity(code.len());
        let mut i = 0usize;
        while i < lines.len() {
            let line = lines[i];
            let trimmed = line.trim_end();
            let is_fn_start =
                (trimmed.contains(" fn ") || trimmed.starts_with("fn ")) && trimmed.ends_with('{');
            if !is_fn_start {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let mut j = i;
            let mut depth = 0isize;
            while j < lines.len() {
                let current = lines[j];
                depth += current.chars().filter(|c| *c == '{').count() as isize;
                depth -= current.chars().filter(|c| *c == '}').count() as isize;
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            if j >= lines.len() || depth != 0 {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let body_lines: &[&str] = if j > i + 1 { &lines[i + 1..j] } else { &[] };
            let pointer_bindings = collect_pointer_bindings(trimmed, body_lines);
            let pointer_fields = impl_targets
                .get(i)
                .and_then(|t| t.as_ref())
                .and_then(|target| struct_pointer_fields.get(target))
                .cloned()
                .unwrap_or_default();

            out.push_str(lines[i]);
            out.push('\n');
            for body_line in body_lines {
                let mut rewritten = body_line.to_string();
                let mut idx = 0usize;
                while let Some(rel) = rewritten[idx..].find("(!") {
                    let open_idx = idx + rel;
                    let Some(close_idx) = AstCodeGen::find_matching_close_paren(&rewritten, open_idx)
                    else {
                        break;
                    };
                    let expr = rewritten[open_idx + 2..close_idx].trim();
                    if !is_pointer_expr(expr, &pointer_bindings, &pointer_fields) {
                        idx = open_idx + 2;
                        continue;
                    }
                    let replacement = format!("(({}).is_null())", expr);
                    rewritten.replace_range(open_idx..=close_idx, &replacement);
                    idx = open_idx + replacement.len();
                }
                out.push_str(&rewritten);
                out.push('\n');
            }
            out.push_str(lines[j]);
            if j + 1 < lines.len() || code.ends_with('\n') {
                out.push('\n');
            }
            i = j + 1;
        }

        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    /// Casts from `self` reference directly to unrelated raw pointer targets are
    /// rejected by rustc. Cast through `*mut _` first.
    fn normalize_self_reference_casts_via_raw_ptr(code: &str) -> String {
        fn rewrite_parenthesized_casts(
            line: &str,
            marker: &str,
            self_ptr_ty: &str,
            cast_kind: &str,
            consume_trailing_paren: bool,
        ) -> String {
            if !line.contains(marker) {
                return line.to_string();
            }
            let mut rewritten = line.to_string();
            let mut idx = 0usize;
            while let Some(rel) = rewritten[idx..].find(marker) {
                let start = idx + rel;
                let ty_start = start + marker.len();
                let mut ty_end = ty_start;
                while ty_end < rewritten.len() {
                    let ch = rewritten[ty_end..].chars().next().unwrap();
                    if AstCodeGen::is_identifier_char(ch) || matches!(ch, ':' | '<' | '>' | '#') {
                        ty_end += ch.len_utf8();
                    } else {
                        break;
                    }
                }
                let ty = rewritten[ty_start..ty_end].trim();
                if ty.is_empty() {
                    idx = ty_start;
                    continue;
                }
                // Do not rewrite the head of chained casts like
                // `(self as *const T as *mut U)`. Replacing only the first
                // segment can unbalance trailing parentheses.
                let remainder = rewritten[ty_end..].trim_start();
                if remainder.starts_with("as *const ")
                    || remainder.starts_with("as *mut ")
                    || remainder.starts_with(") as *const ")
                    || remainder.starts_with(") as *mut ")
                {
                    idx = ty_end;
                    continue;
                }
                let replacement = format!("((self as {}) as {} {})", self_ptr_ty, cast_kind, ty);
                let replace_end = if consume_trailing_paren
                    && ty_end < rewritten.len()
                    && rewritten[ty_end..].starts_with(')')
                {
                    ty_end + 1
                } else {
                    ty_end
                };
                rewritten.replace_range(start..replace_end, &replacement);
                idx = start + replacement.len();
            }
            rewritten
        }

        let mut out = String::with_capacity(code.len());
        for line in code.lines() {
            let mut rewritten = line.to_string();
            rewritten = rewrite_parenthesized_casts(
                &rewritten,
                "(self as *const ",
                "*const Self",
                "*const",
                true,
            );
            rewritten = rewrite_parenthesized_casts(
                &rewritten,
                "(self) as *const ",
                "*const Self",
                "*const",
                false,
            );
            rewritten = rewrite_parenthesized_casts(
                &rewritten,
                "(self as *mut ",
                "*mut Self",
                "*mut",
                true,
            );
            rewritten = rewrite_parenthesized_casts(
                &rewritten,
                "(self) as *mut ",
                "*mut Self",
                "*mut",
                false,
            );

            if rewritten.contains(" as *const ()") && rewritten.contains('&') {
                let mut idx = 0usize;
                let marker = " as *const ()";
                while let Some(rel) = rewritten[idx..].find(marker) {
                    let cast_start = idx + rel;
                    let prefix = &rewritten[..cast_start];
                    let delim = prefix
                        .rfind(|ch: char| matches!(ch, '=' | '(' | '{' | ',' | ';'))
                        .map(|p| p + 1)
                        .unwrap_or(0);
                    let Some(and_rel) = rewritten[delim..cast_start].rfind('&') else {
                        idx = cast_start + marker.len();
                        continue;
                    };
                    let expr_start = delim + and_rel;
                    let expr = rewritten[expr_start..cast_start].trim();
                    if !expr.starts_with('&') {
                        idx = cast_start + marker.len();
                        continue;
                    }
                    let replacement = format!("({} as *const _ as *const ())", expr);
                    rewritten.replace_range(expr_start..cast_start + marker.len(), &replacement);
                    idx = expr_start + replacement.len();
                }
            }
            out.push_str(&rewritten);
            out.push('\n');
        }
        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    /// Raw pointer member access can degrade to `(ptr_expr).field` or
    /// `(ptr_expr).method(...)`; rewrite those to explicit dereference form.
    fn normalize_pointer_parenthesized_receiver_access(code: &str) -> String {
        fn parse_struct_pointer_fields(code: &str) -> HashMap<String, HashSet<String>> {
            let lines: Vec<&str> = code.lines().collect();
            let mut out: HashMap<String, HashSet<String>> = HashMap::new();
            let mut i = 0usize;
            while i < lines.len() {
                let trimmed = lines[i].trim_start();
                let Some(rest) = trimmed
                    .strip_prefix("pub struct ")
                    .or_else(|| trimmed.strip_prefix("struct "))
                else {
                    i += 1;
                    continue;
                };
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                if name.is_empty() || !trimmed.ends_with('{') {
                    i += 1;
                    continue;
                }
                let mut depth = 1isize;
                let mut fields: HashSet<String> = HashSet::new();
                let mut j = i + 1;
                while j < lines.len() && depth > 0 {
                    let current = lines[j];
                    if depth == 1 {
                        let mut field_src = current.trim();
                        if let Some(rest) = field_src.strip_prefix("pub(") {
                            if let Some(close_idx) = rest.find(')') {
                                field_src = rest[close_idx + 1..].trim_start();
                            }
                        } else if let Some(rest) = field_src.strip_prefix("pub ") {
                            field_src = rest.trim_start();
                        }
                        if let Some((lhs, rhs)) = field_src.split_once(':') {
                            let field = lhs.trim().trim_start_matches("r#");
                            let ty = rhs.trim().trim_end_matches(',').trim();
                            if !field.is_empty()
                                && (ty.starts_with("*mut ") || ty.starts_with("*const "))
                            {
                                fields.insert(field.to_string());
                            }
                        }
                    }
                    depth += current.chars().filter(|c| *c == '{').count() as isize;
                    depth -= current.chars().filter(|c| *c == '}').count() as isize;
                    j += 1;
                }
                if !fields.is_empty() {
                    out.insert(name.trim_start_matches("r#").to_string(), fields);
                }
                i = j;
            }
            out
        }

        fn parse_impl_target(line: &str) -> Option<String> {
            let trimmed = line.trim_start();
            let rest = trimmed.strip_prefix("impl ")?;
            if !trimmed.ends_with('{') {
                return None;
            }
            let target_src = rest.split('{').next()?.trim();
            let target_src = if let Some((_, rhs)) = target_src.split_once(" for ") {
                rhs.trim()
            } else {
                target_src
            };
            let token = target_src.split_whitespace().next().unwrap_or(target_src);
            let token = token.split('<').next().unwrap_or(token).trim();
            if token.is_empty() {
                None
            } else {
                Some(token.trim_start_matches("r#").to_string())
            }
        }

        fn collect_impl_target_per_line(lines: &[&str]) -> Vec<Option<String>> {
            let mut out = vec![None; lines.len()];
            let mut depth = 0i32;
            let mut stack: Vec<(i32, String)> = Vec::new();
            for (idx, line) in lines.iter().enumerate() {
                while stack
                    .last()
                    .is_some_and(|(start_depth, _)| *start_depth > depth)
                {
                    stack.pop();
                }
                out[idx] = stack.last().map(|(_, name)| name.clone());

                if let Some(target) = parse_impl_target(line) {
                    stack.push((depth + 1, target));
                }

                let open_count = line.chars().filter(|c| *c == '{').count() as i32;
                let close_count = line.chars().filter(|c| *c == '}').count() as i32;
                depth += open_count - close_count;
                if depth < 0 {
                    depth = 0;
                }
                while stack
                    .last()
                    .is_some_and(|(start_depth, _)| *start_depth > depth)
                {
                    stack.pop();
                }
            }
            out
        }

        fn collect_pointer_bindings(signature_line: &str, body_lines: &[&str]) -> HashSet<String> {
            let mut out = HashSet::new();
            let Some(open_idx) = signature_line.find('(') else {
                return out;
            };
            let Some(close_idx) = AstCodeGen::find_matching_close_paren(signature_line, open_idx)
            else {
                return out;
            };
            for param in AstCodeGen::split_top_level_list(&signature_line[open_idx + 1..close_idx], ',') {
                let Some((lhs, rhs)) = param.split_once(':') else {
                    continue;
                };
                let mut name = lhs.trim();
                if let Some(stripped) = name.strip_prefix("mut ") {
                    name = stripped.trim();
                }
                name = name.trim_start_matches("r#");
                let ty = rhs.trim();
                if !name.is_empty() && (ty.starts_with("*mut ") || ty.starts_with("*const ")) {
                    out.insert(name.to_string());
                }
            }
            for line in body_lines {
                let trimmed = line.trim_start();
                let Some(after_let) = trimmed.strip_prefix("let ") else {
                    continue;
                };
                let mut rest = after_let.trim_start();
                if let Some(stripped) = rest.strip_prefix("mut ") {
                    rest = stripped.trim_start();
                }
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                let Some(colon_idx) = rest.find(':') else {
                    continue;
                };
                let ty = rest[colon_idx + 1..]
                    .split('=')
                    .next()
                    .unwrap_or("")
                    .trim();
                if !name.is_empty() && (ty.starts_with("*mut ") || ty.starts_with("*const ")) {
                    out.insert(name.trim_start_matches("r#").to_string());
                }
            }
            out
        }

        fn is_pointer_expr(
            expr: &str,
            pointer_bindings: &HashSet<String>,
            pointer_fields: &HashSet<String>,
        ) -> bool {
            let mut trimmed = expr.trim();
            while is_fully_parenthesized_expr(trimmed) && trimmed.len() >= 2 {
                trimmed = trimmed[1..trimmed.len() - 1].trim();
            }
            if trimmed.is_empty() || trimmed.starts_with('*') {
                return false;
            }
            if trimmed.contains(" as *mut ") || trimmed.contains(" as *const ") {
                return true;
            }
            let binding = trimmed.trim_start_matches("r#");
            if pointer_bindings.contains(binding) {
                return true;
            }
            if let Some(rest) = trimmed.strip_prefix("self.") {
                let field: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                return pointer_fields.contains(field.trim_start_matches("r#"));
            }
            if let Some(rest) = trimmed.strip_prefix("(*self).") {
                let field: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                return pointer_fields.contains(field.trim_start_matches("r#"));
            }
            false
        }

        fn find_matching_open_paren(line: &str, close_idx: usize) -> Option<usize> {
            if close_idx == 0 {
                return None;
            }
            let bytes = line.as_bytes();
            let mut depth = 1i32;
            let mut pos = close_idx;
            while pos > 0 {
                pos -= 1;
                match bytes[pos] {
                    b')' => depth += 1,
                    b'(' => {
                        depth -= 1;
                        if depth == 0 {
                            return Some(pos);
                        }
                    }
                    _ => {}
                }
            }
            None
        }

        fn is_allowed_pointer_method(name: &str) -> bool {
            matches!(
                name,
                "is_null"
                    | "add"
                    | "sub"
                    | "offset"
                    | "offset_from"
                    | "wrapping_add"
                    | "wrapping_sub"
                    | "wrapping_offset"
                    | "byte_add"
                    | "byte_sub"
                    | "byte_offset"
                    | "cast"
                    | "as_ptr"
                    | "as_mut_ptr"
                    | "read"
                    | "read_unaligned"
                    | "write"
                    | "write_unaligned"
                    | "copy_to"
                    | "copy_from"
                    | "copy_to_nonoverlapping"
                    | "copy_from_nonoverlapping"
            )
        }

        let lines: Vec<&str> = code.lines().collect();
        if lines.is_empty() {
            return code.to_string();
        }
        let impl_targets = collect_impl_target_per_line(&lines);
        let struct_pointer_fields = parse_struct_pointer_fields(code);

        let mut out = String::with_capacity(code.len());
        let mut i = 0usize;
        while i < lines.len() {
            let line = lines[i];
            let trimmed = line.trim_end();
            let is_fn_start =
                (trimmed.contains(" fn ") || trimmed.starts_with("fn ")) && trimmed.ends_with('{');
            if !is_fn_start {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let mut j = i;
            let mut depth = 0isize;
            while j < lines.len() {
                let current = lines[j];
                depth += current.chars().filter(|c| *c == '{').count() as isize;
                depth -= current.chars().filter(|c| *c == '}').count() as isize;
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            if j >= lines.len() || depth != 0 {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let body_lines: &[&str] = if j > i + 1 { &lines[i + 1..j] } else { &[] };
            let pointer_bindings = collect_pointer_bindings(trimmed, body_lines);
            let pointer_fields = impl_targets
                .get(i)
                .and_then(|t| t.as_ref())
                .and_then(|target| struct_pointer_fields.get(target))
                .cloned()
                .unwrap_or_default();

            out.push_str(lines[i]);
            out.push('\n');
            for body_line in body_lines {
                let mut rewritten = body_line.to_string();
                let mut idx = 0usize;
                while let Some(rel) = rewritten[idx..].find(").") {
                    let close_idx = idx + rel;
                    let dot_idx = close_idx + 1;
                    let member_start = dot_idx + 1;
                    if member_start >= rewritten.len() {
                        break;
                    }
                    let mut member_end = member_start;
                    while member_end < rewritten.len() {
                        let ch = rewritten[member_end..].chars().next().unwrap();
                        if AstCodeGen::is_identifier_char(ch) || ch == '#' {
                            member_end += ch.len_utf8();
                        } else {
                            break;
                        }
                    }
                    if member_end == member_start {
                        idx = dot_idx + 1;
                        continue;
                    }
                    let member = rewritten[member_start..member_end]
                        .trim()
                        .trim_start_matches("r#");
                    let mut after_member = member_end;
                    while after_member < rewritten.len()
                        && rewritten.as_bytes()[after_member].is_ascii_whitespace()
                    {
                        after_member += 1;
                    }
                    if after_member < rewritten.len()
                        && rewritten.as_bytes()[after_member] == b'('
                        && is_allowed_pointer_method(member)
                    {
                        idx = member_end;
                        continue;
                    }

                    let Some(open_idx) = find_matching_open_paren(&rewritten, close_idx) else {
                        idx = member_end;
                        continue;
                    };
                    let expr = rewritten[open_idx + 1..close_idx].trim();
                    if !is_pointer_expr(expr, &pointer_bindings, &pointer_fields) {
                        idx = member_end;
                        continue;
                    }
                    let replacement = format!("(*({})).", expr);
                    rewritten.replace_range(open_idx..dot_idx + 1, &replacement);
                    idx = open_idx + replacement.len();
                }
                out.push_str(&rewritten);
                out.push('\n');
            }
            out.push_str(lines[j]);
            if j + 1 < lines.len() || code.ends_with('\n') {
                out.push('\n');
            }
            i = j + 1;
        }

        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    /// Array fields on `self` can degrade to `self.field.add(i)`; project to
    /// mutable pointers first.
    fn normalize_self_array_add_calls(code: &str) -> String {
        fn parse_struct_array_fields(code: &str) -> HashMap<String, HashSet<String>> {
            let lines: Vec<&str> = code.lines().collect();
            let mut out = HashMap::new();
            let mut i = 0usize;
            while i < lines.len() {
                let trimmed = lines[i].trim_start();
                let Some(rest) = trimmed
                    .strip_prefix("pub struct ")
                    .or_else(|| trimmed.strip_prefix("struct "))
                else {
                    i += 1;
                    continue;
                };
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                if name.is_empty() || !trimmed.ends_with('{') {
                    i += 1;
                    continue;
                }
                let mut fields = HashSet::new();
                let mut depth = 1isize;
                let mut j = i + 1;
                while j < lines.len() && depth > 0 {
                    let current = lines[j];
                    let current_trim = current.trim();
                    if depth == 1
                        && !current_trim.starts_with("//")
                        && !current_trim.starts_with("///")
                        && !current_trim.starts_with("#[")
                    {
                        let mut field_src = current_trim;
                        if let Some(rest) = field_src.strip_prefix("pub(") {
                            if let Some(close_idx) = rest.find(')') {
                                field_src = rest[close_idx + 1..].trim_start();
                            }
                        } else if let Some(rest) = field_src.strip_prefix("pub ") {
                            field_src = rest.trim_start();
                        }
                        if let Some((lhs, rhs)) = field_src.split_once(':') {
                            let field = lhs.trim().trim_start_matches("r#");
                            let ty = rhs.trim().trim_end_matches(',').trim();
                            if !field.is_empty() && ty.starts_with('[') {
                                fields.insert(field.to_string());
                            }
                        }
                    }
                    depth += current.chars().filter(|c| *c == '{').count() as isize;
                    depth -= current.chars().filter(|c| *c == '}').count() as isize;
                    j += 1;
                }
                if !fields.is_empty() {
                    out.insert(name.trim_start_matches("r#").to_string(), fields);
                }
                i = j;
            }
            out
        }

        fn parse_impl_target(line: &str) -> Option<String> {
            let trimmed = line.trim_start();
            let rest = trimmed.strip_prefix("impl ")?;
            if !trimmed.ends_with('{') {
                return None;
            }
            let target_src = rest.split('{').next()?.trim();
            let target_src = if let Some((_, rhs)) = target_src.split_once(" for ") {
                rhs.trim()
            } else {
                target_src
            };
            let token = target_src.split_whitespace().next().unwrap_or(target_src);
            let token = token.split('<').next().unwrap_or(token).trim();
            if token.is_empty() {
                None
            } else {
                Some(token.trim_start_matches("r#").to_string())
            }
        }

        fn collect_impl_target_per_line(lines: &[&str]) -> Vec<Option<String>> {
            let mut out = vec![None; lines.len()];
            let mut depth = 0i32;
            let mut stack: Vec<(i32, String)> = Vec::new();
            for (idx, line) in lines.iter().enumerate() {
                while stack
                    .last()
                    .is_some_and(|(start_depth, _)| *start_depth > depth)
                {
                    stack.pop();
                }
                out[idx] = stack.last().map(|(_, t)| t.clone());
                if let Some(target) = parse_impl_target(line) {
                    stack.push((depth + 1, target));
                }
                let open_count = line.chars().filter(|c| *c == '{').count() as i32;
                let close_count = line.chars().filter(|c| *c == '}').count() as i32;
                depth += open_count - close_count;
                if depth < 0 {
                    depth = 0;
                }
                while stack
                    .last()
                    .is_some_and(|(start_depth, _)| *start_depth > depth)
                {
                    stack.pop();
                }
            }
            out
        }

        let lines: Vec<&str> = code.lines().collect();
        if lines.is_empty() {
            return code.to_string();
        }
        let array_fields = parse_struct_array_fields(code);
        let impl_targets = collect_impl_target_per_line(&lines);

        let mut out = String::with_capacity(code.len());
        let mut i = 0usize;
        while i < lines.len() {
            let line = lines[i];
            let trimmed = line.trim_end();
            let is_fn_start =
                (trimmed.contains(" fn ") || trimmed.starts_with("fn ")) && trimmed.ends_with('{');
            if !is_fn_start {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }
            let mut j = i;
            let mut depth = 0isize;
            while j < lines.len() {
                let current = lines[j];
                depth += current.chars().filter(|c| *c == '{').count() as isize;
                depth -= current.chars().filter(|c| *c == '}').count() as isize;
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            if j >= lines.len() || depth != 0 {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }
            let target = impl_targets.get(i).and_then(|t| t.as_ref());
            let mut target_fields: Vec<String> = target
                .and_then(|t| array_fields.get(t))
                .map(|set| set.iter().cloned().collect())
                .unwrap_or_default();
            target_fields.sort_by(|a, b| b.len().cmp(&a.len()).then(a.cmp(b)));

            out.push_str(lines[i]);
            out.push('\n');
            for body_line in &lines[i + 1..j] {
                let mut rewritten = (*body_line).to_string();
                for field in &target_fields {
                    rewritten = rewritten.replace(
                        &format!("self.{}.add(", field),
                        &format!("self.{}.as_mut_ptr().add(", field),
                    );
                    rewritten = rewritten.replace(
                        &format!("self.{}.sub(", field),
                        &format!("self.{}.as_mut_ptr().sub(", field),
                    );
                    rewritten = rewritten.replace(
                        &format!("(*self).{}.add(", field),
                        &format!("(*self).{}.as_mut_ptr().add(", field),
                    );
                    rewritten = rewritten.replace(
                        &format!("(*self).{}.sub(", field),
                        &format!("(*self).{}.as_mut_ptr().sub(", field),
                    );
                }
                out.push_str(&rewritten);
                out.push('\n');
            }
            out.push_str(lines[j]);
            if j + 1 < lines.len() || code.ends_with('\n') {
                out.push('\n');
            }
            i = j + 1;
        }
        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    /// Degraded method calls on pointer receivers can lower as `ptr.method(...)`
    /// instead of `(*ptr).method(...)`.
    fn normalize_pointer_receiver_method_calls(code: &str) -> String {
        fn is_allowed_pointer_method(name: &str) -> bool {
            matches!(
                name,
                "is_null"
                    | "add"
                    | "sub"
                    | "offset"
                    | "offset_from"
                    | "wrapping_add"
                    | "wrapping_sub"
                    | "wrapping_offset"
                    | "byte_add"
                    | "byte_sub"
                    | "byte_offset"
                    | "cast"
                    | "as_ptr"
                    | "as_mut_ptr"
                    | "read"
                    | "read_unaligned"
                    | "write"
                    | "write_unaligned"
                    | "copy_to"
                    | "copy_from"
                    | "copy_to_nonoverlapping"
                    | "copy_from_nonoverlapping"
            )
        }

        fn parse_raw_pointer_pointee_type(ty: &str) -> Option<String> {
            let ty = ty.trim().trim_end_matches(',').trim();
            let pointee = ty
                .strip_prefix("*mut ")
                .or_else(|| ty.strip_prefix("*const "))?
                .trim();
            if pointee.is_empty() {
                return None;
            }
            let token = pointee
                .split(['<', ' ', ',', '{', '['])
                .next()
                .unwrap_or("")
                .trim();
            if token.is_empty() {
                None
            } else {
                Some(token.trim_start_matches("r#").to_string())
            }
        }

        fn parse_struct_fields(code: &str) -> HashMap<String, HashSet<String>> {
            let lines: Vec<&str> = code.lines().collect();
            let mut out = HashMap::new();
            let mut i = 0usize;
            while i < lines.len() {
                let trimmed = lines[i].trim_start();
                let Some(rest) = trimmed
                    .strip_prefix("pub struct ")
                    .or_else(|| trimmed.strip_prefix("struct "))
                else {
                    i += 1;
                    continue;
                };
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                if name.is_empty() || !trimmed.ends_with('{') {
                    i += 1;
                    continue;
                }
                let mut fields = HashSet::new();
                let mut depth = 1isize;
                let mut j = i + 1;
                while j < lines.len() && depth > 0 {
                    let current = lines[j];
                    let current_trim = current.trim();
                    if depth == 1 {
                        let mut field_src = current_trim;
                        if let Some(rest) = field_src.strip_prefix("pub(") {
                            if let Some(close_idx) = rest.find(')') {
                                field_src = rest[close_idx + 1..].trim_start();
                            }
                        } else if let Some(rest) = field_src.strip_prefix("pub ") {
                            field_src = rest.trim_start();
                        }
                        if let Some((lhs, _rhs)) = field_src.split_once(':') {
                            let field = lhs.trim().trim_start_matches("r#");
                            if !field.is_empty() {
                                fields.insert(field.to_string());
                            }
                        }
                    }
                    depth += current.chars().filter(|c| *c == '{').count() as isize;
                    depth -= current.chars().filter(|c| *c == '}').count() as isize;
                    j += 1;
                }
                if !fields.is_empty() {
                    out.insert(name.trim_start_matches("r#").to_string(), fields);
                }
                i = j;
            }
            out
        }

        fn parse_struct_pointer_fields(code: &str) -> HashMap<String, HashSet<String>> {
            let lines: Vec<&str> = code.lines().collect();
            let mut out = HashMap::new();
            let mut i = 0usize;
            while i < lines.len() {
                let trimmed = lines[i].trim_start();
                let Some(rest) = trimmed
                    .strip_prefix("pub struct ")
                    .or_else(|| trimmed.strip_prefix("struct "))
                else {
                    i += 1;
                    continue;
                };
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                if name.is_empty() || !trimmed.ends_with('{') {
                    i += 1;
                    continue;
                }
                let mut fields = HashSet::new();
                let mut depth = 1isize;
                let mut j = i + 1;
                while j < lines.len() && depth > 0 {
                    let current = lines[j];
                    let current_trim = current.trim();
                    if depth == 1 {
                        let mut field_src = current_trim;
                        if let Some(rest) = field_src.strip_prefix("pub(") {
                            if let Some(close_idx) = rest.find(')') {
                                field_src = rest[close_idx + 1..].trim_start();
                            }
                        } else if let Some(rest) = field_src.strip_prefix("pub ") {
                            field_src = rest.trim_start();
                        }
                        if let Some((lhs, rhs)) = field_src.split_once(':') {
                            let field = lhs.trim().trim_start_matches("r#");
                            let ty = rhs.trim().trim_end_matches(',').trim();
                            if !field.is_empty()
                                && (ty.starts_with("*mut ") || ty.starts_with("*const "))
                            {
                                fields.insert(field.to_string());
                            }
                        }
                    }
                    depth += current.chars().filter(|c| *c == '{').count() as isize;
                    depth -= current.chars().filter(|c| *c == '}').count() as isize;
                    j += 1;
                }
                if !fields.is_empty() {
                    out.insert(name.trim_start_matches("r#").to_string(), fields);
                }
                i = j;
            }
            out
        }

        fn parse_struct_pointer_field_pointees(
            code: &str,
            struct_fields: &HashMap<String, HashSet<String>>,
        ) -> HashMap<String, HashMap<String, String>> {
            let lines: Vec<&str> = code.lines().collect();
            let mut out: HashMap<String, HashMap<String, String>> = HashMap::new();
            let mut i = 0usize;
            while i < lines.len() {
                let trimmed = lines[i].trim_start();
                let Some(rest) = trimmed
                    .strip_prefix("pub struct ")
                    .or_else(|| trimmed.strip_prefix("struct "))
                else {
                    i += 1;
                    continue;
                };
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                if name.is_empty() || !trimmed.ends_with('{') {
                    i += 1;
                    continue;
                }
                let mut field_pointees: HashMap<String, String> = HashMap::new();
                let mut depth = 1isize;
                let mut j = i + 1;
                while j < lines.len() && depth > 0 {
                    let current = lines[j];
                    let current_trim = current.trim();
                    if depth == 1 {
                        let mut field_src = current_trim;
                        if let Some(rest) = field_src.strip_prefix("pub(") {
                            if let Some(close_idx) = rest.find(')') {
                                field_src = rest[close_idx + 1..].trim_start();
                            }
                        } else if let Some(rest) = field_src.strip_prefix("pub ") {
                            field_src = rest.trim_start();
                        }
                        if let Some((lhs, rhs)) = field_src.split_once(':') {
                            let field = lhs.trim().trim_start_matches("r#");
                            if field.is_empty() {
                                j += 1;
                                continue;
                            }
                            if let Some(pointee) = parse_raw_pointer_pointee_type(rhs) {
                                if struct_fields.contains_key(&pointee) {
                                    field_pointees.insert(field.to_string(), pointee);
                                }
                            }
                        }
                    }
                    depth += current.chars().filter(|c| *c == '{').count() as isize;
                    depth -= current.chars().filter(|c| *c == '}').count() as isize;
                    j += 1;
                }
                if !field_pointees.is_empty() {
                    out.insert(name.trim_start_matches("r#").to_string(), field_pointees);
                }
                i = j;
            }
            out
        }

        fn parse_impl_target(line: &str) -> Option<String> {
            let trimmed = line.trim_start();
            let rest = trimmed.strip_prefix("impl ")?;
            if !trimmed.ends_with('{') {
                return None;
            }
            let target_src = rest.split('{').next()?.trim();
            let target_src = if let Some((_, rhs)) = target_src.split_once(" for ") {
                rhs.trim()
            } else {
                target_src
            };
            let token = target_src.split_whitespace().next().unwrap_or(target_src);
            let token = token.split('<').next().unwrap_or(token).trim();
            if token.is_empty() {
                None
            } else {
                Some(token.trim_start_matches("r#").to_string())
            }
        }

        fn collect_impl_target_per_line(lines: &[&str]) -> Vec<Option<String>> {
            let mut out = vec![None; lines.len()];
            let mut depth = 0i32;
            let mut stack: Vec<(i32, String)> = Vec::new();
            for (idx, line) in lines.iter().enumerate() {
                while stack
                    .last()
                    .is_some_and(|(start_depth, _)| *start_depth > depth)
                {
                    stack.pop();
                }
                out[idx] = stack.last().map(|(_, t)| t.clone());
                if let Some(target) = parse_impl_target(line) {
                    stack.push((depth + 1, target));
                }
                let open_count = line.chars().filter(|c| *c == '{').count() as i32;
                let close_count = line.chars().filter(|c| *c == '}').count() as i32;
                depth += open_count - close_count;
                if depth < 0 {
                    depth = 0;
                }
                while stack
                    .last()
                    .is_some_and(|(start_depth, _)| *start_depth > depth)
                {
                    stack.pop();
                }
            }
            out
        }

        fn collect_pointer_bindings(signature_line: &str, body_lines: &[&str]) -> HashSet<String> {
            let mut out = HashSet::new();
            let mut non_pointer_locals: HashSet<String> = HashSet::new();
            let Some(open_idx) = signature_line.find('(') else {
                return out;
            };
            let Some(close_idx) = AstCodeGen::find_matching_close_paren(signature_line, open_idx)
            else {
                return out;
            };
            for param in AstCodeGen::split_top_level_list(&signature_line[open_idx + 1..close_idx], ',') {
                let Some((lhs, rhs)) = param.split_once(':') else {
                    continue;
                };
                let mut name = lhs.trim();
                if let Some(stripped) = name.strip_prefix("mut ") {
                    name = stripped.trim();
                }
                let ty = rhs.trim();
                let name = name.trim_start_matches("r#");
                if name.is_empty() {
                    continue;
                }
                if ty.starts_with("*mut ") || ty.starts_with("*const ") {
                    out.insert(name.to_string());
                }
            }
            for line in body_lines {
                let trimmed = line.trim_start();
                let Some(after_let) = trimmed.strip_prefix("let ") else {
                    continue;
                };
                let mut rest = after_let.trim_start();
                if let Some(stripped) = rest.strip_prefix("mut ") {
                    rest = stripped.trim_start();
                }
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                let Some(colon_idx) = rest.find(':') else {
                    continue;
                };
                let ty = rest[colon_idx + 1..]
                    .split('=')
                    .next()
                    .unwrap_or("")
                    .trim();
                let ident = name.trim_start_matches("r#");
                if ident.is_empty() {
                    continue;
                }
                if ty.starts_with("*mut ") || ty.starts_with("*const ") {
                    out.insert(ident.to_string());
                } else {
                    non_pointer_locals.insert(ident.to_string());
                }
            }
            for ident in non_pointer_locals {
                out.remove(&ident);
            }
            out
        }

        fn collect_pointer_binding_pointees(
            signature_line: &str,
            body_lines: &[&str],
            struct_fields: &HashMap<String, HashSet<String>>,
        ) -> HashMap<String, String> {
            let mut out = HashMap::new();
            let mut non_pointer_locals: HashSet<String> = HashSet::new();
            let Some(open_idx) = signature_line.find('(') else {
                return out;
            };
            let Some(close_idx) = AstCodeGen::find_matching_close_paren(signature_line, open_idx)
            else {
                return out;
            };
            for param in AstCodeGen::split_top_level_list(
                &signature_line[open_idx + 1..close_idx],
                ',',
            ) {
                let Some((lhs, rhs)) = param.split_once(':') else {
                    continue;
                };
                let mut name = lhs.trim();
                if let Some(stripped) = name.strip_prefix("mut ") {
                    name = stripped.trim();
                }
                let name = name.trim_start_matches("r#");
                if name.is_empty() {
                    continue;
                }
                let Some(pointee) = parse_raw_pointer_pointee_type(rhs) else {
                    continue;
                };
                if struct_fields.contains_key(&pointee) {
                    out.insert(name.to_string(), pointee);
                }
            }
            for line in body_lines {
                let trimmed = line.trim_start();
                let Some(after_let) = trimmed.strip_prefix("let ") else {
                    continue;
                };
                let mut rest = after_let.trim_start();
                if let Some(stripped) = rest.strip_prefix("mut ") {
                    rest = stripped.trim_start();
                }
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                let Some(colon_idx) = rest.find(':') else {
                    continue;
                };
                let ty = rest[colon_idx + 1..]
                    .split('=')
                    .next()
                    .unwrap_or("")
                    .trim();
                let ident = name.trim_start_matches("r#");
                if ident.is_empty() {
                    continue;
                }
                if let Some(pointee) = parse_raw_pointer_pointee_type(ty) {
                    if struct_fields.contains_key(&pointee) {
                        out.insert(ident.to_string(), pointee);
                    }
                } else {
                    non_pointer_locals.insert(ident.to_string());
                }
            }
            for ident in non_pointer_locals {
                out.remove(&ident);
            }
            out
        }

        fn rewrite_pointer_binding_calls(line: &str, pointer_bindings: &HashSet<String>) -> String {
            if pointer_bindings.is_empty() || !line.contains('.') || !line.contains('(') {
                return line.to_string();
            }
            let mut rewritten = line.to_string();
            for ident in pointer_bindings {
                let pattern = format!("{}.", ident);
                let mut idx = 0usize;
                while let Some(rel) = rewritten[idx..].find(&pattern) {
                    let start = idx + rel;
                    let left_ok = if start == 0 {
                        true
                    } else {
                        !rewritten[..start]
                            .chars()
                            .next_back()
                            .is_some_and(AstCodeGen::is_identifier_char)
                            && !rewritten[..start].ends_with('*')
                    };
                    if !left_ok {
                        idx = start + pattern.len();
                        continue;
                    }
                    let method_start = start + pattern.len();
                    let mut method_end = method_start;
                    while method_end < rewritten.len() {
                        let ch = rewritten[method_end..].chars().next().unwrap();
                        if AstCodeGen::is_identifier_char(ch) || ch == '#' {
                            method_end += ch.len_utf8();
                        } else {
                            break;
                        }
                    }
                    if method_end == method_start || method_end >= rewritten.len() {
                        idx = method_end.max(start + pattern.len());
                        continue;
                    }
                    let mut after_method = method_end;
                    while after_method < rewritten.len()
                        && rewritten.as_bytes()[after_method].is_ascii_whitespace()
                    {
                        after_method += 1;
                    }
                    if after_method >= rewritten.len() || rewritten.as_bytes()[after_method] != b'(' {
                        idx = method_end;
                        continue;
                    }
                    let method = rewritten[method_start..method_end]
                        .trim()
                        .trim_start_matches("r#");
                    if is_allowed_pointer_method(method) {
                        idx = method_end;
                        continue;
                    }
                    rewritten.replace_range(start..method_start, &format!("(*{}).", ident));
                    idx = start + ident.len() + 4;
                }
            }
            rewritten
        }

        fn rewrite_pointer_field_calls(line: &str, field_expr: &str) -> String {
            let pattern = format!("{}.", field_expr);
            if !line.contains(&pattern) {
                return line.to_string();
            }
            let mut rewritten = line.to_string();
            let mut idx = 0usize;
            while let Some(rel) = rewritten[idx..].find(&pattern) {
                let start = idx + rel;
                let method_start = start + pattern.len();
                let mut method_end = method_start;
                while method_end < rewritten.len() {
                    let ch = rewritten[method_end..].chars().next().unwrap();
                    if AstCodeGen::is_identifier_char(ch) || ch == '#' {
                        method_end += ch.len_utf8();
                    } else {
                        break;
                    }
                }
                if method_end == method_start || method_end >= rewritten.len() {
                    idx = method_end.max(start + pattern.len());
                    continue;
                }
                let mut after_method = method_end;
                while after_method < rewritten.len()
                    && rewritten.as_bytes()[after_method].is_ascii_whitespace()
                {
                    after_method += 1;
                }
                if after_method >= rewritten.len() || rewritten.as_bytes()[after_method] != b'(' {
                    idx = method_end;
                    continue;
                }
                let method = rewritten[method_start..method_end]
                    .trim()
                    .trim_start_matches("r#");
                if is_allowed_pointer_method(method) {
                    idx = method_end;
                    continue;
                }
                let replacement_prefix = format!("(*{}).", field_expr);
                rewritten.replace_range(start..method_start, &replacement_prefix);
                idx = start + replacement_prefix.len();
            }
            rewritten
        }

        fn rewrite_receiver_no_arg_method_call_to_value(
            line: &str,
            receiver_expr: &str,
            method: &str,
            replacement: &str,
        ) -> String {
            let call = format!("{}.{}()", receiver_expr, method);
            if !line.contains(&call) {
                return line.to_string();
            }
            let mut rewritten = line.to_string();
            let receiver_starts_ident = receiver_expr
                .chars()
                .next()
                .is_some_and(AstCodeGen::is_identifier_char);
            let mut idx = 0usize;
            while let Some(rel) = rewritten[idx..].find(&call) {
                let start = idx + rel;
                let end = start + call.len();
                if receiver_starts_ident
                    && start > 0
                    && rewritten[..start]
                        .chars()
                        .next_back()
                        .is_some_and(AstCodeGen::is_identifier_char)
                {
                    idx = start + 1;
                    continue;
                }
                if end < rewritten.len()
                    && rewritten[end..]
                        .chars()
                        .next()
                        .is_some_and(AstCodeGen::is_identifier_char)
                {
                    idx = end;
                    continue;
                }
                rewritten.replace_range(start..end, replacement);
                idx = start + replacement.len();
            }
            rewritten
        }

        fn rewrite_pointer_pointee_field_calls(
            line: &str,
            pointer_binding_pointees: &HashMap<String, String>,
            pointer_self_field_pointees: &HashMap<String, String>,
            struct_fields: &HashMap<String, HashSet<String>>,
        ) -> String {
            if line.is_empty() || !line.contains(").") || !line.contains("()") {
                return line.to_string();
            }
            let mut rewritten = line.to_string();

            for (ident, pointee) in pointer_binding_pointees {
                let Some(fields) = struct_fields.get(pointee) else {
                    continue;
                };
                for field in fields {
                    let call_pattern = format!("(*{}).{}()", ident, field);
                    if rewritten.contains(&call_pattern) {
                        rewritten = rewritten.replace(
                            &call_pattern,
                            &format!("(*{}).{}", ident, field),
                        );
                    }
                }
            }

            for (self_field, pointee) in pointer_self_field_pointees {
                let Some(fields) = struct_fields.get(pointee) else {
                    continue;
                };
                for field in fields {
                    let direct_pattern = format!("(*self.{}).{}()", self_field, field);
                    if rewritten.contains(&direct_pattern) {
                        rewritten = rewritten.replace(
                            &direct_pattern,
                            &format!("(*self.{}).{}", self_field, field),
                        );
                    }
                    let deref_self_pattern = format!("(*(*self).{}).{}()", self_field, field);
                    if rewritten.contains(&deref_self_pattern) {
                        rewritten = rewritten.replace(
                            &deref_self_pattern,
                            &format!("(*(*self).{}).{}", self_field, field),
                        );
                    }
                }
            }

            rewritten
        }

        let lines: Vec<&str> = code.lines().collect();
        if lines.is_empty() {
            return code.to_string();
        }
        let struct_fields = parse_struct_fields(code);
        let pointer_fields = parse_struct_pointer_fields(code);
        let pointer_field_pointees = parse_struct_pointer_field_pointees(code, &struct_fields);
        let impl_targets = collect_impl_target_per_line(&lines);

        let mut out = String::with_capacity(code.len());
        let mut i = 0usize;
        while i < lines.len() {
            let line = lines[i];
            let trimmed = line.trim_end();
            let is_fn_start =
                (trimmed.contains(" fn ") || trimmed.starts_with("fn ")) && trimmed.ends_with('{');
            if !is_fn_start {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }
            let mut j = i;
            let mut depth = 0isize;
            while j < lines.len() {
                let current = lines[j];
                depth += current.chars().filter(|c| *c == '{').count() as isize;
                depth -= current.chars().filter(|c| *c == '}').count() as isize;
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            if j >= lines.len() || depth != 0 {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let body_lines: &[&str] = if j > i + 1 { &lines[i + 1..j] } else { &[] };
            let pointer_bindings = collect_pointer_bindings(trimmed, body_lines);
            let pointer_binding_pointees =
                collect_pointer_binding_pointees(trimmed, body_lines, &struct_fields);
            let mut pointer_self_fields: Vec<String> = impl_targets
                .get(i)
                .and_then(|t| t.as_ref())
                .and_then(|target| pointer_fields.get(target))
                .map(|set| set.iter().cloned().collect())
                .unwrap_or_default();
            pointer_self_fields.sort_by(|a, b| b.len().cmp(&a.len()).then(a.cmp(b)));
            let pointer_self_field_pointees: HashMap<String, String> = impl_targets
                .get(i)
                .and_then(|t| t.as_ref())
                .and_then(|target| pointer_field_pointees.get(target))
                .cloned()
                .unwrap_or_default();

            out.push_str(lines[i]);
            out.push('\n');
            for body_line in body_lines {
                let mut rewritten = rewrite_pointer_binding_calls(body_line, &pointer_bindings);
                for ident in &pointer_bindings {
                    rewritten = rewrite_receiver_no_arg_method_call_to_value(
                        &rewritten,
                        ident,
                        "as_mut_ptr",
                        ident,
                    );
                    rewritten = rewrite_receiver_no_arg_method_call_to_value(
                        &rewritten,
                        ident,
                        "as_ptr",
                        ident,
                    );
                }
                for field in &pointer_self_fields {
                    rewritten = rewrite_pointer_field_calls(&rewritten, &format!("self.{}", field));
                    rewritten =
                        rewrite_pointer_field_calls(&rewritten, &format!("(*self).{}", field));
                    rewritten = rewrite_receiver_no_arg_method_call_to_value(
                        &rewritten,
                        &format!("self.{}", field),
                        "as_mut_ptr",
                        &format!("self.{}", field),
                    );
                    rewritten = rewrite_receiver_no_arg_method_call_to_value(
                        &rewritten,
                        &format!("self.{}", field),
                        "as_ptr",
                        &format!("self.{}", field),
                    );
                    rewritten = rewrite_receiver_no_arg_method_call_to_value(
                        &rewritten,
                        &format!("(*self).{}", field),
                        "as_mut_ptr",
                        &format!("(*self).{}", field),
                    );
                    rewritten = rewrite_receiver_no_arg_method_call_to_value(
                        &rewritten,
                        &format!("(*self).{}", field),
                        "as_ptr",
                        &format!("(*self).{}", field),
                    );
                }
                for (ident, pointee) in &pointer_binding_pointees {
                    let Some(pointer_pointee_fields) = pointer_fields.get(pointee) else {
                        continue;
                    };
                    for field in pointer_pointee_fields {
                        let receiver = format!("(*{}).{}", ident, field);
                        rewritten = rewrite_receiver_no_arg_method_call_to_value(
                            &rewritten,
                            &receiver,
                            "as_mut_ptr",
                            &receiver,
                        );
                        rewritten = rewrite_receiver_no_arg_method_call_to_value(
                            &rewritten,
                            &receiver,
                            "as_ptr",
                            &receiver,
                        );
                    }
                }
                rewritten = rewrite_pointer_pointee_field_calls(
                    &rewritten,
                    &pointer_binding_pointees,
                    &pointer_self_field_pointees,
                    &struct_fields,
                );
                out.push_str(&rewritten);
                out.push('\n');
            }
            out.push_str(lines[j]);
            if j + 1 < lines.len() || code.ends_with('\n') {
                out.push('\n');
            }
            i = j + 1;
        }
        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    /// Rewrite pointer `+=`/`-=` artifacts to `wrapping_add`/`wrapping_sub`
    /// forms, which are valid on raw pointers.
    fn normalize_pointer_augmented_assignments(code: &str) -> String {
        fn collect_pointer_bindings(signature_line: &str, body_lines: &[&str]) -> HashSet<String> {
            let mut out = HashSet::new();
            let Some(open_idx) = signature_line.find('(') else {
                return out;
            };
            let Some(close_idx) = AstCodeGen::find_matching_close_paren(signature_line, open_idx)
            else {
                return out;
            };
            let params_src = &signature_line[open_idx + 1..close_idx];
            for param in AstCodeGen::split_top_level_list(params_src, ',') {
                let Some((lhs, rhs)) = param.split_once(':') else {
                    continue;
                };
                let mut name = lhs.trim();
                if let Some(stripped) = name.strip_prefix("mut ") {
                    name = stripped.trim();
                }
                name = name.trim_start_matches("r#");
                let ty = rhs.trim();
                if !name.is_empty() && (ty.starts_with("*mut ") || ty.starts_with("*const ")) {
                    out.insert(name.to_string());
                }
            }
            for line in body_lines {
                let trimmed = line.trim_start();
                let Some(after_let) = trimmed.strip_prefix("let ") else {
                    continue;
                };
                let mut rest = after_let.trim_start();
                if let Some(stripped) = rest.strip_prefix("mut ") {
                    rest = stripped.trim_start();
                }
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                let Some(colon_idx) = rest.find(':') else {
                    continue;
                };
                let ty = rest[colon_idx + 1..]
                    .split('=')
                    .next()
                    .unwrap_or("")
                    .trim();
                if !name.is_empty() && (ty.starts_with("*mut ") || ty.starts_with("*const ")) {
                    out.insert(name.trim_start_matches("r#").to_string());
                }
            }
            out
        }

        fn rewrite_augmented_op(
            line: &str,
            pointer_bindings: &HashSet<String>,
            op: &str,
            method: &str,
        ) -> String {
            if !line.contains(op) {
                return line.to_string();
            }
            let mut rewritten = line.to_string();
            let mut idx = 0usize;
            while let Some(rel) = rewritten[idx..].find(op) {
                let op_idx = idx + rel;
                let bytes = rewritten.as_bytes();
                let mut lhs_end = op_idx;
                while lhs_end > 0 && bytes[lhs_end - 1].is_ascii_whitespace() {
                    lhs_end -= 1;
                }
                let mut lhs_start = lhs_end;
                while lhs_start > 0 {
                    let b = bytes[lhs_start - 1];
                    if (b as char).is_ascii_alphanumeric() || b == b'_' || b == b'#' {
                        lhs_start -= 1;
                    } else {
                        break;
                    }
                }
                if lhs_start == lhs_end {
                    idx = op_idx + op.len();
                    continue;
                }
                let lhs_src = rewritten[lhs_start..lhs_end].trim();
                let lhs_ident = lhs_src.trim_start_matches("r#");
                if !pointer_bindings.contains(lhs_ident) {
                    idx = op_idx + op.len();
                    continue;
                }

                let mut rhs_start = op_idx + op.len();
                while rhs_start < rewritten.len() && rewritten.as_bytes()[rhs_start].is_ascii_whitespace()
                {
                    rhs_start += 1;
                }
                if rhs_start >= rewritten.len() {
                    idx = op_idx + op.len();
                    continue;
                }
                let mut rhs_end = rhs_start;
                let mut p_depth = 0i32;
                let mut b_depth = 0i32;
                let mut c_depth = 0i32;
                while rhs_end < rewritten.len() {
                    let ch = rewritten.as_bytes()[rhs_end] as char;
                    match ch {
                        '(' => p_depth += 1,
                        ')' => {
                            if p_depth > 0 {
                                p_depth -= 1;
                            }
                        }
                        '[' => b_depth += 1,
                        ']' => {
                            if b_depth > 0 {
                                b_depth -= 1;
                            }
                        }
                        '{' => c_depth += 1,
                        '}' => {
                            if c_depth > 0 {
                                c_depth -= 1;
                            } else if p_depth == 0 && b_depth == 0 {
                                // Do not absorb surrounding block terminators
                                // (for example from `unsafe { ptr += x };`) into
                                // the rhs expression; they belong after the
                                // rewritten assignment.
                                break;
                            }
                        }
                        ';' if p_depth == 0 && b_depth == 0 && c_depth == 0 => break,
                        _ => {}
                    }
                    rhs_end += 1;
                }
                if rhs_end <= rhs_start {
                    idx = op_idx + op.len();
                    continue;
                }
                let rhs_expr = rewritten[rhs_start..rhs_end].trim();
                if rhs_expr.is_empty() {
                    idx = op_idx + op.len();
                    continue;
                }
                let replacement = format!(
                    "{} = {}.{}(({}) as usize)",
                    lhs_src, lhs_src, method, rhs_expr
                );
                rewritten.replace_range(lhs_start..rhs_end, &replacement);
                idx = lhs_start + replacement.len();
            }
            rewritten
        }

        let lines: Vec<&str> = code.lines().collect();
        if lines.is_empty() {
            return code.to_string();
        }
        let mut out = String::with_capacity(code.len());
        let mut i = 0usize;
        while i < lines.len() {
            let line = lines[i];
            let trimmed = line.trim_end();
            let is_fn_start =
                (trimmed.contains(" fn ") || trimmed.starts_with("fn ")) && trimmed.ends_with('{');
            if !is_fn_start {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let mut j = i;
            let mut depth = 0isize;
            while j < lines.len() {
                let current = lines[j];
                depth += current.chars().filter(|c| *c == '{').count() as isize;
                depth -= current.chars().filter(|c| *c == '}').count() as isize;
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            if j >= lines.len() || depth != 0 {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let body_lines: &[&str] = if j > i + 1 { &lines[i + 1..j] } else { &[] };
            let pointer_bindings = collect_pointer_bindings(trimmed, body_lines);

            out.push_str(lines[i]);
            out.push('\n');
            for body_line in body_lines {
                let mut rewritten = body_line.to_string();
                rewritten = rewrite_augmented_op(&rewritten, &pointer_bindings, "+=", "wrapping_add");
                rewritten = rewrite_augmented_op(&rewritten, &pointer_bindings, "-=", "wrapping_sub");
                out.push_str(&rewritten);
                out.push('\n');
            }
            out.push_str(lines[j]);
            if j + 1 < lines.len() || code.ends_with('\n') {
                out.push('\n');
            }
            i = j + 1;
        }

        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    /// Casts from value bindings directly to raw pointers are invalid. Cast via
    /// the binding's address (`&`/`&mut`) first.
    fn normalize_value_to_pointer_casts_through_address(code: &str) -> String {
        fn is_primitive_scalar_type(ty: &str) -> bool {
            matches!(
                ty.trim(),
                "u8"
                    | "u16"
                    | "u32"
                    | "u64"
                    | "u128"
                    | "usize"
                    | "i8"
                    | "i16"
                    | "i32"
                    | "i64"
                    | "i128"
                    | "isize"
                    | "f32"
                    | "f64"
                    | "bool"
                    | "char"
            )
        }

        fn collect_binding_types(signature_line: &str, body_lines: &[&str]) -> HashMap<String, String> {
            let mut out = HashMap::new();
            let Some(open_idx) = signature_line.find('(') else {
                return out;
            };
            let Some(close_idx) = AstCodeGen::find_matching_close_paren(signature_line, open_idx)
            else {
                return out;
            };
            for param in AstCodeGen::split_top_level_list(&signature_line[open_idx + 1..close_idx], ',') {
                let Some((lhs, rhs)) = param.split_once(':') else {
                    continue;
                };
                let mut name = lhs.trim();
                if let Some(stripped) = name.strip_prefix("mut ") {
                    name = stripped.trim();
                }
                if !name.is_empty() {
                    out.insert(name.trim_start_matches("r#").to_string(), rhs.trim().to_string());
                }
            }
            for line in body_lines {
                let trimmed = line.trim_start();
                let Some(after_let) = trimmed.strip_prefix("let ") else {
                    continue;
                };
                let mut rest = after_let.trim_start();
                if let Some(stripped) = rest.strip_prefix("mut ") {
                    rest = stripped.trim_start();
                }
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                let Some(colon_idx) = rest.find(':') else {
                    continue;
                };
                let ty = rest[colon_idx + 1..]
                    .split('=')
                    .next()
                    .unwrap_or("")
                    .trim();
                if !name.is_empty() && !ty.is_empty() {
                    out.insert(name.trim_start_matches("r#").to_string(), ty.to_string());
                }
            }
            out
        }

        fn rewrite_ident_pointer_casts(
            line: &str,
            binding_types: &HashMap<String, String>,
            cast_kind: &str,
        ) -> String {
            let marker = format!(") as {} ", cast_kind);
            if !line.contains(&marker) {
                return line.to_string();
            }
            let mut rewritten = line.to_string();
            let mut idx = 0usize;
            while let Some(rel) = rewritten[idx..].find(&marker) {
                let cast_start = idx + rel;
                let Some(open_idx) = rewritten[..cast_start].rfind('(') else {
                    idx = cast_start + marker.len();
                    continue;
                };
                let ident = rewritten[open_idx + 1..cast_start].trim();
                if ident.is_empty() {
                    idx = cast_start + marker.len();
                    continue;
                }
                if !ident
                    .chars()
                    .all(|ch| AstCodeGen::is_identifier_char(ch) || ch == '#')
                {
                    idx = cast_start + marker.len();
                    continue;
                }
                let ident_key = ident.trim_start_matches("r#");
                let Some(ty) = binding_types.get(ident_key) else {
                    idx = cast_start + marker.len();
                    continue;
                };
                if ty.starts_with("*mut ")
                    || ty.starts_with("*const ")
                    || ty.starts_with('&')
                    || is_primitive_scalar_type(ty)
                {
                    idx = cast_start + marker.len();
                    continue;
                }
                let type_start = cast_start + marker.len();
                let mut type_end = type_start;
                while type_end < rewritten.len() {
                    let ch = rewritten[type_end..].chars().next().unwrap();
                    if AstCodeGen::is_identifier_char(ch) || matches!(ch, ':' | '<' | '>' | '#') {
                        type_end += ch.len_utf8();
                    } else {
                        break;
                    }
                }
                if type_end == type_start {
                    idx = cast_start + marker.len();
                    continue;
                }
                let target_ty = rewritten[type_start..type_end].trim();
                let replacement = if cast_kind == "*mut" {
                    format!("((&mut {}) as *mut _ as *mut {})", ident, target_ty)
                } else {
                    format!("((&{}) as *const _ as *const {})", ident, target_ty)
                };
                rewritten.replace_range(open_idx..type_end, &replacement);
                idx = open_idx + replacement.len();
            }
            rewritten
        }

        let lines: Vec<&str> = code.lines().collect();
        if lines.is_empty() {
            return code.to_string();
        }

        let mut out = String::with_capacity(code.len());
        let mut i = 0usize;
        while i < lines.len() {
            let line = lines[i];
            let trimmed = line.trim_end();
            let is_fn_start =
                (trimmed.contains(" fn ") || trimmed.starts_with("fn ")) && trimmed.ends_with('{');
            if !is_fn_start {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let mut j = i;
            let mut depth = 0isize;
            while j < lines.len() {
                let current = lines[j];
                depth += current.chars().filter(|c| *c == '{').count() as isize;
                depth -= current.chars().filter(|c| *c == '}').count() as isize;
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            if j >= lines.len() || depth != 0 {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }
            let body_lines: &[&str] = if j > i + 1 { &lines[i + 1..j] } else { &[] };
            let binding_types = collect_binding_types(trimmed, body_lines);

            out.push_str(lines[i]);
            out.push('\n');
            for body_line in body_lines {
                let mut rewritten = body_line.to_string();
                rewritten = rewrite_ident_pointer_casts(&rewritten, &binding_types, "*mut");
                rewritten = rewrite_ident_pointer_casts(&rewritten, &binding_types, "*const");
                out.push_str(&rewritten);
                out.push('\n');
            }
            out.push_str(lines[j]);
            if j + 1 < lines.len() || code.ends_with('\n') {
                out.push('\n');
            }
            i = j + 1;
        }

        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    /// Retarget degraded pointer cast targets using the typed assignment lhs.
    /// Example: `self.tail_ = (g) as *mut basic_px_group;` where `tail_` is
    /// `*mut basic_px_group_delete_entry` becomes
    /// `self.tail_ = (g) as *mut basic_px_group_delete_entry;`.
    fn normalize_pointer_cast_targets_from_assignment_lhs(code: &str) -> String {
        fn parse_struct_field_types(code: &str) -> HashMap<String, HashMap<String, String>> {
            let lines: Vec<&str> = code.lines().collect();
            let mut out: HashMap<String, HashMap<String, String>> = HashMap::new();
            let mut i = 0usize;
            while i < lines.len() {
                let trimmed = lines[i].trim_start();
                let Some(rest) = trimmed
                    .strip_prefix("pub struct ")
                    .or_else(|| trimmed.strip_prefix("struct "))
                else {
                    i += 1;
                    continue;
                };
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                if name.is_empty() || !trimmed.ends_with('{') {
                    i += 1;
                    continue;
                }
                let mut fields: HashMap<String, String> = HashMap::new();
                let mut depth = 1isize;
                let mut j = i + 1;
                while j < lines.len() && depth > 0 {
                    let current = lines[j];
                    let current_trim = current.trim();
                    if depth == 1
                        && !current_trim.starts_with("//")
                        && !current_trim.starts_with("///")
                        && !current_trim.starts_with("#[")
                    {
                        let mut field_src = current_trim;
                        if let Some(rest) = field_src.strip_prefix("pub(") {
                            if let Some(close_idx) = rest.find(')') {
                                field_src = rest[close_idx + 1..].trim_start();
                            }
                        } else if let Some(rest) = field_src.strip_prefix("pub ") {
                            field_src = rest.trim_start();
                        }
                        if let Some((lhs, rhs)) = field_src.split_once(':') {
                            let field = lhs.trim().trim_start_matches("r#");
                            let ty = rhs.trim().trim_end_matches(',').trim();
                            if !field.is_empty() && !ty.is_empty() {
                                fields.insert(field.to_string(), ty.to_string());
                            }
                        }
                    }
                    depth += current.chars().filter(|c| *c == '{').count() as isize;
                    depth -= current.chars().filter(|c| *c == '}').count() as isize;
                    j += 1;
                }
                out.insert(name.trim_start_matches("r#").to_string(), fields);
                i = j;
            }
            out
        }

        fn parse_impl_target(line: &str) -> Option<String> {
            let trimmed = line.trim_start();
            let rest = trimmed.strip_prefix("impl ")?;
            if !trimmed.ends_with('{') {
                return None;
            }
            let target_src = rest.split('{').next()?.trim();
            let target_src = if let Some((_, rhs)) = target_src.split_once(" for ") {
                rhs.trim()
            } else {
                target_src
            };
            let token = target_src.split_whitespace().next().unwrap_or(target_src);
            let token = token.split('<').next().unwrap_or(token).trim();
            if token.is_empty() {
                None
            } else {
                Some(token.trim_start_matches("r#").to_string())
            }
        }

        fn collect_impl_target_per_line(lines: &[&str]) -> Vec<Option<String>> {
            let mut out = vec![None; lines.len()];
            let mut depth = 0i32;
            let mut stack: Vec<(i32, String)> = Vec::new();
            for (idx, line) in lines.iter().enumerate() {
                while stack
                    .last()
                    .is_some_and(|(start_depth, _)| *start_depth > depth)
                {
                    stack.pop();
                }
                out[idx] = stack.last().map(|(_, name)| name.clone());

                if let Some(target) = parse_impl_target(line) {
                    stack.push((depth + 1, target));
                }
                let open_count = line.chars().filter(|c| *c == '{').count() as i32;
                let close_count = line.chars().filter(|c| *c == '}').count() as i32;
                depth += open_count - close_count;
                if depth < 0 {
                    depth = 0;
                }
                while stack
                    .last()
                    .is_some_and(|(start_depth, _)| *start_depth > depth)
                {
                    stack.pop();
                }
            }
            out
        }

        fn collect_binding_types(signature_line: &str, body_lines: &[&str]) -> HashMap<String, String> {
            let mut out = HashMap::new();
            let Some(open_idx) = signature_line.find('(') else {
                return out;
            };
            let Some(close_idx) = AstCodeGen::find_matching_close_paren(signature_line, open_idx)
            else {
                return out;
            };
            let params_src = &signature_line[open_idx + 1..close_idx];
            for param in AstCodeGen::split_top_level_list(params_src, ',') {
                let Some((lhs, rhs)) = param.split_once(':') else {
                    continue;
                };
                let mut name = lhs.trim();
                if let Some(stripped) = name.strip_prefix("mut ") {
                    name = stripped.trim();
                }
                name = name.trim_start_matches("r#");
                let ty = rhs.trim();
                if !name.is_empty() && !ty.is_empty() {
                    out.insert(name.to_string(), ty.to_string());
                }
            }
            for line in body_lines {
                let trimmed = line.trim_start();
                let Some(after_let) = trimmed.strip_prefix("let ") else {
                    continue;
                };
                let mut rest = after_let.trim_start();
                if let Some(stripped) = rest.strip_prefix("mut ") {
                    rest = stripped.trim_start();
                }
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                let Some(colon_idx) = rest.find(':') else {
                    continue;
                };
                let ty = rest[colon_idx + 1..]
                    .split('=')
                    .next()
                    .unwrap_or("")
                    .trim();
                if !name.is_empty() && !ty.is_empty() {
                    out.insert(name.trim_start_matches("r#").to_string(), ty.to_string());
                }
            }
            out
        }

        fn lhs_pointer_type(
            lhs: &str,
            binding_types: &HashMap<String, String>,
            impl_field_types: &HashMap<String, String>,
        ) -> Option<String> {
            let lhs_trimmed = lhs.trim();
            if let Some(rest) = lhs_trimmed.strip_prefix("self.") {
                let field: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                let ty = impl_field_types.get(field.trim_start_matches("r#"))?;
                if ty.starts_with("*mut ") || ty.starts_with("*const ") {
                    return Some(ty.to_string());
                }
                return None;
            }
            if let Some(rest) = lhs_trimmed.strip_prefix("(*self).") {
                let field: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                let ty = impl_field_types.get(field.trim_start_matches("r#"))?;
                if ty.starts_with("*mut ") || ty.starts_with("*const ") {
                    return Some(ty.to_string());
                }
                return None;
            }
            let ident = lhs_trimmed.trim_start_matches("r#");
            let ty = binding_types.get(ident)?;
            if ty.starts_with("*mut ") || ty.starts_with("*const ") {
                Some(ty.to_string())
            } else {
                None
            }
        }

        fn find_assignment_eq(line: &str) -> Option<usize> {
            let bytes = line.as_bytes();
            let mut idx = 0usize;
            while idx < bytes.len() {
                if bytes[idx] != b'=' {
                    idx += 1;
                    continue;
                }
                let prev = if idx > 0 { Some(bytes[idx - 1]) } else { None };
                let next = if idx + 1 < bytes.len() {
                    Some(bytes[idx + 1])
                } else {
                    None
                };
                let prev_bad = prev.is_some_and(|b| {
                    matches!(
                        b,
                        b'=' | b'!' | b'<' | b'>' | b'+' | b'-' | b'*' | b'/' | b'%' | b'&' | b'|' | b'^'
                    )
                });
                let next_bad = next.is_some_and(|b| b == b'=' || b == b'>');
                if !prev_bad && !next_bad {
                    return Some(idx);
                }
                idx += 1;
            }
            None
        }

        fn extract_assignment_lhs(line: &str, eq_idx: usize) -> String {
            let prefix = &line[..eq_idx];
            let start = prefix
                .rfind('{')
                .map(|i| i + 1)
                .unwrap_or_else(|| prefix.rfind(';').map(|i| i + 1).unwrap_or(0));
            prefix[start..].trim().to_string()
        }

        fn rewrite_rhs_pointer_cast_targets(rhs: &str, lhs_ptr_ty: &str) -> String {
            if !rhs.contains(" as *mut ") && !rhs.contains(" as *const ") {
                return rhs.to_string();
            }
            let mut rewritten = rhs.to_string();
            for marker in [" as *mut ", " as *const "] {
                let mut idx = 0usize;
                while let Some(rel) = rewritten[idx..].find(marker) {
                    let start = idx + rel;
                    let type_start = start + " as ".len();
                    let mut type_end = type_start;
                    while type_end < rewritten.len() {
                        let ch = rewritten[type_end..].chars().next().unwrap();
                        if AstCodeGen::is_identifier_char(ch)
                            || matches!(ch, ':' | '<' | '>' | ',' | ' ')
                        {
                            type_end += ch.len_utf8();
                        } else {
                            break;
                        }
                    }
                    let cast_ty = rewritten[type_start..type_end].trim();
                    if cast_ty.starts_with("*mut ") || cast_ty.starts_with("*const ") {
                        if cast_ty != lhs_ptr_ty {
                            let replacement = format!("as {}", lhs_ptr_ty);
                            rewritten.replace_range(start..type_end, &format!(" {}", replacement));
                            idx = start + replacement.len() + 1;
                            continue;
                        }
                    }
                    idx = type_end;
                }
            }
            rewritten
        }

        let lines: Vec<&str> = code.lines().collect();
        if lines.is_empty() {
            return code.to_string();
        }
        let struct_field_types = parse_struct_field_types(code);
        let impl_targets = collect_impl_target_per_line(&lines);

        let mut out = String::with_capacity(code.len());
        let mut i = 0usize;
        while i < lines.len() {
            let line = lines[i];
            let trimmed = line.trim_end();
            let is_fn_start =
                (trimmed.contains(" fn ") || trimmed.starts_with("fn ")) && trimmed.ends_with('{');
            if !is_fn_start {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }
            let mut j = i;
            let mut depth = 0isize;
            while j < lines.len() {
                let current = lines[j];
                depth += current.chars().filter(|c| *c == '{').count() as isize;
                depth -= current.chars().filter(|c| *c == '}').count() as isize;
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            if j >= lines.len() || depth != 0 {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let body_lines: &[&str] = if j > i + 1 { &lines[i + 1..j] } else { &[] };
            let binding_types = collect_binding_types(trimmed, body_lines);
            let impl_field_types = impl_targets
                .get(i)
                .and_then(|t| t.as_ref())
                .and_then(|target| struct_field_types.get(target))
                .cloned()
                .unwrap_or_default();

            out.push_str(lines[i]);
            out.push('\n');
            for body_line in body_lines {
                let mut rewritten = body_line.to_string();
                if let Some(eq_idx) = find_assignment_eq(&rewritten) {
                    let lhs = extract_assignment_lhs(&rewritten, eq_idx);
                    if let Some(lhs_ptr_ty) = lhs_pointer_type(&lhs, &binding_types, &impl_field_types)
                    {
                        let rhs_start = eq_idx + 1;
                        let rhs = rewritten[rhs_start..].to_string();
                        let normalized_rhs = rewrite_rhs_pointer_cast_targets(&rhs, &lhs_ptr_ty);
                        if normalized_rhs != rhs {
                            rewritten.replace_range(rhs_start.., &normalized_rhs);
                        }
                    }
                }
                out.push_str(&rewritten);
                out.push('\n');
            }
            out.push_str(lines[j]);
            if j + 1 < lines.len() || code.ends_with('\n') {
                out.push('\n');
            }
            i = j + 1;
        }

        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    /// If a function has a local `width` binding but the impl type has no
    /// `width` field, normalize degraded `self.width` references back to that
    /// local binding.
    fn normalize_width_field_reference_aliases(code: &str) -> String {
        fn parse_struct_fields(code: &str) -> HashMap<String, HashSet<String>> {
            let lines: Vec<&str> = code.lines().collect();
            let mut out = HashMap::new();
            let mut i = 0usize;
            while i < lines.len() {
                let trimmed = lines[i].trim_start();
                let Some(rest) = trimmed
                    .strip_prefix("pub struct ")
                    .or_else(|| trimmed.strip_prefix("struct "))
                else {
                    i += 1;
                    continue;
                };
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                if name.is_empty() || !trimmed.ends_with('{') {
                    i += 1;
                    continue;
                }
                let mut fields = HashSet::new();
                let mut depth = 1isize;
                let mut j = i + 1;
                while j < lines.len() && depth > 0 {
                    let current = lines[j];
                    let current_trim = current.trim();
                    if depth == 1
                        && !current_trim.starts_with("//")
                        && !current_trim.starts_with("///")
                        && !current_trim.starts_with("#[")
                    {
                        let mut field_src = current_trim;
                        if let Some(rest) = field_src.strip_prefix("pub(") {
                            if let Some(close_idx) = rest.find(')') {
                                field_src = rest[close_idx + 1..].trim_start();
                            }
                        } else if let Some(rest) = field_src.strip_prefix("pub ") {
                            field_src = rest.trim_start();
                        }
                        if let Some((lhs, _)) = field_src.split_once(':') {
                            let field = lhs.trim().trim_start_matches("r#");
                            if !field.is_empty() {
                                fields.insert(field.to_string());
                            }
                        }
                    }
                    depth += current.chars().filter(|c| *c == '{').count() as isize;
                    depth -= current.chars().filter(|c| *c == '}').count() as isize;
                    j += 1;
                }
                out.insert(name.trim_start_matches("r#").to_string(), fields);
                i = j;
            }
            out
        }

        fn parse_impl_target(line: &str) -> Option<String> {
            let trimmed = line.trim_start();
            let rest = trimmed.strip_prefix("impl ")?;
            if !trimmed.ends_with('{') {
                return None;
            }
            let target_src = rest.split('{').next()?.trim();
            let target_src = if let Some((_, rhs)) = target_src.split_once(" for ") {
                rhs.trim()
            } else {
                target_src
            };
            let token = target_src.split_whitespace().next().unwrap_or(target_src);
            let token = token.split('<').next().unwrap_or(token).trim();
            if token.is_empty() {
                None
            } else {
                Some(token.trim_start_matches("r#").to_string())
            }
        }

        fn collect_impl_target_per_line(lines: &[&str]) -> Vec<Option<String>> {
            let mut out = vec![None; lines.len()];
            let mut depth = 0i32;
            let mut stack: Vec<(i32, String)> = Vec::new();
            for (idx, line) in lines.iter().enumerate() {
                while stack
                    .last()
                    .is_some_and(|(start_depth, _)| *start_depth > depth)
                {
                    stack.pop();
                }
                out[idx] = stack.last().map(|(_, name)| name.clone());

                if let Some(target) = parse_impl_target(line) {
                    stack.push((depth + 1, target));
                }
                let open_count = line.chars().filter(|c| *c == '{').count() as i32;
                let close_count = line.chars().filter(|c| *c == '}').count() as i32;
                depth += open_count - close_count;
                if depth < 0 {
                    depth = 0;
                }
                while stack
                    .last()
                    .is_some_and(|(start_depth, _)| *start_depth > depth)
                {
                    stack.pop();
                }
            }
            out
        }

        fn has_local_width_binding(body_lines: &[&str]) -> bool {
            body_lines.iter().any(|line| {
                let trimmed = line.trim_start();
                let Some(after_let) = trimmed.strip_prefix("let ") else {
                    return false;
                };
                let mut rest = after_let.trim_start();
                if let Some(stripped) = rest.strip_prefix("mut ") {
                    rest = stripped.trim_start();
                }
                rest.starts_with("width")
                    && rest["width".len()..]
                        .chars()
                        .next()
                        .is_some_and(|c| c == ':' || c.is_whitespace())
            })
        }

        let lines: Vec<&str> = code.lines().collect();
        if lines.is_empty() {
            return code.to_string();
        }
        let struct_fields = parse_struct_fields(code);
        let impl_targets = collect_impl_target_per_line(&lines);

        let mut out = String::with_capacity(code.len());
        let mut i = 0usize;
        while i < lines.len() {
            let line = lines[i];
            let trimmed = line.trim_end();
            let is_fn_start =
                (trimmed.contains(" fn ") || trimmed.starts_with("fn ")) && trimmed.ends_with('{');
            if !is_fn_start {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let mut j = i;
            let mut depth = 0isize;
            while j < lines.len() {
                let current = lines[j];
                depth += current.chars().filter(|c| *c == '{').count() as isize;
                depth -= current.chars().filter(|c| *c == '}').count() as isize;
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            if j >= lines.len() || depth != 0 {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let body_lines: &[&str] = if j > i + 1 { &lines[i + 1..j] } else { &[] };
            let impl_target = impl_targets.get(i).and_then(|t| t.as_ref()).cloned();
            let has_width_field = impl_target
                .as_ref()
                .and_then(|name| struct_fields.get(name))
                .is_some_and(|fields| fields.contains("width"));
            let should_rewrite = !has_width_field && has_local_width_binding(body_lines);

            out.push_str(lines[i]);
            out.push('\n');
            for body_line in body_lines {
                let rewritten = if should_rewrite {
                    body_line
                        .replace("self.width", "width")
                        .replace("(*self).width", "width")
                } else {
                    (*body_line).to_string()
                };
                out.push_str(&rewritten);
                out.push('\n');
            }
            out.push_str(lines[j]);
            if j + 1 < lines.len() || code.ends_with('\n') {
                out.push('\n');
            }
            i = j + 1;
        }

        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    /// Degraded lowering can access pseudo-fields on primitive values
    /// (`x.v_`, `self.kx_.p`, etc.). Collapse those pseudo-fields to the
    /// primitive receiver expression.
    fn normalize_primitive_scalar_field_access_artifacts(code: &str) -> String {
        fn is_primitive_scalar_type(ty: &str) -> bool {
            matches!(
                ty.trim(),
                "u8"
                    | "u16"
                    | "u32"
                    | "u64"
                    | "u128"
                    | "usize"
                    | "i8"
                    | "i16"
                    | "i32"
                    | "i64"
                    | "i128"
                    | "isize"
                    | "f32"
                    | "f64"
                    | "bool"
                    | "char"
            )
        }

        fn parse_struct_primitive_fields(code: &str) -> HashMap<String, HashSet<String>> {
            let lines: Vec<&str> = code.lines().collect();
            let mut out = HashMap::new();
            let mut i = 0usize;
            while i < lines.len() {
                let trimmed = lines[i].trim_start();
                let Some(rest) = trimmed
                    .strip_prefix("pub struct ")
                    .or_else(|| trimmed.strip_prefix("struct "))
                else {
                    i += 1;
                    continue;
                };
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                if name.is_empty() || !trimmed.ends_with('{') {
                    i += 1;
                    continue;
                }
                let mut primitive_fields: HashSet<String> = HashSet::new();
                let mut depth = 1isize;
                let mut j = i + 1;
                while j < lines.len() && depth > 0 {
                    let current = lines[j];
                    let current_trim = current.trim();
                    if depth == 1
                        && !current_trim.starts_with("//")
                        && !current_trim.starts_with("///")
                        && !current_trim.starts_with("#[")
                    {
                        let mut field_src = current_trim;
                        if let Some(rest) = field_src.strip_prefix("pub(") {
                            if let Some(close_idx) = rest.find(')') {
                                field_src = rest[close_idx + 1..].trim_start();
                            }
                        } else if let Some(rest) = field_src.strip_prefix("pub ") {
                            field_src = rest.trim_start();
                        }
                        if let Some((lhs, rhs)) = field_src.split_once(':') {
                            let field = lhs.trim().trim_start_matches("r#");
                            let ty = rhs.trim().trim_end_matches(',').trim();
                            if !field.is_empty() && is_primitive_scalar_type(ty) {
                                primitive_fields.insert(field.to_string());
                            }
                        }
                    }
                    depth += current.chars().filter(|c| *c == '{').count() as isize;
                    depth -= current.chars().filter(|c| *c == '}').count() as isize;
                    j += 1;
                }
                if !primitive_fields.is_empty() {
                    out.insert(name.trim_start_matches("r#").to_string(), primitive_fields);
                }
                i = j;
            }
            out
        }

        fn parse_impl_target(line: &str) -> Option<String> {
            let trimmed = line.trim_start();
            let rest = trimmed.strip_prefix("impl ")?;
            if !trimmed.ends_with('{') {
                return None;
            }
            let target_src = rest.split('{').next()?.trim();
            let target_src = if let Some((_, rhs)) = target_src.split_once(" for ") {
                rhs.trim()
            } else {
                target_src
            };
            let token = target_src.split_whitespace().next().unwrap_or(target_src);
            let token = token.split('<').next().unwrap_or(token).trim();
            if token.is_empty() {
                None
            } else {
                Some(token.trim_start_matches("r#").to_string())
            }
        }

        fn collect_impl_target_per_line(lines: &[&str]) -> Vec<Option<String>> {
            let mut out = vec![None; lines.len()];
            let mut depth = 0i32;
            let mut stack: Vec<(i32, String)> = Vec::new();
            for (idx, line) in lines.iter().enumerate() {
                while stack
                    .last()
                    .is_some_and(|(start_depth, _)| *start_depth > depth)
                {
                    stack.pop();
                }
                out[idx] = stack.last().map(|(_, name)| name.clone());
                if let Some(target) = parse_impl_target(line) {
                    stack.push((depth + 1, target));
                }
                let open_count = line.chars().filter(|c| *c == '{').count() as i32;
                let close_count = line.chars().filter(|c| *c == '}').count() as i32;
                depth += open_count - close_count;
                if depth < 0 {
                    depth = 0;
                }
                while stack
                    .last()
                    .is_some_and(|(start_depth, _)| *start_depth > depth)
                {
                    stack.pop();
                }
            }
            out
        }

        fn collect_primitive_bindings(signature_line: &str, body_lines: &[&str]) -> HashSet<String> {
            let mut out = HashSet::new();
            let Some(open_idx) = signature_line.find('(') else {
                return out;
            };
            let Some(close_idx) = AstCodeGen::find_matching_close_paren(signature_line, open_idx)
            else {
                return out;
            };
            let params_src = &signature_line[open_idx + 1..close_idx];
            for param in AstCodeGen::split_top_level_list(params_src, ',') {
                let Some((lhs, rhs)) = param.split_once(':') else {
                    continue;
                };
                let mut name = lhs.trim();
                if let Some(stripped) = name.strip_prefix("mut ") {
                    name = stripped.trim();
                }
                name = name.trim_start_matches("r#");
                let ty = rhs.trim();
                if !name.is_empty() && is_primitive_scalar_type(ty) {
                    out.insert(name.to_string());
                }
            }
            for line in body_lines {
                let trimmed = line.trim_start();
                let Some(after_let) = trimmed.strip_prefix("let ") else {
                    continue;
                };
                let mut rest = after_let.trim_start();
                if let Some(stripped) = rest.strip_prefix("mut ") {
                    rest = stripped.trim_start();
                }
                let name: String = rest
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c) || *c == '#')
                    .collect();
                let Some(colon_idx) = rest.find(':') else {
                    continue;
                };
                let ty = rest[colon_idx + 1..]
                    .split('=')
                    .next()
                    .unwrap_or("")
                    .trim();
                if !name.is_empty() && is_primitive_scalar_type(ty) {
                    out.insert(name.trim_start_matches("r#").to_string());
                }
            }
            out
        }

        fn rewrite_receiver_field_accesses(line: &str, receiver: &str) -> String {
            let marker = format!("{}.", receiver);
            if !line.contains(&marker) {
                return line.to_string();
            }
            let mut rewritten = line.to_string();
            let mut idx = 0usize;
            while let Some(rel) = rewritten[idx..].find(&marker) {
                let start = idx + rel;
                let member_start = start + marker.len();
                let mut member_end = member_start;
                while member_end < rewritten.len() {
                    let ch = rewritten[member_end..].chars().next().unwrap();
                    if AstCodeGen::is_identifier_char(ch) || ch == '#' {
                        member_end += ch.len_utf8();
                    } else {
                        break;
                    }
                }
                if member_end == member_start {
                    idx = member_start;
                    continue;
                }
                let mut after_member = member_end;
                while after_member < rewritten.len()
                    && rewritten.as_bytes()[after_member].is_ascii_whitespace()
                {
                    after_member += 1;
                }
                if after_member < rewritten.len() && rewritten.as_bytes()[after_member] == b'(' {
                    idx = member_end;
                    continue;
                }
                rewritten.replace_range(start..member_end, receiver);
                idx = start + receiver.len();
            }
            rewritten
        }

        fn rewrite_primitive_binding_accesses(line: &str, primitive_bindings: &HashSet<String>) -> String {
            if primitive_bindings.is_empty() || !line.contains('.') {
                return line.to_string();
            }
            let mut rewritten = line.to_string();
            let mut idx = 0usize;
            while idx < rewritten.len() {
                let Some(dot_rel) = rewritten[idx..].find('.') else {
                    break;
                };
                let dot_idx = idx + dot_rel;
                if dot_idx == 0 {
                    idx = dot_idx + 1;
                    continue;
                }
                let bytes = rewritten.as_bytes();
                let mut recv_end = dot_idx;
                while recv_end > 0 && bytes[recv_end - 1].is_ascii_whitespace() {
                    recv_end -= 1;
                }
                let mut recv_start = recv_end;
                while recv_start > 0 {
                    let b = bytes[recv_start - 1];
                    if (b as char).is_ascii_alphanumeric() || b == b'_' || b == b'#' {
                        recv_start -= 1;
                    } else {
                        break;
                    }
                }
                if recv_start == recv_end {
                    idx = dot_idx + 1;
                    continue;
                }
                let receiver = rewritten[recv_start..recv_end]
                    .trim()
                    .trim_start_matches("r#");
                if !primitive_bindings.contains(receiver) {
                    idx = dot_idx + 1;
                    continue;
                }
                let member_start = dot_idx + 1;
                let mut member_end = member_start;
                while member_end < rewritten.len() {
                    let ch = rewritten[member_end..].chars().next().unwrap();
                    if AstCodeGen::is_identifier_char(ch) || ch == '#' {
                        member_end += ch.len_utf8();
                    } else {
                        break;
                    }
                }
                if member_end == member_start {
                    idx = member_start;
                    continue;
                }
                let mut after_member = member_end;
                while after_member < rewritten.len()
                    && rewritten.as_bytes()[after_member].is_ascii_whitespace()
                {
                    after_member += 1;
                }
                if after_member < rewritten.len() && rewritten.as_bytes()[after_member] == b'(' {
                    idx = member_end;
                    continue;
                }
                let receiver_src = rewritten[recv_start..recv_end].to_string();
                rewritten.replace_range(recv_start..member_end, &receiver_src);
                idx = recv_start + receiver_src.len();
            }
            rewritten
        }

        let lines: Vec<&str> = code.lines().collect();
        if lines.is_empty() {
            return code.to_string();
        }
        let struct_primitive_fields = parse_struct_primitive_fields(code);
        let impl_targets = collect_impl_target_per_line(&lines);

        let mut out = String::with_capacity(code.len());
        let mut i = 0usize;
        while i < lines.len() {
            let line = lines[i];
            let trimmed = line.trim_end();
            let is_fn_start =
                (trimmed.contains(" fn ") || trimmed.starts_with("fn ")) && trimmed.ends_with('{');
            if !is_fn_start {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }
            let mut j = i;
            let mut depth = 0isize;
            while j < lines.len() {
                let current = lines[j];
                depth += current.chars().filter(|c| *c == '{').count() as isize;
                depth -= current.chars().filter(|c| *c == '}').count() as isize;
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            if j >= lines.len() || depth != 0 {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }
            let body_lines: &[&str] = if j > i + 1 { &lines[i + 1..j] } else { &[] };
            let primitive_bindings = collect_primitive_bindings(trimmed, body_lines);
            let primitive_self_fields = impl_targets
                .get(i)
                .and_then(|t| t.as_ref())
                .and_then(|target| struct_primitive_fields.get(target))
                .cloned()
                .unwrap_or_default();
            let mut primitive_self_fields_sorted: Vec<String> =
                primitive_self_fields.into_iter().collect();
            primitive_self_fields_sorted
                .sort_by(|a, b| b.len().cmp(&a.len()).then(a.cmp(b)));

            out.push_str(lines[i]);
            out.push('\n');
            for body_line in body_lines {
                let mut rewritten = body_line.to_string();
                for field in &primitive_self_fields_sorted {
                    rewritten =
                        rewrite_receiver_field_accesses(&rewritten, &format!("self.{}", field));
                    rewritten = rewrite_receiver_field_accesses(
                        &rewritten,
                        &format!("(*self).{}", field),
                    );
                }
                rewritten = rewrite_primitive_binding_accesses(&rewritten, &primitive_bindings);
                out.push_str(&rewritten);
                out.push('\n');
            }
            out.push_str(lines[j]);
            if j + 1 < lines.len() || code.ends_with('\n') {
                out.push('\n');
            }
            i = j + 1;
        }

        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    fn normalize_unit_negation_artifacts(code: &str) -> String {
        code.replace("!()", "false").replace("(!())", "(false)")
    }

    fn normalize_unit_placeholder_expression_artifacts(code: &str) -> String {
        if !code.contains("()") {
            return code.to_string();
        }

        fn replace_standalone_unit_cast(haystack: &str, needle: &str, replacement: &str) -> String {
            if !haystack.contains(needle) {
                return haystack.to_string();
            }
            let bytes = haystack.as_bytes();
            let mut out = String::with_capacity(haystack.len());
            let mut i = 0usize;
            while i < haystack.len() {
                if haystack[i..].starts_with(needle) {
                    let prev = if i == 0 {
                        None
                    } else {
                        Some(bytes[i - 1] as char)
                    };
                    let prev_is_boundary = prev.is_none_or(|c| {
                        c.is_whitespace()
                            || c == '('
                            || c == '['
                            || c == '{'
                            || c == ','
                            || c == ';'
                            || c == '='
                            || c == ':'
                    });
                    if prev_is_boundary {
                        out.push_str(replacement);
                        i += needle.len();
                        continue;
                    }
                }
                let ch = haystack[i..].chars().next().unwrap();
                out.push(ch);
                i += ch.len_utf8();
            }
            out
        }

        let mut out = code.to_string();
        for ty in [
            "u8", "u16", "u32", "u64", "u128", "usize", "i8", "i16", "i32", "i64", "i128",
            "isize", "f32", "f64",
        ] {
            out = out.replace(&format!("((()) as {})", ty), &format!("(0 as {})", ty));
            out = out.replace(&format!("(() as {})", ty), &format!("(0 as {})", ty));
        }
        out = out.replace("(()as *const i8)", "(std::ptr::null() as *const i8)");
        out = out.replace("(() as *const i8)", "(std::ptr::null() as *const i8)");
        out = out.replace("(()as *mut i8)", "(std::ptr::null_mut() as *mut i8)");
        out = out.replace("(() as *mut i8)", "(std::ptr::null_mut() as *mut i8)");
        out = replace_standalone_unit_cast(&out, "()as *const i8", "std::ptr::null() as *const i8");
        out = replace_standalone_unit_cast(&out, "() as *const i8", "std::ptr::null() as *const i8");
        out = replace_standalone_unit_cast(&out, "()as *mut i8", "std::ptr::null_mut() as *mut i8");
        out = replace_standalone_unit_cast(&out, "() as *mut i8", "std::ptr::null_mut() as *mut i8");

        let mut rebuilt = String::with_capacity(out.len());
        for line in out.lines() {
            let mut rewritten = line.to_string();
            // Keep these rewrites in expression-context lines only.
            // Do not rewrite `< ()` / `> ()`: those textual patterns also
            // appear in generic/function-pointer type syntax (for example
            // `Option<extern "C" fn() -> ()>`), where expression rewrites
            // would corrupt item/type positions.
            if line.contains("while ")
                || line.contains("if ")
                || line.contains(" loop ")
                || line.trim_start().starts_with("while ")
                || line.trim_start().starts_with("if ")
            {
                // Expression-only repair for `x < ()` / `x > ()` placeholders.
                // Use a literal zero instead of `Default::default()` so the
                // comparison remains type-directed by the non-placeholder side.
                rewritten = rewritten.replace(" < ()", " < 0");
                rewritten = rewritten.replace(" > ()", " > 0");
                rewritten = rewritten.replace("(()- ", "(0u64 - ");
                rewritten = rewritten.replace("(() - ", "(0u64 - ");
            }
            // Constructor field initialization artifacts frequently emit unit
            // placeholders (`__self.field = ();`) for non-unit fields.
            if line.contains("__self.") {
                rewritten = rewritten.replace(" = ();", " = Default::default();");
            }
            rebuilt.push_str(&rewritten);
            rebuilt.push('\n');
        }
        if !code.ends_with('\n') && !rebuilt.is_empty() {
            rebuilt.pop();
        }
        rebuilt
    }

    fn normalize_placeholder_local_cast_returns(code: &str) -> String {
        if !code.contains("return (") || !code.contains("UnknownTagAutoType") {
            return code.to_string();
        }

        fn rewrite_placeholder_return(line: &str, placeholders: &HashSet<String>) -> String {
            let trimmed = line.trim();
            let Some(inner) = trimmed.strip_prefix("return (") else {
                return line.to_string();
            };
            let Some(end) = inner.find(") as ") else {
                return line.to_string();
            };
            let var_name = inner[..end].trim();
            if !placeholders.contains(var_name) {
                return line.to_string();
            }
            let indent_len = line.chars().take_while(|c| c.is_whitespace()).count();
            format!("{}return Default::default();", &line[..indent_len])
        }

        let mut placeholders: HashSet<String> = HashSet::new();
        for line in code.lines() {
            let trimmed = line.trim();
            let Some(after) = trimmed.strip_prefix("let mut ") else {
                continue;
            };
            let name: String = after
                .chars()
                .take_while(|c| AstCodeGen::is_identifier_char(*c))
                .collect();
            if name.is_empty() {
                continue;
            }
            if trimmed.contains(": UnknownTagAutoType")
                || trimmed.contains("= unsafe { std::mem::zeroed() }")
                || trimmed.contains("= unsafe { Default::default() }")
                || trimmed.contains("= Default::default()")
            {
                placeholders.insert(name);
            }
        }

        if placeholders.is_empty() {
            return code.to_string();
        }

        let lines: Vec<&str> = code.lines().collect();
        let mut out = String::with_capacity(code.len());
        for (idx, line) in lines.iter().enumerate() {
            let rewritten = rewrite_placeholder_return(line, &placeholders);
            out.push_str(&rewritten);
            if idx + 1 < lines.len() || code.ends_with('\n') {
                out.push('\n');
            }
        }

        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

    fn normalize_out_of_range_i8_literal_casts(code: &str) -> String {
        if !code.contains(" as i8") {
            return code.to_string();
        }
        let mut out = code.to_string();
        for value in 128..=255 {
            out = out.replace(
                &format!("({value}) as i8"),
                &format!("({value}u8) as i8"),
            );
        }
        out
    }

    fn normalize_nonprimitive_local_return_casts(code: &str) -> String {
        if !code.contains("return (") || !code.contains(") as ") {
            return code.to_string();
        }

        fn is_primitive_type_name(ty: &str) -> bool {
            matches!(
                ty,
                "u8"
                    | "u16"
                    | "u32"
                    | "u64"
                    | "u128"
                    | "usize"
                    | "i8"
                    | "i16"
                    | "i32"
                    | "i64"
                    | "i128"
                    | "isize"
                    | "f32"
                    | "f64"
                    | "bool"
                    | "char"
                    | "()"
            )
        }

        let lines: Vec<&str> = code.lines().collect();
        if lines.is_empty() {
            return code.to_string();
        }

        let mut out = String::with_capacity(code.len());
        let mut i = 0usize;
        while i < lines.len() {
            let line = lines[i];
            let trimmed = line.trim_end();
            let is_fn_start =
                (trimmed.contains(" fn ") || trimmed.starts_with("fn ")) && trimmed.ends_with('{');
            if !is_fn_start {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let mut j = i;
            let mut depth = 0isize;
            while j < lines.len() {
                let current = lines[j];
                depth += current.chars().filter(|c| *c == '{').count() as isize;
                depth -= current.chars().filter(|c| *c == '}').count() as isize;
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            if j >= lines.len() || depth != 0 {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let mut typed_nonprimitive_locals: HashSet<String> = HashSet::new();
            for body_line in &lines[i + 1..j] {
                let trimmed = body_line.trim();
                if !(trimmed.starts_with("let ") && trimmed.contains(':') && trimmed.contains('=')) {
                    continue;
                }
                let after_let = trimmed
                    .strip_prefix("let mut ")
                    .or_else(|| trimmed.strip_prefix("let "));
                let Some(after_let) = after_let else {
                    continue;
                };
                let name: String = after_let
                    .chars()
                    .take_while(|c| AstCodeGen::is_identifier_char(*c))
                    .collect();
                if name.is_empty() {
                    continue;
                }
                let Some((_, rhs)) = trimmed.split_once(':') else {
                    continue;
                };
                let ty = rhs.split('=').next().unwrap_or(rhs).trim();
                if ty.is_empty()
                    || is_primitive_type_name(ty)
                    || ty.starts_with('*')
                    || ty.starts_with('&')
                {
                    continue;
                }
                typed_nonprimitive_locals.insert(name);
            }

            out.push_str(lines[i]);
            out.push('\n');
            for k in i + 1..j {
                let body_line = lines[k];
                let mut rewritten = body_line.to_string();
                let trimmed_body = body_line.trim();
                if let Some(inner) = trimmed_body.strip_prefix("return (") {
                    if let Some(cast_pos) = inner.find(") as ") {
                        let expr = inner[..cast_pos].trim();
                        if typed_nonprimitive_locals.contains(expr)
                            || expr.contains("super::to_string(")
                            || expr.contains("std::to_string(")
                        {
                            let indent_len =
                                body_line.len().saturating_sub(body_line.trim_start().len());
                            rewritten =
                                format!("{}return Default::default();", &body_line[..indent_len]);
                        }
                    }
                }
                out.push_str(&rewritten);
                out.push('\n');
            }
            out.push_str(lines[j]);
            if j + 1 < lines.len() || code.ends_with('\n') {
                out.push('\n');
            }
            i = j + 1;
        }
        if !code.ends_with('\n') && out.ends_with('\n') {
            out.pop();
        }
        out
    }

    fn normalize_clamp_ref_numeric_reference_artifacts(code: &str) -> String {
        if !code.contains("pub fn clamp_ref_") {
            return code.to_string();
        }

        fn is_numeric_primitive(ty: &str) -> bool {
            matches!(
                ty,
                "i8"
                    | "i16"
                    | "i32"
                    | "i64"
                    | "i128"
                    | "isize"
                    | "u8"
                    | "u16"
                    | "u32"
                    | "u64"
                    | "u128"
                    | "usize"
                    | "f32"
                    | "f64"
            )
        }

        fn parse_ref_param_type(sig: &str, name: &str) -> Option<String> {
            let params_src = sig
                .split_once('(')?
                .1
                .split_once(')')?
                .0;
            for param in AstCodeGen::split_top_level_list(params_src, ',') {
                let (lhs, rhs) = param.split_once(':')?;
                if lhs.trim() == name {
                    let rhs = rhs.trim();
                    let inner = rhs.strip_prefix('&')?.trim_start();
                    if is_numeric_primitive(inner) {
                        return Some(inner.to_string());
                    }
                    return None;
                }
            }
            None
        }

        let lines: Vec<&str> = code.lines().collect();
        if lines.is_empty() {
            return code.to_string();
        }

        let mut out = String::with_capacity(code.len());
        let mut i = 0usize;
        while i < lines.len() {
            let line = lines[i];
            let trimmed = line.trim_end();
            let is_target_fn = trimmed.starts_with("pub fn clamp_ref_")
                && trimmed.contains("->")
                && trimmed.ends_with('{');
            if !is_target_fn {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let Some((_, ret_tail)) = trimmed.split_once("->") else {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            };
            let ret_ty = ret_tail.trim().trim_end_matches('{').trim();
            if !is_numeric_primitive(ret_ty) {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let Some(v_ty) = parse_ref_param_type(trimmed, "v") else {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            };
            let Some(lower_ty) = parse_ref_param_type(trimmed, "lower") else {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            };
            let Some(upper_ty) = parse_ref_param_type(trimmed, "upper") else {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            };
            if !is_numeric_primitive(&v_ty)
                || !is_numeric_primitive(&lower_ty)
                || !is_numeric_primitive(&upper_ty)
            {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let mut j = i;
            let mut depth = 0isize;
            while j < lines.len() {
                let current = lines[j];
                depth += current.chars().filter(|c| *c == '{').count() as isize;
                depth -= current.chars().filter(|c| *c == '}').count() as isize;
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            if j >= lines.len() || depth != 0 {
                out.push_str(line);
                if i + 1 < lines.len() || code.ends_with('\n') {
                    out.push('\n');
                }
                i += 1;
                continue;
            }

            let cast_v = format!("(unsafe {{ (*v) as {} }})", ret_ty);
            let cast_lower = format!("(unsafe {{ (*lower) as {} }})", ret_ty);
            let cast_upper = format!("(unsafe {{ (*upper) as {} }})", ret_ty);

            out.push_str(lines[i]);
            out.push('\n');
            for k in i + 1..j {
                let body_line = lines[k];
                let trimmed_body = body_line.trim();
                let indent_len = body_line
                    .len()
                    .saturating_sub(body_line.trim_start().len());
                let indent = &body_line[..indent_len];
                let rewritten = if trimmed_body == "return unsafe { lower };" {
                    format!("{indent}return unsafe {{ (*lower) as {} }};", ret_ty)
                } else if trimmed_body == "return unsafe { upper };" {
                    format!("{indent}return unsafe {{ (*upper) as {} }};", ret_ty)
                } else if trimmed_body == "return unsafe { v };" {
                    format!("{indent}return unsafe {{ (*v) as {} }};", ret_ty)
                } else {
                    body_line
                        .replace("(unsafe { v })", &cast_v)
                        .replace("(unsafe { lower })", &cast_lower)
                        .replace("(unsafe { upper })", &cast_upper)
                };
                out.push_str(&rewritten);
                out.push('\n');
            }
            out.push_str(lines[j]);
            if j + 1 < lines.len() || code.ends_with('\n') {
                out.push('\n');
            }
            i = j + 1;
        }

        if !code.ends_with('\n') && out.ends_with('\n') {
            out.pop();
        }
        out
    }

    fn normalize_make_box_ref_zeroed_box_ident_artifacts(code: &str) -> String {
        const NEEDLE: &str = "std::mem::zeroed::<std::boxed::Box<";
        if !code.contains(NEEDLE) {
            return code.to_string();
        }

        let mut out = String::with_capacity(code.len());
        for line in code.lines() {
            let mut rewritten = line.to_string();
            let mut scan = 0usize;
            while let Some(rel) = rewritten[scan..].find(NEEDLE) {
                let start = scan + rel;
                let inner_start = start + NEEDLE.len();
                let Some(close_rel) = rewritten[inner_start..].find(">>()") else {
                    break;
                };
                let inner_end = inner_start + close_rel;
                let ident = rewritten[inner_start..inner_end].trim();
                if ident.is_empty() || !ident.chars().all(Self::is_identifier_char) {
                    scan = inner_end + ">>()".len();
                    continue;
                }
                let replacement = format!(
                    "std::boxed::Box::new(unsafe {{ std::mem::zeroed::<{}>() }})",
                    ident
                );
                rewritten.replace_range(start..inner_end + ">>()".len(), &replacement);
                scan = start + replacement.len();
            }
            out.push_str(&rewritten);
            out.push('\n');
        }
        if !code.ends_with('\n') && !out.is_empty() {
            out.pop();
        }
        out
    }

