                    self.writeln("}");
                    self.writeln("let start = idx;");
                    self.writeln("while idx < bytes.len() && ((base == 16 && bytes[idx].is_ascii_hexdigit()) || (base == 10 && bytes[idx].is_ascii_digit())) {");
                    self.indent += 1;
