    /// Generate Rust stubs (signatures only, no bodies) from a Clang AST.
    /// This is useful for FFI declarations and header generation.
    pub fn generate_stubs(mut self, ast: &ClangNode) -> String {
        // File header
        self.writeln("// Auto-generated Rust stubs from C++ code");
        self.writeln("#![allow(dead_code)]");
        self.writeln("#![allow(unused_variables)]");
        self.writeln("");

        // Process translation unit
        if let ClangNodeKind::TranslationUnit = &ast.kind {
            for child in &ast.children {
                self.generate_stub_top_level(child);
            }
        }

        self.output
    }

    /// Generate a top-level stub declaration (signatures only).
    fn generate_stub_top_level(&mut self, node: &ClangNode) {
        match &node.kind {
            ClangNodeKind::FunctionDecl {
                name,
                mangled_name,
                return_type,
                params,
                is_definition,
                is_variadic,
                ..
            } => {
                if *is_definition {
                    self.generate_function_stub(
                        name,
                        mangled_name,
                        return_type,
                        params,
                        *is_variadic,
                    );
                }
            }
            ClangNodeKind::RecordDecl {
                name,
                is_class,
                is_definition,
                ..
            } => {
                // Only generate struct stub for definitions
                if *is_definition {
                    self.generate_struct_stub(name, *is_class, &node.children);
                }
            }
            ClangNodeKind::EnumDecl {
                name,
                is_scoped,
                underlying_type,
            } => {
                self.generate_enum_stub(name, *is_scoped, underlying_type, &node.children);
            }
            ClangNodeKind::UnionDecl { name, .. } => {
                self.generate_union_stub(name, &node.children);
            }
            ClangNodeKind::NamespaceDecl { name, .. } => {
                // Generate Rust module for namespace stubs
                if let Some(ns_name) = name {
                    // Skip internal namespaces or flatten them into the global scope
                    // std namespace is flattened, __ prefixed are internal, pmr has memory_resource issues
                    if ns_name.starts_with("__") || ns_name == "std" || ns_name == "pmr" {
                        for child in &node.children {
                            self.generate_stub_top_level(child);
                        }
                    } else {
                        self.writeln(&format!("pub mod {} {{", sanitize_identifier(ns_name)));
                        self.indent += 1;
                        // Re-export parent module items for name resolution
                        self.writeln("use super::*;");
                        for child in &node.children {
                            self.generate_stub_top_level(child);
                        }
                        self.indent -= 1;
                        self.writeln("}");
                        self.writeln("");
                    }
                } else {
                    for child in &node.children {
                        self.generate_stub_top_level(child);
                    }
                }
            }
            ClangNodeKind::LinkageSpecDecl => {
                // `extern "C" { ... }` is a transparent container.
                for child in &node.children {
                    self.generate_stub_top_level(child);
                }
            }
            _ => {}
        }
    }

    /// Generate a function stub (signature with placeholder body).
    fn generate_function_stub(
        &mut self,
        name: &str,
        mangled_name: &str,
        return_type: &CppType,
        params: &[(String, CppType)],
        is_variadic: bool,
    ) {
        self.writeln(&format!("/// @fragile_cpp_mangled: {}", mangled_name));
        self.writeln(&format!("#[export_name = \"{}\"]", mangled_name));

        // Deduplicate parameter names (C++ allows unnamed params, Rust doesn't)
        let mut param_name_counts: HashMap<String, usize> = HashMap::new();
        let params_str = params
            .iter()
            .map(|(n, t)| {
                let mut param_name = sanitize_identifier(n);
                let count = param_name_counts.entry(param_name.clone()).or_insert(0);
                if *count > 0 {
                    param_name = format!("{}_{}", param_name, *count);
                }
                *param_name_counts.get_mut(&sanitize_identifier(n)).unwrap() += 1;
                format!("{}: {}", param_name, t.to_rust_type_str())
            })
            .collect::<Vec<_>>()
            .join(", ");

        // Add variadic indicator for C variadic functions
        let params_with_variadic = if is_variadic {
            if params_str.is_empty() {
                "...".to_string()
            } else {
                format!("{}, ...", params_str)
            }
        } else {
            params_str
        };

        let ret_str = if *return_type == CppType::Void {
            String::new()
        } else {
            format!(
                " -> {}",
                Self::sanitize_return_type(&return_type.to_rust_type_str())
            )
        };

        // Variadic extern "C" functions require unsafe in Rust
        let unsafe_keyword = if is_variadic { "unsafe " } else { "" };
        self.writeln(&format!(
            "pub {}extern \"C\" fn {}({}){} {{",
            unsafe_keyword,
            sanitize_identifier(name),
            params_with_variadic,
            ret_str
        ));
        self.indent += 1;
        self.writeln("// Stub body - replaced by MIR injection at compile time");
        self.writeln("unreachable!(\"Fragile: C++ MIR should be injected\")");
        self.indent -= 1;
        self.writeln("}");
        self.writeln("");
    }

    /// Generate a struct stub (fields only).
    fn generate_struct_stub(&mut self, name: &str, is_class: bool, children: &[ClangNode]) {
        // Convert C++ struct name to valid Rust identifier (handles template types)
        let rust_name = CppType::Named(name.to_string()).to_rust_type_str();

        // Skip template DEFINITIONS that have unresolved type parameters
        if Self::has_unresolved_template_placeholder(name) {
            return;
        }

        // Skip deep STL internal types that cause compilation issues
        if name.contains("__normal_iterator")
            || name.contains("__wrap_iter")
            || name.contains("allocator_traits<allocator<void>")
            || name.contains("allocator_traits<std::allocator<void>")
            || name.contains("numeric_limits<ranges::__detail::")
            || name.contains("hash<float>")
            || name.contains("hash<double>")
            || name.contains("hash<long double>")
            || name.contains("memory_resource")
            || name.contains("__uninitialized_copy")
            || name.contains("_Bit_iterator")  // Bit iterator has op_index returning c_void
            || name.contains("_Bit_const_iterator")
        {
            return;
        }

        self.register_namespace_type_alias(&rust_name);

        // Skip if already generated (handles duplicate template instantiations)
        if self.generated_structs.contains(&rust_name) {
            if !self.current_rust_module_path().is_empty() {
                self.namespace_type_alias_conflicts
                    .insert(rust_name.clone());
            }
            return;
        }
        self.generated_structs.insert(rust_name.clone());
        if self.current_rust_module_path().is_empty() {
            self.global_type_names.insert(rust_name.clone());
        }

        // Emit nested union declarations when a named field in this record uses that
        // union type (e.g., `union { ... } fc;` in zlib's `ct_data_s`).
        for child in children {
            if let ClangNodeKind::UnionDecl {
                name: union_name, ..
            } = &child.kind
            {
                if Self::record_has_field_backed_by_union(children, union_name) {
                    self.generate_union_stub(union_name, &child.children);
                }
            }
        }

        // Emit nested enum declarations before field/method emission so class-local
        // enum references resolve in the generated struct body and impl methods.
        self.generate_record_nested_enums(name, children, true);

        let kind = if is_class { "class" } else { "struct" };
        self.writeln(&format!("/// C++ {} `{}`", kind, name));
        self.writeln("#[repr(C)]");
        self.writeln(&format!("pub struct {} {{", rust_name));
        self.indent += 1;

        // Add vtable pointer for ROOT polymorphic classes (those without a polymorphic base)
        // Derived classes inherit the vtable pointer through __base
        if let Some(vtable_info) = self.vtables.get(name).cloned() {
            if vtable_info.base_class.is_none() {
                // This is a root polymorphic class - add vtable pointer as first field
                self.writeln(&format!("pub __vtable: *const {}_vtable,", rust_name));
            }
        }

        // First, embed non-virtual base classes as fields (supports multiple inheritance)
        // Also collect base fields for class_fields tracking
        let mut base_fields = Vec::new();
        let mut base_idx = 0;
        for child in children {
            if let ClangNodeKind::CXXBaseSpecifier {
                base_type,
                access,
                is_virtual,
                ..
            } = &child.kind
            {
                // Always include base class fields regardless of C++ access specifier
                // (private inheritance still requires the base subobject for correct layout)
                if *is_virtual {
                    continue;
                }
                let base_name = base_type.to_rust_type_str();
                // Use __base for single inheritance, __base0/__base1/etc for MI
                let field_name = if base_idx == 0 {
                    "__base".to_string()
                } else {
                    format!("__base{}", base_idx)
                };
                // Use pub(crate) for private inheritance, pub otherwise
                let vis = if matches!(access, crate::ast::AccessSpecifier::Private) {
                    "pub(crate) "
                } else {
                    "pub "
                };
                self.writeln(&format!("{}{}: {},", vis, field_name, base_name));
                base_fields.push((field_name, base_type.clone()));
                base_idx += 1;
            }
        }

        // Add virtual base pointers and storage if needed
        let vbases_to_add = self.virtual_bases.get(name).cloned().unwrap_or_default();
        for vb in &vbases_to_add {
            let field = self.virtual_base_field_name(vb);
            let storage = self.virtual_base_storage_field_name(vb);
            self.writeln(&format!("pub {}: *mut {},", field, vb));
            self.writeln(&format!("pub {}: Option<Box<{}>>,", storage, vb));
        }

        // Then add derived class fields (including flattened anonymous struct fields)
        let mut fields = Vec::new();
        for child in children {
            if let ClangNodeKind::FieldDecl {
                name: field_name,
                ty,
                access,
                ..
            } = &child.kind
            {
                let sanitized_name = if field_name.is_empty() {
                    "_field".to_string()
                } else {
                    sanitize_identifier(field_name)
                };
                let effective_ty = if (name == "stat"
                    || name == "stat64"
                    || name.ends_with("stat")
                    || name.ends_with("stat64"))
                    && matches!(field_name.as_str(), "st_atim" | "st_mtim" | "st_ctim")
                {
                    CppType::Named("timespec".to_string())
                } else {
                    ty.clone()
                };
                let vis = access_to_visibility(*access);
                self.writeln(&format!(
                    "{}{}: {},",
                    vis,
                    sanitized_name,
                    effective_ty.to_rust_type_str_for_field()
                ));
                fields.push((sanitized_name, effective_ty));
            } else if let ClangNodeKind::RecordDecl {
                name: anon_name, ..
            } = &child.kind
            {
                // Flatten anonymous struct fields into parent
                if anon_name.starts_with("(anonymous") || anon_name.starts_with("__anon_") {
                    for anon_child in &child.children {
                        if let ClangNodeKind::FieldDecl {
                            name: field_name,
                            ty,
                            access,
                            ..
                        } = &anon_child.kind
                        {
                            let sanitized_name = if field_name.is_empty() {
                                "_field".to_string()
                            } else {
                                sanitize_identifier(field_name)
                            };
                            let vis = access_to_visibility(*access);
                            self.writeln(&format!(
                                "{}{}: {},",
                                vis,
                                sanitized_name,
                                ty.to_rust_type_str_for_field()
                            ));
                            fields.push((sanitized_name, ty.clone()));
                        }
                    }
                }
            } else if let ClangNodeKind::UnionDecl {
                name: anon_name, ..
            } = &child.kind
            {
                // Flatten anonymous union fields into parent
                // In C++, anonymous unions allow direct access to their members from the parent
                if anon_name.starts_with("(anonymous") || anon_name.starts_with("__anon_union_") {
                    for anon_child in &child.children {
                        if let ClangNodeKind::FieldDecl {
                            name: field_name,
                            ty,
                            access,
                            ..
                        } = &anon_child.kind
                        {
                            let sanitized_name = if field_name.is_empty() {
                                "_field".to_string()
                            } else {
                                sanitize_identifier(field_name)
                            };
                            let vis = access_to_visibility(*access);
                            self.writeln(&format!(
                                "{}{}: {},",
                                vis,
                                sanitized_name,
                                ty.to_rust_type_str_for_field()
                            ));
                            fields.push((sanitized_name, ty.clone()));
                        }
                    }
                }
            }
        }
        // Store field info for constructor generation (including base fields)
        let mut all_fields = base_fields;
        all_fields.extend(fields);
        self.class_fields.insert(name.to_string(), all_fields);

        self.indent -= 1;
        self.writeln("}");
        self.writeln("");
    }

    /// Normalize nested record type names to the enum base name used by class-local
    /// references while preserving compatibility aliases for fully-qualified spellings.
    fn normalize_nested_record_type_name(record_name: &str, nested_name: &str) -> String {
        let nested = nested_name.trim();
        if nested.is_empty() {
            return nested.to_string();
        }

        if nested.contains("::") {
            if let Some(last) = nested.rsplit("::").next() {
                if !last.is_empty() {
                    return last.to_string();
                }
            }
        }

        let record_full_flat = record_name.replace("::", "_");
        if !record_full_flat.is_empty() {
            let prefix = format!("{}_", record_full_flat);
            if let Some(rest) = nested.strip_prefix(&prefix) {
                if !rest.is_empty() {
                    return rest.to_string();
                }
            }
        }

        let record_unqualified = record_name.rsplit("::").next().unwrap_or(record_name);
        let record_unqualified_flat = record_unqualified.replace("::", "_");
        if !record_unqualified_flat.is_empty() {
            let prefix = format!("{}_", record_unqualified_flat);
            if let Some(rest) = nested.strip_prefix(&prefix) {
                if !rest.is_empty() {
                    return rest.to_string();
                }
            }
        }

        nested.to_string()
    }

    /// Generate nested enum declarations found inside a record/class declaration.
    /// For qualified/flattened nested enum spellings, emit a compatibility type
    /// alias back to the emitted base enum name.
    fn generate_record_nested_enums(
        &mut self,
        record_name: &str,
        children: &[ClangNode],
        as_stub: bool,
    ) {
        for child in children {
            let ClangNodeKind::EnumDecl {
                name: enum_name,
                is_scoped,
                underlying_type,
            } = &child.kind
            else {
                continue;
            };

            let emitted_name = Self::normalize_nested_record_type_name(record_name, enum_name);
            if as_stub {
                self.generate_enum_stub(
                    &emitted_name,
                    *is_scoped,
                    underlying_type,
                    &child.children,
                );
            } else {
                self.generate_enum(&emitted_name, *is_scoped, underlying_type, &child.children);
            }

            let original_rust_name = CppType::Named(enum_name.clone()).to_rust_type_str();
            let emitted_rust_name = CppType::Named(emitted_name).to_rust_type_str();
            if original_rust_name.is_empty()
                || original_rust_name == emitted_rust_name
                || self.generated_aliases.contains(&original_rust_name)
                || self.generated_structs.contains(&original_rust_name)
                || self.generated_enums.contains(&original_rust_name)
            {
                continue;
            }

            self.writeln(&format!(
                "pub type {} = {};",
                original_rust_name, emitted_rust_name
            ));
            self.writeln("");
            self.generated_aliases.insert(original_rust_name);
        }
    }

    /// Generate an enum stub.
    fn generate_enum_stub(
        &mut self,
        name: &str,
        is_scoped: bool,
        underlying_type: &CppType,
        children: &[ClangNode],
    ) {
        // Skip enums with known duplicate discriminant issues
        if name == "__memory_order_modifier" {
            return;
        }

        let kind = if is_scoped { "enum class" } else { "enum" };
        self.writeln(&format!("/// C++ {} `{}`", kind, name));

        // Generate as Rust enum
        // Use a valid primitive type for repr - fall back to i32 if the type is not a standard primitive
        let repr_type = match underlying_type.to_rust_type_str().as_str() {
            "i8" | "i16" | "i32" | "i64" | "i128" | "isize" | "u8" | "u16" | "u32" | "u64"
            | "u128" | "usize" => underlying_type.to_rust_type_str(),
            _ => "i32".to_string(),
        };
        self.register_enum_repr_type(name, &repr_type);
        self.writeln(&format!("#[repr({})]", repr_type));
        self.writeln("#[derive(Clone, Copy, PartialEq, Eq, Debug)]");
        self.writeln(&format!("pub enum {} {{", name));
        self.generated_enums.insert(name.to_string());
        self.indent += 1;

        for child in children {
            if let ClangNodeKind::EnumConstantDecl {
                name: const_name,
                value,
            } = &child.kind
            {
                if let Some(v) = value {
                    // For unsigned repr types, handle negative values by wrapping
                    let fixed_value = if repr_type.starts_with('u') && *v < 0 {
                        // Negative value in unsigned enum - use explicit cast
                        // This handles C++ patterns like `__memory_order_modifier_mask = -65536`
                        // which should be 0xFFFF0000 in unsigned
                        format!("{}i64 as {}", v, repr_type)
                    } else {
                        v.to_string()
                    };
                    self.writeln(&format!("{} = {},", const_name, fixed_value));
                    self.enum_variant_map
                        .insert((name.to_string(), *v as i128), const_name.clone());
                } else {
                    self.writeln(&format!("{},", const_name));
                }
            }
        }

        self.indent -= 1;
        self.writeln("}");
        self.writeln("");
    }

    /// Generate a union stub (fields only).
    fn generate_union_stub(&mut self, name: &str, children: &[ClangNode]) {
        // Keep unnamed-union compatibility with field-type lowering while falling back
        // to a sanitized identifier for invalid lowered item names (e.g., `type` -> `()`).
        let rust_name = Self::union_decl_rust_name(name);

        // Skip if already generated
        if self.generated_structs.contains(&rust_name) {
            return;
        }

        // Skip unions whose array payload bound is an unresolved non-type template
        // placeholder (e.g., `ITEM_SIZE`) to avoid hard compile blockers from
        // template-definition-only artifacts.
        for child in children {
            if let ClangNodeKind::FieldDecl { ty, .. } = &child.kind {
                let type_str = ty.to_rust_type_str();
                if type_str.contains("_S_local_capacity")
                    || type_str.contains("_S_")
                    || Self::has_unresolved_array_size_placeholder(&type_str)
                {
                    return;
                }
            }
        }

        self.generated_structs.insert(rust_name.clone());
        self.union_types.insert(rust_name.clone());

        // Check if any field needs ManuallyDrop (non-Copy types: structs, c_void, etc.)
        let has_non_copy_field = children.iter().any(|child| {
            if let ClangNodeKind::FieldDecl { ty, .. } = &child.kind {
                let type_str = Self::normalize_known_union_helper_field_type(ty.to_rust_type_str());
                !Self::is_definitely_copy_rust_type(&type_str)
            } else {
                false
            }
        });

        self.writeln(&format!("/// C++ union `{}`", name));
        self.writeln("#[repr(C)]");
        // Can't derive Copy/Clone if any field needs ManuallyDrop
        if !has_non_copy_field {
            self.writeln("#[derive(Copy, Clone)]");
        }
        self.writeln(&format!("pub union {} {{", rust_name));
        self.indent += 1;

        let mut fields = Vec::new();
        for child in children {
            if let ClangNodeKind::FieldDecl {
                name: field_name,
                ty,
                access,
                ..
            } = &child.kind
            {
                let sanitized_name = if field_name.is_empty() {
                    "_field".to_string()
                } else {
                    sanitize_identifier(field_name)
                };
                let vis = access_to_visibility(*access);
                let type_str =
                    Self::normalize_known_union_helper_field_type(ty.to_rust_type_str_for_field());
                // Wrap non-Copy types in ManuallyDrop for union compatibility.
                let wrapped_type = if !Self::is_definitely_copy_rust_type(&type_str) {
                    format!("std::mem::ManuallyDrop<{}>", type_str)
                } else {
                    type_str
                };
                self.writeln(&format!("{}{}: {},", vis, sanitized_name, wrapped_type));
                fields.push((sanitized_name, ty.clone()));
            }
        }

        self.indent -= 1;
        self.writeln("}");

        self.writeln("");
        self.writeln(&format!("impl {} {{", rust_name));
        self.indent += 1;
        self.writeln("pub fn new_0() -> Self {");
        self.indent += 1;
        self.writeln("Default::default()");
        self.indent -= 1;
        self.writeln("}");
        self.indent -= 1;
        self.writeln("}");

        // Generate Default impl
        self.writeln("");
        self.writeln(&format!("impl Default for {} {{", rust_name));
        self.indent += 1;
        self.writeln("fn default() -> Self {");
        self.indent += 1;
        self.writeln("unsafe { std::mem::zeroed() }");
        self.indent -= 1;
        self.writeln("}");
        self.indent -= 1;
        self.writeln("}");

        // Generate Clone impl if we have non-Copy fields (can't derive it)
        if has_non_copy_field {
            self.writeln("");
            self.writeln(&format!("impl Clone for {} {{", rust_name));
            self.indent += 1;
            self.writeln("fn clone(&self) -> Self {");
            self.indent += 1;
            self.writeln("unsafe { std::ptr::read(self) }");
            self.indent -= 1;
            self.writeln("}");
            self.indent -= 1;
            self.writeln("}");
        }
        if !fields.is_empty() {
            self.class_fields.insert(rust_name.clone(), fields.clone());
            if rust_name != name {
                self.class_fields.insert(name.to_string(), fields);
            }
        }
        self.writeln("");
    }

    /// Check if a type name is a primitive type (not a struct).
    fn is_primitive_type_name(name: &str) -> bool {
        matches!(
            name,
            "int"
                | "unsigned"
                | "long"
                | "short"
                | "char"
                | "bool"
                | "float"
                | "double"
                | "void"
                | "i8"
                | "i16"
                | "i32"
                | "i64"
                | "u8"
                | "u16"
                | "u32"
                | "u64"
                | "isize"
                | "usize"
                | "f32"
                | "f64"
                | "str"
                | "size_t"
                | "std::size_t"
                | "ssize_t"
                | "ptrdiff_t"
                | "std::ptrdiff_t"
                | "intptr_t"
                | "uintptr_t"
                | "wchar_t"
        )
    }

    fn maybe_track_named_type_for_stub(&mut self, candidate: &str) {
        if candidate.is_empty()
            || candidate == "_"
            || candidate.starts_with('[')
            || candidate.contains(' ')
            || candidate.contains("::")
            || candidate.contains('<')
            || candidate.contains('>')
            || RUST_KEYWORDS.contains(&candidate)
            || Self::is_primitive_type_name(candidate)
            || !Self::looks_like_stub_candidate_type_name(candidate)
            || self.generated_structs.contains(candidate)
            || self.generated_aliases.contains(candidate)
            || self.generated_enums.contains(candidate)
            || self.primitive_aliases.contains(candidate)
        {
            return;
        }

        let mut chars = candidate.chars();
        let Some(first) = chars.next() else {
            return;
        };
        if !(first.is_alphabetic() || first == '_') {
            return;
        }
        if !chars.all(|c| c.is_alphanumeric() || c == '_') {
            return;
        }

        self.referenced_but_undefined_structs
            .insert(candidate.to_string());
    }

    /// Track missing named alias targets so placeholder struct stubs can be emitted later.
    fn maybe_track_alias_target_for_stub(&mut self, rust_type: &str) {
        let mut expanded = HashSet::new();
        for candidate in Self::extract_named_type_identifiers_from_type_expr(rust_type) {
            expanded.insert(candidate.clone());
            for sibling in Self::qualifier_family_siblings(&candidate) {
                expanded.insert(sibling);
            }
        }
        for candidate in expanded {
            self.maybe_track_named_type_for_stub(&candidate);
        }
    }

    fn track_referenced_types_from_emitted_output(&mut self) {
        let referenced = Self::collect_referenced_type_like_names(&self.output);
        for name in referenced {
            self.maybe_track_named_type_for_stub(&name);
            for sibling in Self::qualifier_family_siblings(&name) {
                self.maybe_track_named_type_for_stub(&sibling);
            }
        }
    }

    fn function_decl_signature_key(
        name: &str,
        mangled_name: &str,
        params: &[(String, CppType)],
    ) -> String {
        if !mangled_name.is_empty() {
            return format!("mangled:{}", mangled_name);
        }
        let param_key = params
            .iter()
            .map(|(_, ty)| ty.to_rust_type_str())
            .collect::<Vec<_>>()
            .join("|");
        format!("name:{}:params:{}", name, param_key)
    }

    /// Emit an `extern "C"` declaration for unresolved C functions.
    fn generate_extern_c_function_decl(
        &mut self,
        name: &str,
        mangled_name: &str,
        return_type: &CppType,
        params: &[(String, CppType)],
        is_variadic: bool,
    ) {
        let link_symbol = if mangled_name.is_empty() {
            name
        } else {
            mangled_name
        };
        let signature_key = Self::function_decl_signature_key(name, mangled_name, params);
        if !self.current_namespace.is_empty()
            || self.defined_function_signatures.contains(&signature_key)
        {
            return;
        }

        if !self.emitted_extern_c_decl_symbols.insert(signature_key) {
            return;
        }

        let base_rust_name = sanitize_identifier(name);
        if base_rust_name.is_empty() {
            return;
        }
        let mut suffix = self
            .generated_functions
            .get(&base_rust_name)
            .copied()
            .unwrap_or(0);
        let (rust_name, raw_rust_name) = loop {
            let candidate = if suffix == 0 {
                base_rust_name.clone()
            } else {
                format!("{}_{}", base_rust_name, suffix)
            };
            let raw_candidate = format!("__fragile_extern_{}", candidate);
            let has_existing_free_fn_decl = self.output.lines().any(|line| {
                let trimmed = line.trim_start();
                let matches_name = trimmed.contains(&format!("pub fn {}(", candidate))
                    || trimmed.contains(&format!("pub unsafe fn {}(", candidate))
                    || trimmed.starts_with(&format!("fn {}(", candidate));
                matches_name && !trimmed.contains("&self") && !trimmed.contains("&mut self")
            });
            let has_existing_top_level_wrapper = has_existing_free_fn_decl
                || self.output.contains(&format!("fn {}(", raw_candidate));
            if !self.emitted_extern_c_functions.contains(&candidate)
                && !has_existing_top_level_wrapper
            {
                break (candidate, raw_candidate);
            }
            suffix += 1;
        };
        self.generated_functions
            .insert(base_rust_name.clone(), suffix + 1);

        let mut ret_ty = if *return_type == CppType::Void {
            String::new()
        } else {
            Self::sanitize_return_type(&return_type.to_rust_type_str())
        };

        let mut param_entries: Vec<(String, String)> = params
            .iter()
            .enumerate()
            .map(|(i, (_, t))| (format!("_arg{}", i), t.to_rust_type_str()))
            .collect();
        for (_, ty) in &param_entries {
            self.maybe_track_alias_target_for_stub(ty);
        }
        if !ret_ty.is_empty() {
            self.maybe_track_alias_target_for_stub(&ret_ty);
        }
        let mut fn_generics = String::new();
        if !ret_ty.is_empty() && ret_ty.starts_with('&') {
            let ref_param_indices: Vec<usize> = param_entries
                .iter()
                .enumerate()
                .filter_map(|(idx, (_, ty))| ty.starts_with('&').then_some(idx))
                .collect();
            if ref_param_indices.len() > 1 {
                let anchor_idx = ref_param_indices
                    .iter()
                    .copied()
                    .find(|idx| param_entries[*idx].1.starts_with("&mut "))
                    .unwrap_or(ref_param_indices[0]);
                param_entries[anchor_idx].1 =
                    Self::add_named_lifetime_to_ref_type(&param_entries[anchor_idx].1, "'a");
                ret_ty = Self::add_named_lifetime_to_ref_type(&ret_ty, "'a");
                fn_generics = "<'a>".to_string();
            }
        }
        let ret_str = if ret_ty.is_empty() {
            String::new()
        } else {
            format!(" -> {}", ret_ty)
        };
        let param_strs: Vec<String> = param_entries
            .iter()
            .map(|(name, ty)| format!("{}: {}", name, ty))
            .collect();
        let call_args: Vec<String> = param_entries.iter().map(|(name, _)| name.clone()).collect();
        if is_variadic {
            // Rust cannot define non-extern variadic wrappers, so keep a direct declaration.
            let mut variadic_params = param_strs.clone();
            variadic_params.push("...".to_string());
            self.writeln("unsafe extern \"C\" {");
            self.indent += 1;
            if rust_name != link_symbol {
                self.writeln(&format!("#[link_name = \"{}\"]", link_symbol));
            }
            self.writeln(&format!(
                "pub fn {}{}({}){};",
                rust_name,
                fn_generics,
                variadic_params.join(", "),
                ret_str
            ));
            self.indent -= 1;
            self.writeln("}");
            self.writeln("");
            self.register_function_overload(name, &rust_name, params, return_type, true);
            self.emitted_extern_c_functions.insert(rust_name);
            return;
        }

        self.writeln("unsafe extern \"C\" {");
        self.indent += 1;
        self.writeln(&format!("#[link_name = \"{}\"]", link_symbol));
        self.writeln(&format!(
            "fn {}{}({}){};",
            raw_rust_name,
            fn_generics,
            param_strs.join(", "),
            ret_str
        ));
        self.indent -= 1;
        self.writeln("}");
        self.writeln("#[inline]");
        self.writeln(&format!(
            "pub fn {}{}({}){} {{",
            rust_name,
            fn_generics,
            param_strs.join(", "),
            ret_str
        ));
        self.indent += 1;
        if ret_str.is_empty() {
            self.writeln(&format!(
                "unsafe {{ {}({}); }}",
                raw_rust_name,
                call_args.join(", ")
            ));
        } else {
            self.writeln(&format!(
                "unsafe {{ {}({}) }}",
                raw_rust_name,
                call_args.join(", ")
            ));
        }
        self.indent -= 1;
        self.writeln("}");
        self.writeln("");
        self.register_function_overload(name, &rust_name, params, return_type, false);
        self.emitted_extern_c_functions.insert(rust_name);
    }

    /// Generate a top-level declaration.
    fn generate_top_level(&mut self, node: &ClangNode) {
        match &node.kind {
            ClangNodeKind::FunctionDecl {
                name,
                mangled_name,
                is_static,
                return_type,
                params,
                is_definition,
                is_variadic,
                is_coroutine,
                coroutine_info,
                ..
            } => {
                if *is_definition {
                    self.generate_function(
                        name,
                        mangled_name,
                        *is_static,
                        return_type,
                        params,
                        *is_variadic,
                        *is_coroutine,
                        coroutine_info,
                        &node.children,
                    );
                } else {
                    self.generate_extern_c_function_decl(
                        name,
                        mangled_name,
                        return_type,
                        params,
                        *is_variadic,
                    );
                }
            }
            ClangNodeKind::FunctionTemplateInstantiation { mangled_name, .. } => {
                // Emit parser-surfaced function-template instantiations directly.
                self.generate_variadic_template_instance(mangled_name, node);
            }
            ClangNodeKind::RecordDecl {
                name,
                is_class,
                is_definition,
                ..
            } => {
                // Only generate struct for definitions, not forward declarations
                if *is_definition {
                    self.generate_struct(name, *is_class, &node.children);
                }
            }
            ClangNodeKind::EnumDecl {
                name,
                is_scoped,
                underlying_type,
            } => {
                self.generate_enum(name, *is_scoped, underlying_type, &node.children);
            }
            ClangNodeKind::UnionDecl { name, .. } => {
                self.generate_union(name, &node.children);
            }
            ClangNodeKind::TypedefDecl {
                name,
                underlying_type,
            } => {
                self.generate_type_alias(name, underlying_type);
            }
            ClangNodeKind::TypeAliasDecl {
                name,
                underlying_type,
            } => {
                self.generate_type_alias(name, underlying_type);
            }
            ClangNodeKind::VarDecl {
                name,
                ty,
                has_init,
                is_static,
                is_extern,
            } => {
                if Self::is_header_decl_without_initializer(node, *has_init) {
                    return;
                }

                if !self.is_out_of_class_static_member_definition(name, ty, &node.children) {
                    self.generate_global_var(
                        name,
                        ty,
                        *has_init,
                        *is_static,
                        *is_extern,
                        &node.children,
                        node.location.file.as_deref(),
                    );
                }
            }
            ClangNodeKind::ModuleImportDecl {
                module_name,
                is_header_unit,
            } => {
                // C++20 module import → comment for now (pending full module support)
                // In the future, this could map to:
                // - `use module_name::*;` for regular modules
                // - `include!("header.rs");` for header units
                if *is_header_unit {
                    self.writeln(&format!(
                        "// C++20 header unit import: import <{}>",
                        module_name
                    ));
                } else {
                    // Convert module path separators (. or ::) to Rust path
                    let rust_path = module_name.replace('.', "::");
                    self.writeln(&format!("// C++20 module import: import {}", module_name));
                    // Generate a use statement as a placeholder
                    // When modules are fully implemented, this will become functional
                    if !rust_path.is_empty() {
                        self.writeln(&format!(
                            "// use {}::*; // (pending module implementation)",
                            sanitize_identifier(&rust_path)
                        ));
                    }
                }
            }
            ClangNodeKind::NamespaceDecl { name, is_inline } => {
                // Generate Rust module for namespace
                if let Some(ns_name) = name {
                    // Skip anonymous namespaces, standard library namespaces, or problematic ones
                    // pmr namespace has memory_resource with polymorphic dispatch issues
                    if ns_name.starts_with("__") || ns_name == "std" || ns_name == "pmr" {
                        // Still track the namespace for deduplication, but don't create module
                        // Pass is_inline flag for proper module key computation
                        self.current_namespace.push((ns_name.clone(), *is_inline));
                        for child in &node.children {
                            self.generate_top_level(child);
                        }
                        self.current_namespace.pop();
                    } else {
                        // Build full module key for deduplication
                        // Filter out inline namespaces which are transparent in C++
                        // This uses the is_inline flag instead of heuristics
                        let effective_namespace: Vec<&str> = self
                            .current_namespace
                            .iter()
                            .filter(|(_, is_inline)| !is_inline)
                            .map(|(name, _)| name.as_str())
                            .collect();
                        let module_key = if effective_namespace.is_empty() {
                            ns_name.clone()
                        } else {
                            format!("{}::{}", effective_namespace.join("::"), ns_name)
                        };

                        // Check if this is the first occurrence of this module
                        let is_first = !self.generated_modules.contains(&module_key);
                        if is_first {
                            self.generated_modules.insert(module_key.clone());
                        }

                        // For duplicate namespaces, skip - we generate merged contents on first occurrence
                        if !is_first {
                            return;
                        }

                        self.writeln(&format!("pub mod {} {{", sanitize_identifier(ns_name)));
                        self.indent += 1;
                        self.module_depth += 1; // Track actual Rust module depth
                                                // Re-export parent module items for name resolution
                        self.writeln("use super::*;");

                        // Track current namespace for relative path computation
                        // Regular (non-inline) namespace
                        self.current_namespace.push((ns_name.clone(), false));

                        // Use merged namespace contents from all occurrences
                        // This handles C++ namespace reopening (same namespace declared multiple times)
                        // Consume merged child indices on first module emission.
                        // This avoids cloning large vectors in reopened namespaces.
                        if let Some(merged_indices) =
                            self.merged_namespace_children.remove(&module_key)
                        {
                            if merged_indices.is_empty() {
                                for child in &node.children {
                                    self.generate_top_level(child);
                                }
                            } else {
                                for idx in merged_indices {
                                    let merged_child = self
                                        .collected_nodes
                                        .get_mut(idx)
                                        .and_then(|slot| slot.take());
                                    if let Some(child) = merged_child {
                                        self.generate_top_level(&child);
                                    }
                                }
                            }
                        } else {
                            // Fallback: use direct children if not in merged map
                            for child in &node.children {
                                self.generate_top_level(child);
                            }
                        }

                        self.current_namespace.pop();

                        // Add stub functions for specific libc++ internal namespaces
                        if ns_name == "_LIBCPP_ABI_NAMESPACE" {
                            self.writeln("/// libc++ constant evaluation check (always returns false at runtime)");
                            self.writeln("#[inline]");
                            self.writeln(
                                "pub fn __libcpp_is_constant_evaluated() -> bool { false }",
                            );
                            self.writeln("");
                            self.writeln("/// swap function stub");
                            self.writeln("#[inline]");
                            self.writeln(
                                "pub fn swap<T>(a: &mut T, b: &mut T) { std::mem::swap(a, b); }",
                            );
                            self.writeln("");
                            self.writeln("/// move function stub  ");
                            self.writeln("#[inline]");
                            self.writeln("pub fn r#move<T>(v: T) -> T { v }");
                        }

                        self.module_depth -= 1;
                        self.indent -= 1;
                        self.writeln("}");
                        self.writeln("");
                    }
                } else {
                    // Anonymous namespace - generate private module with synthetic name
                    // This mirrors C++ semantics where anonymous namespaces have internal linkage
                    let anon_name = format!("__anon_{}", self.anon_namespace_counter);
                    self.anon_namespace_counter += 1;

                    self.writeln("/// Anonymous namespace (internal linkage)");
                    self.writeln(&format!("pub(crate) mod {} {{", anon_name));
                    self.indent += 1;
                    self.module_depth += 1;
                    self.writeln("use super::*;");

                    // Track the synthetic namespace name for path resolution
                    // Anonymous namespaces are not inline
                    self.current_namespace.push((anon_name.clone(), false));
                    for child in &node.children {
                        self.generate_top_level(child);
                    }
                    self.current_namespace.pop();

                    self.module_depth -= 1;
                    self.indent -= 1;
                    self.writeln("}");

                    // Auto-use the contents so they're accessible in parent scope
                    self.writeln(&format!("pub(crate) use {}::*;", anon_name));
                    self.writeln("");
                }
            }
            ClangNodeKind::LinkageSpecDecl => {
                // `extern "C" { ... }` is a transparent container around declarations.
                for child in &node.children {
                    self.generate_top_level(child);
                }
            }
            ClangNodeKind::ClassTemplateDecl {
                name: template_name,
                template_params,
                ..
            } => {
                // Template definitions are already pre-collected before top-level generation.
                // Keep this as a guarded fallback and avoid redundant child Vec clones.
                self.store_class_template_definition_if_better(
                    template_name,
                    template_params,
                    &node.children,
                );

                // Process children of class template to find implicit instantiations
                for child in &node.children {
                    match &child.kind {
                        // Template instantiations appear as RecordDecl children with
                        // type names containing template arguments (e.g., "MyVec<int>")
                        ClangNodeKind::RecordDecl {
                            name: child_name,
                            is_class,
                            is_definition,
                            ..
                        } => {
                            // Only process instantiations (names with <...>) that are definitions
                            if *is_definition
                                && child_name.contains('<')
                                && child_name.contains('>')
                            {
                                self.generate_struct(child_name, *is_class, &child.children);
                            }
                        }
                        _ => {
                            // Recursively process other children (might contain nested instantiations)
                            self.generate_top_level(child);
                        }
                    }
                }
            }
            ClangNodeKind::ClassTemplatePartialSpecDecl { .. } => {
                // Partial specializations are like regular structs with the specialized types
                // The name will include the specialization pattern (e.g., "Pair<T, T>")
                // For now, process children to find any instantiations
                for child in &node.children {
                    if let ClangNodeKind::RecordDecl {
                        name: child_name,
                        is_class,
                        is_definition,
                        ..
                    } = &child.kind
                    {
                        // Only generate for definitions
                        if *is_definition && child_name.contains('<') && child_name.contains('>') {
                            self.generate_struct(child_name, *is_class, &child.children);
                        }
                    }
                }
            }
            _ => {}
        }
    }

    /// Get the appropriate return type string for a function, considering coroutine info.
    /// For async coroutines with value type, uses the extracted type.
    /// For generators, could use impl Iterator<Item=T> (future enhancement).
    fn get_coroutine_return_type(
        &self,
        return_type: &CppType,
        coroutine_info: &Option<CoroutineInfo>,
    ) -> String {
        if let Some(info) = coroutine_info {
            // If we extracted a value type from the coroutine return type, use it
            if let Some(ref value_type) = info.value_type {
                match info.kind {
                    CoroutineKind::Async | CoroutineKind::Task => {
                        // async fn returns the inner type directly
                        if *value_type == CppType::Void {
                            return String::new();
                        }
                        return format!(
                            " -> {}",
                            Self::sanitize_return_type(&value_type.to_rust_type_str())
                        );
                    }
                    CoroutineKind::Generator => {
                        // Generators should return impl Iterator<Item=T>
                        // Note: Rust generators are unstable, so this is forward-looking
                        return format!(
                            " -> impl Iterator<Item={}>",
                            Self::sanitize_return_type(&value_type.to_rust_type_str())
                        );
                    }
                    CoroutineKind::Custom => {
                        // Fall through to default handling
                    }
                }
            }
        }

        // Default: use the original return type
        if *return_type == CppType::Void {
            String::new()
        } else {
            format!(
                " -> {}",
                Self::sanitize_return_type(&return_type.to_rust_type_str())
            )
        }
    }

    /// Collect co_yield expressions from a generator function body.
    /// Returns a list of yield value strings.
    fn collect_generator_yields(&mut self, children: &[ClangNode]) -> Vec<String> {
        let mut yields = Vec::new();
        self.collect_yields_recursive(children, &mut yields);
        yields
    }

    fn collect_yields_recursive(&mut self, children: &[ClangNode], yields: &mut Vec<String>) {
        for child in children {
            if let ClangNodeKind::CoyieldExpr { .. } = &child.kind {
                // Extract the yield value
                if !child.children.is_empty() {
                    let value = self.expr_to_string(&child.children[0]);
                    yields.push(value);
                } else {
                    yields.push("()".to_string());
                }
            }
            // Recursively search in children
            self.collect_yields_recursive(&child.children, yields);
        }
    }

    /// Generate a state machine struct and Iterator implementation for a generator.
    fn generate_generator_struct(&mut self, func_name: &str, item_type: &str, yields: &[String]) {
        let struct_name = format!("{}Generator", to_pascal_case(func_name));

        // Generate the struct
        self.writeln(&format!(
            "/// State machine struct for generator `{}`",
            func_name
        ));
        self.writeln(&format!("pub struct {} {{", struct_name));
        self.indent += 1;
        self.writeln("__state: i32,");
        self.indent -= 1;
        self.writeln("}");
        self.writeln("");

        // Generate Iterator implementation
        self.writeln(&format!("impl Iterator for {} {{", struct_name));
        self.indent += 1;
        self.writeln(&format!("type Item = {};", item_type));
        self.writeln("");
        self.writeln("fn next(&mut self) -> Option<Self::Item> {");
        self.indent += 1;
        self.writeln("match self.__state {");
        self.indent += 1;

        // Generate match arms for each yield
        for (i, yield_val) in yields.iter().enumerate() {
            self.writeln(&format!(
                "{} => {{ self.__state = {}; Some({}) }}",
                i,
                i + 1,
                yield_val
            ));
        }

        // Final state returns None
        self.writeln("_ => None,");

        self.indent -= 1;
        self.writeln("}");
        self.indent -= 1;
        self.writeln("}");
        self.indent -= 1;
        self.writeln("}");
        self.writeln("");
    }

    fn subtree_contains_throw_expr(node: &ClangNode) -> bool {
        if matches!(&node.kind, ClangNodeKind::ThrowExpr { .. }) {
            return true;
        }
        node.children.iter().any(Self::subtree_contains_throw_expr)
    }

    fn contains_throw_expr(nodes: &[ClangNode]) -> bool {
        nodes.iter().any(Self::subtree_contains_throw_expr)
    }

    fn add_named_lifetime_to_ref_type(ty: &str, lifetime: &str) -> String {
        if let Some(inner) = ty.strip_prefix("&mut ") {
            format!("&{} mut {}", lifetime, inner)
        } else if let Some(inner) = ty.strip_prefix('&') {
            format!("&{} {}", lifetime, inner)
        } else {
            ty.to_string()
        }
    }

    fn add_named_lifetime_to_return_type(ret: &str, lifetime: &str) -> String {
        if let Some(inner) = ret.strip_prefix(" -> &mut ") {
            format!(" -> &{} mut {}", lifetime, inner)
        } else if let Some(inner) = ret.strip_prefix(" -> &") {
            format!(" -> &{} {}", lifetime, inner)
        } else {
            ret.to_string()
        }
    }

    fn is_builtin_non_constructible_rust_type(rust_type: &str) -> bool {
        rust_type.starts_with('*')
            || rust_type.starts_with('&')
            || matches!(
                rust_type,
                "std::ffi::c_void"
                    | "()"
                    | "bool"
                    | "char"
                    | "i8"
                    | "i16"
                    | "i32"
                    | "i64"
                    | "i128"
                    | "isize"
                    | "u8"
                    | "u16"
                    | "u32"
                    | "u64"
                    | "u128"
                    | "usize"
                    | "f32"
                    | "f64"
            )
    }

    fn is_non_constructible_rust_type(&self, rust_type: &str) -> bool {
        if Self::is_builtin_non_constructible_rust_type(rust_type)
            || self.primitive_aliases.contains(rust_type)
        {
            return true;
        }
        self.type_alias_targets
            .get(rust_type)
            .is_some_and(|target| {
                Self::is_builtin_non_constructible_rust_type(target)
                    || self.primitive_aliases.contains(target)
            })
    }

    fn rust_type_resolves_to_c_void(&self, rust_type: &str) -> bool {
        let normalized = rust_type
            .trim_start_matches("&mut ")
            .trim_start_matches('&')
            .trim_start_matches("*mut ")
            .trim_start_matches("*const ")
            .trim();
        let leaf = normalized.rsplit("::").next().unwrap_or(normalized);
        if normalized == "std::ffi::c_void" || leaf == "std::ffi::c_void" {
            return true;
        }
        if self
            .type_alias_targets
            .get(normalized)
            .is_some_and(|target| target == "std::ffi::c_void")
            || self
                .type_alias_targets
                .get(leaf)
                .is_some_and(|target| target == "std::ffi::c_void")
        {
            return true;
        }
        self.type_alias_targets.iter().any(|(alias, target)| {
            target == "std::ffi::c_void"
                && (alias == normalized
                    || alias == leaf
                    || normalized.starts_with(alias)
                    || alias.starts_with(normalized)
                    || leaf.starts_with(alias)
                    || alias.starts_with(leaf))
        })
    }

    fn rust_type_resolves_to_unique_ptr_like(&self, rust_type: &str) -> bool {
        let mut current = rust_type
            .trim_start_matches("&mut ")
            .trim_start_matches('&')
            .trim_start_matches("*mut ")
            .trim_start_matches("*const ")
            .trim()
            .to_string();
        let mut seen: HashSet<String> = HashSet::new();
        loop {
            if current.contains("std_unique_ptr<")
                || current.contains("std::unique_ptr<")
                || current.contains("unique_ptr<")
                || current.contains("unique_ptr")
            {
                return true;
            }
            if !seen.insert(current.clone()) {
                return false;
            }
            let leaf = current
                .rsplit("::")
                .next()
                .unwrap_or(current.as_str())
                .to_string();
            if let Some(target) = self.type_alias_targets.get(&current) {
                current = target.clone();
                continue;
            }
            if let Some(target) = self.type_alias_targets.get(&leaf) {
                current = target.clone();
                continue;
            }
            return false;
        }
    }

