    #[test]
    fn test_preamble_owned_helper_functions_are_not_reemitted() {
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::FunctionDecl {
                        name: "__countl_zero_u64".to_string(),
                        mangled_name: "_Z17__countl_zero_u64m".to_string(),
                        is_static: false,
                        return_type: CppType::Int { signed: false },
                        params: vec![("x".to_string(), CppType::LongLong { signed: false })],
                        is_definition: true,
                        is_variadic: false,
                        is_noexcept: false,
                        is_coroutine: false,
                        coroutine_info: None,
                    },
                    vec![make_node(
                        ClangNodeKind::CompoundStmt,
                        vec![make_node(
                            ClangNodeKind::ReturnStmt,
                            vec![make_node(
                                ClangNodeKind::IntegerLiteral {
                                    value: 0,
                                    cpp_type: Some(CppType::Int { signed: false }),
                                },
                                vec![],
                            )],
                        )],
                    )],
                ),
                make_node(
                    ClangNodeKind::FunctionDecl {
                        name: "__atomic_notify_all_std_atomic_flag".to_string(),
                        mangled_name: "_Z35__atomic_notify_all_std_atomic_flagPK15std_atomic_flag"
                            .to_string(),
                        is_static: false,
                        return_type: CppType::Void,
                        params: vec![(
                            "__a".to_string(),
                            CppType::Pointer {
                                pointee: Box::new(CppType::Named("std_atomic_flag".to_string())),
                                is_const: true,
                            },
                        )],
                        is_definition: true,
                        is_variadic: false,
                        is_noexcept: false,
                        is_coroutine: false,
                        coroutine_info: None,
                    },
                    vec![make_node(ClangNodeKind::CompoundStmt, vec![])],
                ),
            ],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert_eq!(
            code.matches("pub fn __countl_zero_u64(").count(),
            1,
            "expected only preamble-owned __countl_zero_u64 helper, got:\n{}",
            code
        );
        assert!(
            !code.contains("pub fn __countl_zero_u64_1("),
            "preamble helper must not be re-emitted with overload suffix, got:\n{}",
            code
        );
        assert_eq!(
            code.matches("pub fn __atomic_notify_all_std_atomic_flag")
                .count(),
            1,
            "expected only preamble-owned __atomic_notify_all_std_atomic_flag helper, got:\n{}",
            code
        );
        assert!(
            !code.contains("pub fn __atomic_notify_all_std_atomic_flag_1"),
            "preamble helper must not be re-emitted with overload suffix, got:\n{}",
            code
        );
    }

    #[test]
    fn test_preamble_function_name_collisions_use_suffixed_rust_identifiers() {
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::FunctionDecl {
                    name: "rotl32".to_string(),
                    mangled_name: "_Z6rotl32ja".to_string(),
                    is_static: false,
                    return_type: CppType::Int { signed: false },
                    params: vec![
                        ("x".to_string(), CppType::Int { signed: false }),
                        ("r".to_string(), CppType::Char { signed: true }),
                    ],
                    is_definition: true,
                    is_variadic: false,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(
                        ClangNodeKind::ReturnStmt,
                        vec![make_node(
                            ClangNodeKind::IntegerLiteral {
                                value: 0,
                                cpp_type: Some(CppType::Int { signed: false }),
                            },
                            vec![],
                        )],
                    )],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("pub fn rotl32(x: u32, r: i32) -> u32 {"),
            "expected preamble rotl32 helper to stay available, got:\n{}",
            code
        );
        assert!(
            code.contains("#[export_name = \"_Z6rotl32ja\"]"),
            "expected exported C++ symbol for rotl32, got:\n{}",
            code
        );
        assert!(
            code.contains("pub extern \"C\" fn rotl32_1(x: u32, r: i8) -> u32 {"),
            "expected colliding C++ function to receive a suffixed Rust identifier, got:\n{}",
            code
        );
        assert!(
            !code.contains("pub extern \"C\" fn rotl32(x: u32, r: i8) -> u32 {"),
            "expected no direct Rust name collision with preamble helper, got:\n{}",
            code
        );
    }

