    #[test]
    fn test_reopened_namespace_merges_all_children_without_dropping_entries() {
        let make_returning_fn =
            |name: &str, mangled_name: &str, value: i128| -> ClangNode {
                make_node(
                    ClangNodeKind::FunctionDecl {
                        name: name.to_string(),
                        mangled_name: mangled_name.to_string(),
                        is_static: false,
                        return_type: CppType::Int { signed: true },
                        params: vec![],
                        is_definition: true,
                        is_variadic: false,
                        is_noexcept: false,
                        is_coroutine: false,
                        coroutine_info: None,
                    },
                    vec![make_node(
                        ClangNodeKind::CompoundStmt,
                        vec![make_node(
                            ClangNodeKind::ReturnStmt,
                            vec![make_node(
                                ClangNodeKind::IntegerLiteral {
                                    value,
                                    cpp_type: Some(CppType::Int { signed: true }),
                                },
                                vec![],
                            )],
                        )],
                    )],
                )
            };

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::NamespaceDecl {
                        name: Some("rpc".to_string()),
                        is_inline: false,
                    },
                    vec![make_returning_fn(
                        "lane_a",
                        "_ZN3rpc6lane_aEv",
                        1,
                    )],
                ),
                make_node(
                    ClangNodeKind::NamespaceDecl {
                        name: Some("rpc".to_string()),
                        is_inline: false,
                    },
                    vec![make_returning_fn(
                        "lane_b",
                        "_ZN3rpc6lane_bEv",
                        2,
                    )],
                ),
            ],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert_eq!(
            code.matches("pub mod rpc {").count(),
            1,
            "reopened namespaces should still emit a single merged Rust module, got:\n{}",
            code
        );
        assert!(
            code.contains("fn lane_a("),
            "merged namespace should keep declarations from first occurrence, got:\n{}",
            code
        );
        assert_eq!(
            code.matches("fn lane_a(").count(),
            1,
            "merged namespace should emit first-occurrence declaration exactly once, got:\n{}",
            code
        );
        assert!(
            code.contains("fn lane_b("),
            "merged namespace should keep declarations from reopened occurrence, got:\n{}",
            code
        );
        assert_eq!(
            code.matches("fn lane_b(").count(),
            1,
            "merged namespace should emit reopened declaration exactly once, got:\n{}",
            code
        );
    }

    #[test]
    fn test_member_call_rewrites_to_const_overload_for_self_receiver() {
        let int_ty = CppType::Int { signed: true };
        let foo_const_this = CppType::Pointer {
            pointee: Box::new(CppType::Named("Foo".to_string())),
            is_const: true,
        };

        let foo_record = make_node(
            ClangNodeKind::RecordDecl {
                name: "Foo".to_string(),
                is_class: true,
                is_definition: true,
                fields: vec![],
            },
            vec![
                make_node(
                    ClangNodeKind::CXXMethodDecl {
                        class_name: "Foo".to_string(),
                        name: "bar".to_string(),
                        return_type: int_ty.clone(),
                        params: vec![],
                        is_definition: true,
                        is_static: false,
                        is_virtual: false,
                        is_pure_virtual: false,
                        is_override: false,
                        is_final: false,
                        is_const: false,
                        access: AccessSpecifier::Public,
                    },
                    vec![make_node(
                        ClangNodeKind::CompoundStmt,
                        vec![make_node(
                            ClangNodeKind::ReturnStmt,
                            vec![make_node(
                                ClangNodeKind::IntegerLiteral {
                                    value: 1,
                                    cpp_type: Some(int_ty.clone()),
                                },
                                vec![],
                            )],
                        )],
                    )],
                ),
                make_node(
                    ClangNodeKind::CXXMethodDecl {
                        class_name: "Foo".to_string(),
                        name: "bar".to_string(),
                        return_type: int_ty.clone(),
                        params: vec![],
                        is_definition: true,
                        is_static: false,
                        is_virtual: false,
                        is_pure_virtual: false,
                        is_override: false,
                        is_final: false,
                        is_const: true,
                        access: AccessSpecifier::Public,
                    },
                    vec![make_node(
                        ClangNodeKind::CompoundStmt,
                        vec![make_node(
                            ClangNodeKind::ReturnStmt,
                            vec![make_node(
                                ClangNodeKind::IntegerLiteral {
                                    value: 2,
                                    cpp_type: Some(int_ty.clone()),
                                },
                                vec![],
                            )],
                        )],
                    )],
                ),
                make_node(
                    ClangNodeKind::CXXMethodDecl {
                        class_name: "Foo".to_string(),
                        name: "call".to_string(),
                        return_type: int_ty.clone(),
                        params: vec![],
                        is_definition: true,
                        is_static: false,
                        is_virtual: false,
                        is_pure_virtual: false,
                        is_override: false,
                        is_final: false,
                        is_const: true,
                        access: AccessSpecifier::Public,
                    },
                    vec![make_node(
                        ClangNodeKind::CompoundStmt,
                        vec![make_node(
                            ClangNodeKind::ReturnStmt,
                            vec![make_node(
                                ClangNodeKind::CallExpr {
                                    ty: int_ty.clone(),
                                    template_instantiation: None,
                                },
                                vec![make_node(
                                    ClangNodeKind::MemberExpr {
                                        member_name: "bar".to_string(),
                                        is_arrow: false,
                                        ty: CppType::Function {
                                            return_type: Box::new(int_ty.clone()),
                                            params: vec![],
                                            is_variadic: false,
                                        },
                                        declaring_class: Some("Foo".to_string()),
                                        is_static: false,
                                    },
                                    vec![make_node(
                                        ClangNodeKind::CXXThisExpr {
                                            ty: foo_const_this.clone(),
                                        },
                                        vec![],
                                    )],
                                )],
                            )],
                        )],
                    )],
                ),
            ],
        );

        let ast = make_node(ClangNodeKind::TranslationUnit, vec![foo_record]);
        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("pub fn bar(&mut self, ) -> i32"),
            "expected non-const overload to be generated, got:\n{}",
            code
        );
        assert!(
            code.contains("pub fn bar_1(&self, ) -> i32"),
            "expected const overload to be suffixed, got:\n{}",
            code
        );
        assert!(
            code.contains("return self.bar_1()")
                || code.contains("return (self.bar_1()) as i32"),
            "const self-receiver call should target suffixed const overload, got:\n{}",
            code
        );
    }

