    #[test]
    fn test_const_method_member_call_to_mutable_only_getstr_uses_mut_cast_fallback() {
        let char_ptr_const = CppType::Pointer {
            pointee: Box::new(CppType::Char { signed: true }),
            is_const: true,
        };

        let str_record = make_node(
            ClangNodeKind::RecordDecl {
                name: "Str".to_string(),
                is_class: true,
                is_definition: true,
                fields: vec![],
            },
            vec![make_node(
                ClangNodeKind::CXXMethodDecl {
                    class_name: "Str".to_string(),
                    name: "GetStr".to_string(),
                    return_type: char_ptr_const.clone(),
                    params: vec![],
                    is_definition: true,
                    is_static: false,
                    is_virtual: false,
                    is_pure_virtual: false,
                    is_override: false,
                    is_final: false,
                    is_const: false,
                    access: AccessSpecifier::Public,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(
                        ClangNodeKind::ReturnStmt,
                        vec![make_node(ClangNodeKind::NullPtrLiteral, vec![])],
                    )],
                )],
            )],
        );

        let node_record = make_node(
            ClangNodeKind::RecordDecl {
                name: "Node".to_string(),
                is_class: true,
                is_definition: true,
                fields: vec![("_value".to_string(), CppType::Named("Str".to_string()))],
            },
            vec![
                make_node(
                    ClangNodeKind::FieldDecl {
                        name: "_value".to_string(),
                        ty: CppType::Named("Str".to_string()),
                        access: AccessSpecifier::Public,
                        is_static: false,
                        bit_field_width: None,
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::CXXMethodDecl {
                        class_name: "Node".to_string(),
                        name: "Value".to_string(),
                        return_type: char_ptr_const.clone(),
                        params: vec![],
                        is_definition: true,
                        is_static: false,
                        is_virtual: false,
                        is_pure_virtual: false,
                        is_override: false,
                        is_final: false,
                        is_const: true,
                        access: AccessSpecifier::Public,
                    },
                    vec![make_node(
                        ClangNodeKind::CompoundStmt,
                        vec![make_node(
                            ClangNodeKind::ReturnStmt,
                            vec![make_node(
                                ClangNodeKind::CallExpr {
                                    ty: char_ptr_const.clone(),
                                    template_instantiation: None,
                                },
                                vec![make_node(
                                    ClangNodeKind::MemberExpr {
                                        member_name: "GetStr".to_string(),
                                        is_arrow: false,
                                        ty: CppType::Function {
                                            return_type: Box::new(char_ptr_const.clone()),
                                            params: vec![],
                                            is_variadic: false,
                                        },
                                        declaring_class: Some("Str".to_string()),
                                        is_static: false,
                                    },
                                    vec![make_node(
                                        ClangNodeKind::MemberExpr {
                                            member_name: "_value".to_string(),
                                            is_arrow: false,
                                            ty: CppType::Named("Str".to_string()),
                                            declaring_class: Some("Node".to_string()),
                                            is_static: false,
                                        },
                                        vec![make_node(
                                            ClangNodeKind::CXXThisExpr {
                                                ty: CppType::Pointer {
                                                    pointee: Box::new(CppType::Named(
                                                        "Node".to_string(),
                                                    )),
                                                    is_const: true,
                                                },
                                            },
                                            vec![],
                                        )],
                                    )],
                                )],
                            )],
                        )],
                    )],
                ),
            ],
        );

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![str_record, node_record],
        );
        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("as *const Str) as *mut Str") && code.contains(".GetStr()"),
            "const context mutable-only member call should use mut-cast fallback, got:\n{}",
            code
        );
        assert!(
            !code.contains("(&mut *(((&self._value) as *const Str) as *mut Str)).GetStr()"),
            "const context mutable-only member call should avoid &T -> &mut T reference casting, got:\n{}",
            code
        );
    }

