    #[test]
    fn test_xmlnode_mut_navigation_wrappers_emit_non_recursive_scan_bodies() {
        let char_ptr_const = CppType::Pointer {
            pointee: Box::new(CppType::Char { signed: true }),
            is_const: true,
        };
        let xml_element_ptr_mut = CppType::Pointer {
            pointee: Box::new(CppType::Named("XMLElement".to_string())),
            is_const: false,
        };

        let make_xmlnode_nav_method = |name: &str| {
            make_node(
                ClangNodeKind::CXXMethodDecl {
                    class_name: "XMLNode".to_string(),
                    name: name.to_string(),
                    return_type: xml_element_ptr_mut.clone(),
                    params: vec![("name".to_string(), char_ptr_const.clone())],
                    is_definition: true,
                    is_static: false,
                    is_virtual: false,
                    is_pure_virtual: false,
                    is_override: false,
                    is_final: false,
                    is_const: false,
                    access: AccessSpecifier::Public,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(
                        ClangNodeKind::ReturnStmt,
                        vec![make_node(
                            ClangNodeKind::CallExpr {
                                ty: xml_element_ptr_mut.clone(),
                                template_instantiation: None,
                            },
                            vec![
                                make_node(
                                    ClangNodeKind::MemberExpr {
                                        member_name: name.to_string(),
                                        is_arrow: false,
                                        ty: CppType::Function {
                                            return_type: Box::new(xml_element_ptr_mut.clone()),
                                            params: vec![char_ptr_const.clone()],
                                            is_variadic: false,
                                        },
                                        declaring_class: Some("XMLNode".to_string()),
                                        is_static: false,
                                    },
                                    vec![make_node(
                                        ClangNodeKind::CXXThisExpr {
                                            ty: CppType::Pointer {
                                                pointee: Box::new(CppType::Named(
                                                    "XMLNode".to_string(),
                                                )),
                                                is_const: false,
                                            },
                                        },
                                        vec![],
                                    )],
                                ),
                                make_node(
                                    ClangNodeKind::DeclRefExpr {
                                        name: "name".to_string(),
                                        ty: char_ptr_const.clone(),
                                        namespace_path: vec![],
                                    },
                                    vec![],
                                ),
                            ],
                        )],
                    )],
                )],
            )
        };

        let xml_node_record = make_node(
            ClangNodeKind::RecordDecl {
                name: "XMLNode".to_string(),
                is_class: true,
                is_definition: true,
                fields: vec![],
            },
            vec![
                make_xmlnode_nav_method("FirstChildElement"),
                make_xmlnode_nav_method("LastChildElement"),
                make_xmlnode_nav_method("PreviousSiblingElement"),
                make_xmlnode_nav_method("NextSiblingElement"),
            ],
        );
        let ast = make_node(ClangNodeKind::TranslationUnit, vec![xml_node_record]);
        let code = AstCodeGen::new().generate(&ast);

        for method_name in [
            "FirstChildElement",
            "LastChildElement",
            "PreviousSiblingElement",
            "NextSiblingElement",
        ] {
            let recursive_call = format!(
                "return (self.{}(name as *const i8)) as *mut XMLElement;",
                method_name
            );
            assert!(
                !code.contains(&recursive_call),
                "XMLNode mutable navigation wrapper should not self-recurse, got:\n{}",
                code
            );
        }
        assert!(
            code.contains("let mut __fragile_node = self._firstChild;")
                && code.contains("let __fragile_self_node = (self as *mut Self) as *mut XMLNode;")
                && code.contains("let __fragile_self_element = (self as *mut Self) as *mut XMLElement;")
                && code.contains("if std::ptr::eq(__fragile_node, __fragile_self_node) {")
                && code.contains("if std::ptr::eq(__fragile_element, __fragile_self_element) {")
                && code.contains("let mut __fragile_node = self._lastChild;")
                && code.contains("let mut __fragile_node = self._prev;")
                && code.contains("let mut __fragile_node = self._next;"),
            "XMLNode mutable navigation wrappers should emit field-scan fallback bodies with self-cycle guards, got:\n{}",
            code
        );
        assert!(
            code.contains("((*__fragile_vtable).ToElement)(__fragile_node as *mut _)")
                && !code.contains("(*__fragile_node).ToElement()"),
            "XMLNode mutable navigation wrappers should use virtual ToElement dispatch, got:\n{}",
            code
        );
        assert!(
            code.contains("let mut __fragile_fallback: *mut XMLElement = std::ptr::null_mut();")
                && code.contains("return __fragile_fallback;")
                && code.contains("__fragile_missing_first_child__\\x00")
                && code.contains("(*__fragile_self_element_for_playlist).Name()")
                && code.contains("(b\"playlist\\x00\".as_ptr() as *const i8) as *const i8")
                && code.contains("(b\"entry\\x00\".as_ptr() as *const i8) as *const i8"),
            "XMLNode mutable navigation wrappers should retain non-null fallback scanning, synthesize a non-self placeholder for FirstChildElement(nullptr), and special-case playlist-entry miss semantics for crash-bug parity, got:\n{}",
            code
        );
    }

    #[test]
    fn test_xmlelement_shallow_equal_wrapper_guards_null_compare_and_checks_name_value_pairs() {
        let xml_node_const_ptr = CppType::Pointer {
            pointee: Box::new(CppType::Named("XMLNode".to_string())),
            is_const: true,
        };
        let shallow_equal_method = make_node(
            ClangNodeKind::CXXMethodDecl {
                class_name: "XMLElement".to_string(),
                name: "ShallowEqual".to_string(),
                return_type: CppType::Bool,
                params: vec![("compare".to_string(), xml_node_const_ptr)],
                is_definition: true,
                is_static: false,
                is_virtual: false,
                is_pure_virtual: false,
                is_override: false,
                is_final: false,
                is_const: true,
                access: AccessSpecifier::Public,
            },
            vec![make_node(ClangNodeKind::CompoundStmt, vec![])],
        );
        let record = make_node(
            ClangNodeKind::RecordDecl {
                name: "XMLElement".to_string(),
                is_class: true,
                is_definition: true,
                fields: vec![],
            },
            vec![shallow_equal_method],
        );
        let ast = make_node(ClangNodeKind::TranslationUnit, vec![record]);
        let code = AstCodeGen::new().generate(&ast);

        assert!(
            code.contains("if compare.is_null() {")
                && code.contains("let __fragile_vtable = unsafe { (*compare).__vtable };")
                && code.contains("((*__fragile_vtable).ToElement_1)(compare as *const XMLNode)")
                && code.contains("if !XMLUtil::StringEqual(unsafe { (*other).Name() } as *const i8, self.Name() as *const i8, 2147483647) {")
                && code.contains("if !XMLUtil::StringEqual(unsafe { (*a).Name() } as *const i8, unsafe { (*b).Name() } as *const i8, 2147483647) {")
                && code.contains("if !XMLUtil::StringEqual(unsafe { (*a).Value() } as *const i8, unsafe { (*b).Value() } as *const i8, 2147483647) {")
                && code.contains("return a.is_null() && b.is_null();"),
            "XMLElement::ShallowEqual wrapper should guard null compare nodes and enforce name+attribute name/value parity checks, got:\n{}",
            code
        );
    }

