    #[test]
    fn test_condition_bool_int_casts_do_not_emit_chained_comparisons() {
        let cmp_window_bits = make_node(
            ClangNodeKind::BinaryOperator {
                op: BinaryOp::Eq,
                ty: CppType::Bool,
            },
            vec![
                make_node(
                    ClangNodeKind::DeclRefExpr {
                        name: "windowBits".to_string(),
                        ty: CppType::Int { signed: true },
                        namespace_path: vec![],
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::IntegerLiteral {
                        value: 8,
                        cpp_type: Some(CppType::Int { signed: true }),
                    },
                    vec![],
                ),
            ],
        );
        let cmp_wrap = make_node(
            ClangNodeKind::BinaryOperator {
                op: BinaryOp::Ne,
                ty: CppType::Bool,
            },
            vec![
                make_node(
                    ClangNodeKind::DeclRefExpr {
                        name: "wrap".to_string(),
                        ty: CppType::Int { signed: true },
                        namespace_path: vec![],
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::IntegerLiteral {
                        value: 1,
                        cpp_type: Some(CppType::Int { signed: true }),
                    },
                    vec![],
                ),
            ],
        );
        let cond = make_node(
            ClangNodeKind::BinaryOperator {
                op: BinaryOp::LAnd,
                ty: CppType::Bool,
            },
            vec![
                make_node(
                    ClangNodeKind::BinaryOperator {
                        op: BinaryOp::Ne,
                        ty: CppType::Bool,
                    },
                    vec![
                        make_node(
                            ClangNodeKind::CastExpr {
                                ty: CppType::Bool,
                                cast_kind: CastKind::IntegralCast,
                            },
                            vec![cmp_window_bits],
                        ),
                        make_node(
                            ClangNodeKind::IntegerLiteral {
                                value: 0,
                                cpp_type: Some(CppType::Int { signed: true }),
                            },
                            vec![],
                        ),
                    ],
                ),
                make_node(
                    ClangNodeKind::BinaryOperator {
                        op: BinaryOp::Ne,
                        ty: CppType::Bool,
                    },
                    vec![
                        make_node(
                            ClangNodeKind::CastExpr {
                                ty: CppType::Bool,
                                cast_kind: CastKind::IntegralCast,
                            },
                            vec![cmp_wrap],
                        ),
                        make_node(
                            ClangNodeKind::IntegerLiteral {
                                value: 0,
                                cpp_type: Some(CppType::Int { signed: true }),
                            },
                            vec![],
                        ),
                    ],
                ),
            ],
        );

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::FunctionDecl {
                    name: "bool_int_chain_guard".to_string(),
                    mangled_name: "bool_int_chain_guard".to_string(),
                    is_static: false,
                    return_type: CppType::Int { signed: true },
                    params: vec![
                        ("windowBits".to_string(), CppType::Int { signed: true }),
                        ("wrap".to_string(), CppType::Int { signed: true }),
                    ],
                    is_definition: true,
                    is_variadic: false,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(
                        ClangNodeKind::IfStmt,
                        vec![
                            cond,
                            make_node(
                                ClangNodeKind::ReturnStmt,
                                vec![make_node(
                                    ClangNodeKind::IntegerLiteral {
                                        value: 1,
                                        cpp_type: Some(CppType::Int { signed: true }),
                                    },
                                    vec![],
                                )],
                            ),
                            make_node(
                                ClangNodeKind::ReturnStmt,
                                vec![make_node(
                                    ClangNodeKind::IntegerLiteral {
                                        value: 0,
                                        cpp_type: Some(CppType::Int { signed: true }),
                                    },
                                    vec![],
                                )],
                            ),
                        ],
                    )],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            !code.contains("== 8 != 0"),
            "comparison chains should be normalized away in conditions, got:\n{}",
            code
        );
        assert!(
            !code.contains("!= 1 != 0"),
            "comparison chains should be normalized away in conditions, got:\n{}",
            code
        );
        assert!(
            code.contains("windowBits == 8"),
            "normalized condition should preserve comparison semantics, got:\n{}",
            code
        );
        assert!(
            code.contains("wrap != 1"),
            "normalized condition should preserve comparison semantics, got:\n{}",
            code
        );
    }

    #[test]
    fn test_int_assignment_from_comparison_bool_is_casted() {
        let assign_expr = make_node(
            ClangNodeKind::BinaryOperator {
                op: BinaryOp::Assign,
                ty: CppType::Int { signed: true },
            },
            vec![
                make_node(
                    ClangNodeKind::DeclRefExpr {
                        name: "out".to_string(),
                        ty: CppType::Int { signed: true },
                        namespace_path: vec![],
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::BinaryOperator {
                        op: BinaryOp::Eq,
                        ty: CppType::Bool,
                    },
                    vec![
                        make_node(
                            ClangNodeKind::DeclRefExpr {
                                name: "a".to_string(),
                                ty: CppType::Int { signed: true },
                                namespace_path: vec![],
                            },
                            vec![],
                        ),
                        make_node(
                            ClangNodeKind::DeclRefExpr {
                                name: "b".to_string(),
                                ty: CppType::Int { signed: true },
                                namespace_path: vec![],
                            },
                            vec![],
                        ),
                    ],
                ),
            ],
        );

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::FunctionDecl {
                    name: "assign_cmp_to_int".to_string(),
                    mangled_name: "assign_cmp_to_int".to_string(),
                    is_static: false,
                    return_type: CppType::Int { signed: true },
                    params: vec![
                        ("a".to_string(), CppType::Int { signed: true }),
                        ("b".to_string(), CppType::Int { signed: true }),
                    ],
                    is_definition: true,
                    is_variadic: false,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![
                        make_node(
                            ClangNodeKind::VarDecl {
                                name: "out".to_string(),
                                ty: CppType::Int { signed: true },
                                has_init: true,
                                is_static: false,
                                is_extern: false,
                            },
                            vec![make_node(
                                ClangNodeKind::IntegerLiteral {
                                    value: 0,
                                    cpp_type: Some(CppType::Int { signed: true }),
                                },
                                vec![],
                            )],
                        ),
                        make_node(ClangNodeKind::ExprStmt, vec![assign_expr]),
                        make_node(
                            ClangNodeKind::ReturnStmt,
                            vec![make_node(
                                ClangNodeKind::DeclRefExpr {
                                    name: "out".to_string(),
                                    ty: CppType::Int { signed: true },
                                    namespace_path: vec![],
                                },
                                vec![],
                            )],
                        ),
                    ],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("out = (a == b) as i32") || code.contains("out = ((a == b)) as i32"),
            "integer lvalue assignment from comparison should cast bool to i32, got:\n{}",
            code
        );
    }

