    #[test]
    fn test_reconcile_function_param_names_with_definition_children_prefers_definition_names() {
        let params = vec![
            ("str".to_string(), CppType::Bool),
            ("head".to_string(), CppType::Bool),
        ];
        let children = vec![
            ClangNode {
                kind: ClangNodeKind::ParmVarDecl {
                    name: "str".to_string(),
                    ty: CppType::Bool,
                },
                children: Vec::new(),
                location: SourceLocation::default(),
            },
            ClangNode {
                kind: ClangNodeKind::ParmVarDecl {
                    name: "tail".to_string(),
                    ty: CppType::Bool,
                },
                children: Vec::new(),
                location: SourceLocation::default(),
            },
            ClangNode {
                kind: ClangNodeKind::CompoundStmt,
                children: Vec::new(),
                location: SourceLocation::default(),
            },
        ];

        let reconciled =
            AstCodeGen::reconcile_function_param_names_with_definition_children(&params, &children);
        assert_eq!(reconciled[0].0, "str");
        assert_eq!(reconciled[1].0, "tail");
    }

