    #[test]
    fn test_missing_stub_generation_ignores_expression_like_path_used_type_names() {
        let mut codegen = AstCodeGen::new();
        codegen
            .used_types
            .insert("size_of".to_string(), "size::of".to_string());
        codegen
            .used_types
            .insert("type_name".to_string(), "type::name".to_string());
        codegen
            .used_types
            .insert("from_utf8".to_string(), "from::utf8".to_string());
        codegen
            .used_types
            .insert("align_of".to_string(), "align::of".to_string());
        codegen
            .used_types
            .insert("new_0".to_string(), "new::0".to_string());
        codegen.used_types.insert(
            "from_raw_parts_mut".to_string(),
            "from::raw::parts::mut".to_string(),
        );
        codegen
            .used_types
            .insert("size".to_string(), "::size".to_string());
        codegen
            .used_types
            .insert("ptr".to_string(), "::ptr".to_string());
        codegen
            .used_types
            .insert("c_void".to_string(), "c::void".to_string());
        codegen
            .used_types
            .insert("c_u128".to_string(), "c::u128".to_string());
        codegen
            .used_types
            .insert("mutex".to_string(), "mutex".to_string());
        codegen.generate_missing_type_stubs();
        let code = codegen.output;
        assert!(
            !code.contains("pub struct size_of")
                && !code.contains("pub struct type_name")
                && !code.contains("pub struct from_utf8")
                && !code.contains("pub struct align_of")
                && !code.contains("pub struct new_0")
                && !code.contains("pub struct from_raw_parts_mut")
                && !code.contains("pub struct size")
                && !code.contains("pub struct ptr")
                && !code.contains("pub struct c_void"),
            "missing stub generation should ignore expression-like path tokens leaked as type names, got:\n{}",
            code
        );
        assert!(
            code.contains("pub struct mutex") && code.contains("pub struct c_u128"),
            "known lowercase type surfaces should remain eligible when they are real type spellings (for example c::u128), got:\n{}",
            code
        );
    }

    #[test]
    fn test_missing_stub_generation_ignores_expression_like_referenced_but_undefined_names() {
        let mut codegen = AstCodeGen::new();
        codegen
            .referenced_but_undefined_structs
            .insert("size_of".to_string());
        codegen
            .referenced_but_undefined_structs
            .insert("type_name".to_string());
        codegen
            .referenced_but_undefined_structs
            .insert("from_utf8".to_string());
        codegen
            .referenced_but_undefined_structs
            .insert("new_0".to_string());
        codegen
            .referenced_but_undefined_structs
            .insert("from_raw_parts_mut".to_string());
        codegen
            .referenced_but_undefined_structs
            .insert("c_void".to_string());
        codegen
            .referenced_but_undefined_structs
            .insert("c_u128".to_string());
        codegen
            .referenced_but_undefined_structs
            .insert("thread_id".to_string());
        codegen.generate_missing_type_stubs();
        let code = codegen.output;
        assert!(
            !code.contains("pub struct size_of")
                && !code.contains("pub struct type_name")
                && !code.contains("pub struct from_utf8")
                && !code.contains("pub struct new_0")
                && !code.contains("pub struct from_raw_parts_mut")
                && !code.contains("pub struct c_void"),
            "referenced-but-undefined expression-like names should be ignored as type stubs, got:\n{}",
            code
        );
        assert!(
            code.contains("pub struct thread_id") && code.contains("pub struct c_u128"),
            "non-expression lowercase type-like names should remain eligible in referenced-but-undefined recovery, got:\n{}",
            code
        );
    }

    #[test]
    fn test_missing_stub_default_uses_false_for_bool_specialization_fields() {
        let mut codegen = AstCodeGen::new();
        let rust_name = "ConnState".to_string();
        let cpp_name = "ConnState".to_string();
        codegen
            .used_types
            .insert(rust_name.clone(), cpp_name.clone());

        let mut spec_info = make_specialization_field_info(
            &cpp_name,
            vec![],
            TemplateSpecializationKind::ImplicitInstantiation,
        );
        spec_info
            .field_types
            .insert("joined_".to_string(), CppType::Bool);
        codegen
            .specialization_field_types
            .insert(cpp_name.clone(), spec_info);

        codegen.generate_missing_type_stubs();
        let code = codegen.output;
        let struct_impl = code
            .split("impl Default for ConnState {")
            .nth(1)
            .unwrap_or("");

        assert!(
            struct_impl.contains("joined_: false,"),
            "bool specialization fields in placeholder defaults should use `false`, got:\n{}",
            code
        );
        assert!(
            !struct_impl.contains("joined_: 0"),
            "bool specialization fields must not default to integer zero, got:\n{}",
            code
        );
    }

    #[test]
    fn test_record_with_unqualified_vector_field_does_not_derive_copy() {
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::RecordDecl {
                    name: "HasVector".to_string(),
                    is_class: true,
                    is_definition: true,
                    fields: vec![],
                },
                vec![make_node(
                    ClangNodeKind::FieldDecl {
                        name: "buffer".to_string(),
                        ty: CppType::Named("vector<char>".to_string()),
                        is_static: false,
                        access: AccessSpecifier::Public,
                        bit_field_width: None,
                    },
                    vec![],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("pub type vector_char = std_vector<i8>;"),
            "record generation should alias vector<char> to pre-generated std_vector<i8>, got:\n{}",
            code
        );
        assert!(
            code.contains("#[derive(Default, Clone)]\npub struct HasVector {"),
            "record with vector<char> field should derive Default/Clone but not Copy, got:\n{}",
            code
        );
        assert!(
            !code.contains("#[derive(Default, Clone, Copy)]\npub struct HasVector {"),
            "record with vector<char> field should not derive Copy when lowered to std_vector<i8>, got:\n{}",
            code
        );
    }

