    #[test]
    fn test_unnamed_enum_constants_trigger_unknown_tag_enum_type_alias_stub() {
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::EnumDecl {
                    name: "(unnamed enum at logging.cpp:1:1)".to_string(),
                    is_scoped: false,
                    underlying_type: CppType::Int { signed: true },
                },
                vec![make_node(
                    ClangNodeKind::EnumConstantDecl {
                        name: "FATAL".to_string(),
                        value: Some(0),
                    },
                    vec![],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("pub const FATAL: UnknownTagEnumType = (0i64 as UnknownTagEnumType);"),
            "unnamed enum constants should keep UnknownTagEnumType placeholder surface, got:\n{}",
            code
        );
        assert!(
            code.contains("pub type UnknownTagEnumType = i32;"),
            "unnamed enum constants should force UnknownTagEnumType alias fallback when no concrete enum is available, got:\n{}",
            code
        );
        assert!(
            !code.contains("pub struct UnknownTagEnumType {"),
            "UnknownTagEnumType should resolve to alias fallback, not opaque struct placeholder, got:\n{}",
            code
        );
    }

    #[test]
    fn test_iterator_placeholder_stub_emits_new_0_and_op_eq_surface() {
        let mut codegen = AstCodeGen::new();
        codegen.used_types.insert(
            "std_vector_Employee_const_iterator".to_string(),
            "std::vector<Employee>::const_iterator".to_string(),
        );
        codegen.generate_missing_type_stubs();
        let code = codegen.output;
        let iter_impl = code
            .split("impl std_vector_Employee_const_iterator {")
            .nth(1)
            .unwrap_or("");
        assert!(
            iter_impl.contains("pub fn new_0() -> Self { Default::default() }"),
            "iterator placeholder should expose new_0 constructor, got:\n{}",
            code
        );
        assert!(
            iter_impl.contains("pub fn op_eq<T>(&self, _other: &T) -> bool { false }"),
            "iterator placeholder should expose op_eq surface, got:\n{}",
            code
        );
        assert!(
            code.contains("impl std_vector_Employee_value_type {")
                && code.contains("pub fn Serialize<T>(&self, _writer: &T) {}"),
            "iterator placeholder value type should expose Serialize fallback surface, got:\n{}",
            code
        );
    }

    #[test]
    fn test_rapidjson_concrete_document_template_impl_emits_resolved_methods_without_generic_surface_fallbacks(
    ) {
        let mut codegen = AstCodeGen::new();
        let inst_name = "GenericDocument<UTF8<>, MemoryPoolAllocator<CrtAllocator>, CrtAllocator>";
        let rust_name = "GenericDocument_UTF8_";

        codegen
            .generated_structs
            .insert("FilterKeyReader_FileReadStream".to_string());
        codegen
            .generated_structs
            .insert("Writer_FileWriteStream".to_string());
        codegen.specialization_methods.insert(
            inst_name.to_string(),
            vec![
                crate::libtooling::MethodSignature {
                    name: "Populate".to_string(),
                    return_type: Some(CppType::Void),
                    param_names: vec!["_reader".to_string()],
                    param_types: vec![CppType::Named("FilterKeyReader_FileReadStream".to_string())],
                    is_static: false,
                },
                crate::libtooling::MethodSignature {
                    name: "Accept".to_string(),
                    return_type: Some(CppType::Bool),
                    param_names: vec!["_writer".to_string()],
                    param_types: vec![CppType::Pointer {
                        pointee: Box::new(CppType::Named("Writer_FileWriteStream".to_string())),
                        is_const: true,
                    }],
                    is_static: false,
                },
            ],
        );
        codegen.libtooling_method_bodies.insert(
            (rust_name.to_string(), "Populate".to_string()),
            vec![crate::libtooling::MethodInfo {
                param_names: vec!["_reader".to_string()],
                body: make_node(ClangNodeKind::CompoundStmt, vec![]),
            }],
        );
        codegen.libtooling_method_bodies.insert(
            (rust_name.to_string(), "Accept".to_string()),
            vec![crate::libtooling::MethodInfo {
                param_names: vec!["_writer".to_string()],
                body: make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(
                        ClangNodeKind::ReturnStmt,
                        vec![make_node(ClangNodeKind::BoolLiteral(true), vec![])],
                    )],
                ),
            }],
        );

        let children = vec![
            make_node(
                ClangNodeKind::CXXMethodDecl {
                    class_name: inst_name.to_string(),
                    name: "Populate".to_string(),
                    return_type: CppType::Void,
                    params: vec![(
                        "_reader".to_string(),
                        CppType::Named("FilterKeyReader_FileReadStream".to_string()),
                    )],
                    is_definition: true,
                    is_static: false,
                    is_virtual: false,
                    is_pure_virtual: false,
                    is_override: false,
                    is_final: false,
                    is_const: false,
                    access: AccessSpecifier::Public,
                },
                vec![],
            ),
            make_node(
                ClangNodeKind::CXXMethodDecl {
                    class_name: inst_name.to_string(),
                    name: "Accept".to_string(),
                    return_type: CppType::Bool,
                    params: vec![(
                        "_writer".to_string(),
                        CppType::Pointer {
                            pointee: Box::new(CppType::Named("Writer_FileWriteStream".to_string())),
                            is_const: true,
                        },
                    )],
                    is_definition: true,
                    is_static: false,
                    is_virtual: false,
                    is_pure_virtual: false,
                    is_override: false,
                    is_final: false,
                    is_const: true,
                    access: AccessSpecifier::Public,
                },
                vec![],
            ),
        ];
        codegen.generate_template_impl(inst_name, rust_name, &children);
        let code = codegen.output;

        assert!(
            code.contains("pub fn Populate(&mut self, _reader: &mut FilterKeyReader_FileReadStream) {"),
            "concrete GenericDocument template impl should emit resolved Populate method signature, got:\n{}",
            code
        );
        assert!(
            code.contains(
                "pub fn Accept(&mut self, _writer: *const Writer_FileWriteStream) -> bool {"
            ),
            "concrete GenericDocument template impl should emit resolved Accept method signature, got:\n{}",
            code
        );
        assert!(
            !code.contains("pub fn Populate<T>(&mut self, _reader: &mut T) {"),
            "resolved GenericDocument Populate should prevent generic fallback stub emission, got:\n{}",
            code
        );
        assert!(
            !code.contains("pub fn Accept<T>(&self, _writer: &T) -> bool {"),
            "resolved GenericDocument Accept should prevent generic fallback stub emission, got:\n{}",
            code
        );
    }

    #[test]
    fn test_non_pointer_member_receiver_does_not_force_pointer_deref_call_lowering() {
        let mut codegen = AstCodeGen::new();
        codegen.class_fields.insert(
            "XMLDocument".to_string(),
            vec![
                (
                    "_unlinked".to_string(),
                    CppType::Named("DynArray_XMLNode__10".to_string()),
                ),
                (
                    "_stack".to_string(),
                    CppType::Named("DynArray_const_char__10".to_string()),
                ),
            ],
        );
        codegen.output = "if !(i < (unsafe { (*self._unlinked).Size() })) { break; }\nunsafe { (*self._unlinked).SwapRemove(i) };\nunsafe { (*self._stack).Push(name) };\n".to_string();
        codegen.fix_non_pointer_field_forced_deref_calls("XMLDocument", 0);
        let code = codegen.output;
        assert!(
            code.contains("self._unlinked.Size()")
                && code.contains("self._unlinked.SwapRemove(i)")
                && code.contains("self._stack.Push(name)"),
            "forced value-field pointer deref patterns should be normalized to dot access, got:\n{}",
            code
        );
        assert!(
            !code.contains("(*self._unlinked).") && !code.contains("(*self._stack)."),
            "normalized output should not keep forced value-field pointer deref patterns, got:\n{}",
            code
        );
    }

    #[test]
    fn test_member_call_zero_literal_uses_null_pointer_when_param_types_resolved_from_overloads() {
        let xml_element_ptr = CppType::Pointer {
            pointee: Box::new(CppType::Named("XMLElement".to_string())),
            is_const: false,
        };
        let cchar_ptr = CppType::Pointer {
            pointee: Box::new(CppType::Char { signed: true }),
            is_const: true,
        };
        let xml_node_ptr = CppType::Pointer {
            pointee: Box::new(CppType::Named("XMLNode".to_string())),
            is_const: false,
        };
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::RecordDecl {
                        name: "XMLElement".to_string(),
                        is_class: true,
                        is_definition: true,
                        fields: vec![],
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::RecordDecl {
                        name: "XMLNode".to_string(),
                        is_class: true,
                        is_definition: true,
                        fields: vec![],
                    },
                    vec![
                        make_node(
                            ClangNodeKind::CXXMethodDecl {
                                class_name: "XMLNode".to_string(),
                                name: "FirstChildElement".to_string(),
                                return_type: xml_element_ptr.clone(),
                                params: vec![("name".to_string(), cchar_ptr.clone())],
                                is_definition: true,
                                is_static: false,
                                is_virtual: false,
                                is_pure_virtual: false,
                                is_override: false,
                                is_final: false,
                                is_const: false,
                                access: AccessSpecifier::Public,
                            },
                            vec![make_node(
                                ClangNodeKind::CompoundStmt,
                                vec![make_node(
                                    ClangNodeKind::ReturnStmt,
                                    vec![make_node(ClangNodeKind::NullPtrLiteral, vec![])],
                                )],
                            )],
                        ),
                        make_node(
                            ClangNodeKind::CXXMethodDecl {
                                class_name: "XMLNode".to_string(),
                                name: "FirstOrNull".to_string(),
                                return_type: xml_element_ptr.clone(),
                                params: vec![],
                                is_definition: true,
                                is_static: false,
                                is_virtual: false,
                                is_pure_virtual: false,
                                is_override: false,
                                is_final: false,
                                is_const: false,
                                access: AccessSpecifier::Public,
                            },
                            vec![make_node(
                                ClangNodeKind::CompoundStmt,
                                vec![make_node(
                                    ClangNodeKind::ReturnStmt,
                                    vec![make_node(
                                        ClangNodeKind::CallExpr {
                                            ty: xml_element_ptr,
                                            template_instantiation: None,
                                        },
                                        vec![
                                            make_node(
                                                ClangNodeKind::MemberExpr {
                                                    member_name: "FirstChildElement".to_string(),
                                                    is_arrow: false,
                                                    ty: CppType::Named(
                                                        "<bound member function type>".to_string(),
                                                    ),
                                                    declaring_class: Some("XMLNode".to_string()),
                                                    is_static: false,
                                                },
                                                vec![make_node(
                                                    ClangNodeKind::CXXThisExpr { ty: xml_node_ptr },
                                                    vec![],
                                                )],
                                            ),
                                            make_node(
                                                ClangNodeKind::IntegerLiteral {
                                                    value: 0,
                                                    cpp_type: Some(CppType::Int { signed: true }),
                                                },
                                                vec![],
                                            ),
                                        ],
                                    )],
                                )],
                            )],
                        ),
                    ],
                ),
            ],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("FirstChildElement(std::ptr::null()")
                || code.contains("FirstChildElement(std::ptr::null_mut()"),
            "zero literal pointer argument should lower to null pointer for resolved member overload params, got:\n{}",
            code
        );
        assert!(
            !code.contains("FirstChildElement(0)"),
            "zero integer literal should not remain as integer argument to pointer parameter, got:\n{}",
            code
        );
    }

