    #[test]
    fn test_unary_deref_non_pointer_member_receiver_is_elided() {
        let xml_handle_ty = CppType::Named("XMLHandle".to_string());

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::FunctionDecl {
                    name: "probe_handle".to_string(),
                    mangled_name: "probe_handle".to_string(),
                    is_static: false,
                    return_type: xml_handle_ty.clone(),
                    params: vec![("h".to_string(), xml_handle_ty.clone())],
                    is_definition: true,
                    is_variadic: false,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(
                        ClangNodeKind::ReturnStmt,
                        vec![make_node(
                            ClangNodeKind::UnaryOperator {
                                op: UnaryOp::Deref,
                                ty: xml_handle_ty.clone(),
                            },
                            vec![make_node(
                                ClangNodeKind::DeclRefExpr {
                                    name: "h".to_string(),
                                    ty: xml_handle_ty.clone(),
                                    namespace_path: vec![],
                                },
                                vec![],
                            )],
                        )],
                    )],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("return h;"),
            "non-pointer unary deref wrappers should be elided for value-typed operands, got:\n{}",
            code
        );
        assert!(
            !code.contains("unsafe { *h }"),
            "value-typed operands should not keep raw-pointer-style unary deref, got:\n{}",
            code
        );
    }

    #[test]
    fn test_tinyxml2_handle_value_not_treated_as_pointer_receiver() {
        let codegen = AstCodeGen::new();
        let handle_node = make_node(
            ClangNodeKind::DeclRefExpr {
                name: "docH".to_string(),
                ty: CppType::Named("XMLHandle".to_string()),
                namespace_path: vec![],
            },
            vec![],
        );
        let ptr_node = make_node(
            ClangNodeKind::DeclRefExpr {
                name: "nodePtr".to_string(),
                ty: CppType::Pointer {
                    pointee: Box::new(CppType::Named("XMLNode".to_string())),
                    is_const: false,
                },
                namespace_path: vec![],
            },
            vec![],
        );

        assert!(
            !codegen.is_pointer_receiver_expr(&handle_node),
            "XMLHandle values should stay value receivers and must not be forced through pointer dereference lowering"
        );
        assert!(
            codegen.is_pointer_receiver_expr(&ptr_node),
            "raw pointer receivers must still be detected as pointer receivers"
        );
    }

    #[test]
    fn test_member_call_zero_literal_normalizes_to_bool_param() {
        let cchar_ptr = CppType::Pointer {
            pointee: Box::new(CppType::Char { signed: true }),
            is_const: true,
        };
        let node_ptr = CppType::Pointer {
            pointee: Box::new(CppType::Named("Node".to_string())),
            is_const: false,
        };

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::RecordDecl {
                    name: "Node".to_string(),
                    is_class: true,
                    is_definition: true,
                    fields: vec![],
                },
                vec![
                    make_node(
                        ClangNodeKind::CXXMethodDecl {
                            class_name: "Node".to_string(),
                            name: "SetValue".to_string(),
                            return_type: CppType::Void,
                            params: vec![
                                ("str".to_string(), cchar_ptr.clone()),
                                ("staticMem".to_string(), CppType::Bool),
                            ],
                            is_definition: true,
                            is_static: false,
                            is_virtual: false,
                            is_pure_virtual: false,
                            is_override: false,
                            is_final: false,
                            is_const: false,
                            access: AccessSpecifier::Public,
                        },
                        vec![make_node(ClangNodeKind::CompoundStmt, vec![])],
                    ),
                    make_node(
                        ClangNodeKind::CXXMethodDecl {
                            class_name: "Node".to_string(),
                            name: "SetText".to_string(),
                            return_type: CppType::Void,
                            params: vec![("inText".to_string(), cchar_ptr.clone())],
                            is_definition: true,
                            is_static: false,
                            is_virtual: false,
                            is_pure_virtual: false,
                            is_override: false,
                            is_final: false,
                            is_const: false,
                            access: AccessSpecifier::Public,
                        },
                        vec![make_node(
                            ClangNodeKind::CompoundStmt,
                            vec![make_node(
                                ClangNodeKind::ExprStmt,
                                vec![make_node(
                                    ClangNodeKind::CallExpr {
                                        ty: CppType::Void,
                                        template_instantiation: None,
                                    },
                                    vec![
                                        make_node(
                                            ClangNodeKind::MemberExpr {
                                                member_name: "SetValue".to_string(),
                                                is_arrow: false,
                                                ty: CppType::Named(
                                                    "<bound member function type>".to_string(),
                                                ),
                                                declaring_class: Some("Node".to_string()),
                                                is_static: false,
                                            },
                                            vec![make_node(
                                                ClangNodeKind::CXXThisExpr { ty: node_ptr },
                                                vec![],
                                            )],
                                        ),
                                        make_node(
                                            ClangNodeKind::DeclRefExpr {
                                                name: "inText".to_string(),
                                                ty: cchar_ptr,
                                                namespace_path: vec![],
                                            },
                                            vec![],
                                        ),
                                        make_node(
                                            ClangNodeKind::IntegerLiteral {
                                                value: 0,
                                                cpp_type: Some(CppType::Int { signed: true }),
                                            },
                                            vec![],
                                        ),
                                    ],
                                )],
                            )],
                        )],
                    ),
                ],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("SetValue(inText as *const i8, false)")
                || code.contains("SetValue(inText, false)"),
            "zero integer literal should normalize to false for bool member parameter, got:\n{}",
            code
        );
        assert!(
            !code.contains("SetValue(inText as *const i8, 0)")
                && !code.contains("SetValue(inText, 0)"),
            "bool member parameter should not keep integer literal 0 argument, got:\n{}",
            code
        );
    }

