    #[test]
    fn test_normalize_shadowed_std_prelude_paths_qualifies_option_box_result_and_shadowed_vec() {
        let input = r#"
pub struct Option;
pub struct Box;
pub struct Vec;
pub struct Result;
pub struct Holder {
    pub invoke: Option<extern "C" fn(*mut ()) -> ()>,
}
pub fn alloc<T>(v: T) -> *mut T {
    Box::into_raw(Box::new(v))
}
pub fn keep() {
    let _tokens: Vec<&str> = "a,b".split(',').collect();
    let _v = Vec::new();
    let _r: Result<i32, ()> = Result::Ok(1i32);
    let _x: std::option::Option<i32> = std::option::Option::None;
    let _y = std::boxed::Box::new(1i32);
}
"#;
        let output = AstCodeGen::normalize_shadowed_std_prelude_paths(input);
        assert!(
            output.contains("pub invoke: std::option::Option<extern \"C\" fn(*mut ()) -> ()>,"),
            "std-prelude shadow normalization should qualify bare Option generics, got:\n{}",
            output
        );
        assert!(
            output.contains("std::boxed::Box::into_raw(std::boxed::Box::new(v))"),
            "std-prelude shadow normalization should qualify bare Box paths, got:\n{}",
            output
        );
        assert!(
            output.contains("let _tokens: std::vec::Vec<&str> = \"a,b\".split(',').collect();")
                && output.contains("let _v = std::vec::Vec::new();"),
            "std-prelude shadow normalization should qualify bare Vec paths when Vec is shadowed by a non-generic type, got:\n{}",
            output
        );
        assert!(
            output.contains(
                "let _r: std::result::Result<i32, ()> = std::result::Result::Ok(1i32);"
            ),
            "std-prelude shadow normalization should qualify bare Result paths when Result is shadowed by a non-generic type, got:\n{}",
            output
        );
        assert!(
            output.contains("let _x: std::option::Option<i32> = std::option::Option::None;")
                && output.contains("let _y = std::boxed::Box::new(1i32);"),
            "std-prelude shadow normalization should not duplicate already-qualified std paths, got:\n{}",
            output
        );
    }

