    #[test]
    fn test_derived_static_vtable_omits_fields_not_in_root_layout() {
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::RecordDecl {
                        name: "Base".to_string(),
                        is_class: true,
                        is_definition: true,
                        fields: vec![],
                    },
                    vec![make_node(
                        ClangNodeKind::CXXMethodDecl {
                            class_name: "Base".to_string(),
                            name: "Foo".to_string(),
                            return_type: CppType::Void,
                            params: vec![],
                            is_definition: false,
                            is_static: false,
                            is_virtual: true,
                            is_pure_virtual: true,
                            is_override: false,
                            is_final: false,
                            is_const: false,
                            access: AccessSpecifier::Public,
                        },
                        vec![],
                    )],
                ),
                make_node(
                    ClangNodeKind::RecordDecl {
                        name: "Derived".to_string(),
                        is_class: true,
                        is_definition: true,
                        fields: vec![],
                    },
                    vec![
                        make_node(
                            ClangNodeKind::CXXBaseSpecifier {
                                base_type: CppType::Named("Base".to_string()),
                                access: AccessSpecifier::Public,
                                is_virtual: false,
                            },
                            vec![],
                        ),
                        make_node(
                            ClangNodeKind::CXXMethodDecl {
                                class_name: "Derived".to_string(),
                                name: "Foo".to_string(),
                                return_type: CppType::Void,
                                params: vec![],
                                is_definition: false,
                                is_static: false,
                                is_virtual: true,
                                is_pure_virtual: false,
                                is_override: true,
                                is_final: false,
                                is_const: false,
                                access: AccessSpecifier::Public,
                            },
                            vec![],
                        ),
                        make_node(
                            ClangNodeKind::CXXMethodDecl {
                                class_name: "Derived".to_string(),
                                name: "Bar".to_string(),
                                return_type: CppType::Void,
                                params: vec![],
                                is_definition: false,
                                is_static: false,
                                is_virtual: true,
                                is_pure_virtual: false,
                                is_override: false,
                                is_final: false,
                                is_const: false,
                                access: AccessSpecifier::Public,
                            },
                            vec![],
                        ),
                    ],
                ),
            ],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("pub static DERIVED_VTABLE: Base_vtable = Base_vtable {"),
            "derived vtable should still use root vtable type, got:\n{}",
            code
        );
        assert!(
            !code.contains("Bar: Derived_vtable_Bar"),
            "derived-only virtual fields should not be emitted into root-typed static vtable initializer, got:\n{}",
            code
        );
    }

    #[test]
    fn test_collect_root_vtable_class_names_skips_derived_entries() {
        let mut codegen = AstCodeGen::new();
        codegen.vtables.insert(
            "Base".to_string(),
            ClassVTableInfo {
                class_name: "Base".to_string(),
                entries: Vec::new(),
                base_class: None,
                is_abstract: false,
                secondary_vtables: vec![],
            },
        );
        codegen.vtables.insert(
            "Derived".to_string(),
            ClassVTableInfo {
                class_name: "Derived".to_string(),
                entries: Vec::new(),
                base_class: Some("Base".to_string()),
                is_abstract: false,
                secondary_vtables: vec![],
            },
        );

        let roots: std::collections::HashSet<String> =
            codegen.collect_root_vtable_class_names().into_iter().collect();
        assert!(
            roots.contains("Base"),
            "root vtable class collection should keep base classes"
        );
        assert!(
            !roots.contains("Derived"),
            "root vtable class collection should skip derived classes with base vtables"
        );
    }

    #[test]
    fn test_collect_concrete_vtable_class_names_skips_abstract_entries() {
        let mut codegen = AstCodeGen::new();
        codegen.vtables.insert(
            "AbstractBase".to_string(),
            ClassVTableInfo {
                class_name: "AbstractBase".to_string(),
                entries: Vec::new(),
                base_class: None,
                is_abstract: true,
                secondary_vtables: vec![],
            },
        );
        codegen.vtables.insert(
            "ConcreteDerived".to_string(),
            ClassVTableInfo {
                class_name: "ConcreteDerived".to_string(),
                entries: Vec::new(),
                base_class: Some("AbstractBase".to_string()),
                is_abstract: false,
                secondary_vtables: vec![],
            },
        );

        let concrete: std::collections::HashSet<String> = codegen
            .collect_concrete_vtable_class_names()
            .into_iter()
            .collect();
        assert!(
            !concrete.contains("AbstractBase"),
            "concrete vtable class collection should skip abstract classes"
        );
        assert!(
            concrete.contains("ConcreteDerived"),
            "concrete vtable class collection should include non-abstract classes"
        );
    }

