    #[test]
    fn test_named_global_new_0_initializer_falls_back_to_const_safe_default() {
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::RecordDecl {
                        name: "destroying_delete_t".to_string(),
                        is_class: false,
                        is_definition: true,
                        fields: vec![],
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::VarDecl {
                        name: "destroying_delete".to_string(),
                        ty: CppType::Named("destroying_delete_t".to_string()),
                        has_init: true,
                        is_static: true,
                        is_extern: false,
                    },
                    vec![make_node(
                        ClangNodeKind::CallExpr {
                            ty: CppType::Named("destroying_delete_t".to_string()),
                            template_instantiation: None,
                        },
                        vec![make_node(
                            ClangNodeKind::DeclRefExpr {
                                name: "destroying_delete_t::new_0".to_string(),
                                ty: CppType::Function {
                                    return_type: Box::new(CppType::Named(
                                        "destroying_delete_t".to_string(),
                                    )),
                                    params: vec![],
                                    is_variadic: false,
                                },
                                namespace_path: vec![],
                            },
                            vec![],
                        )],
                    )],
                ),
            ],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains(
                "static mut __gv_destroying_delete: destroying_delete_t = unsafe { std::mem::zeroed() };"
            ) || code.contains(
                "static mut __gv_destroying_delete: std::mem::MaybeUninit<destroying_delete_t> = std::mem::MaybeUninit::uninit();"
            ),
            "named global new_0 initializer should stay const-safe, got:\n{}",
            code
        );
        assert!(
            !code.contains("__gv_destroying_delete: destroying_delete_t = destroying_delete_t::new_0();"),
            "named global new_0 initializer should not call constructor in static initializer, got:\n{}",
            code
        );
    }

    #[test]
    fn test_global_unit_typed_initializer_falls_back_to_unit_default() {
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::VarDecl {
                    name: "value".to_string(),
                    ty: CppType::Void,
                    has_init: true,
                    is_static: true,
                    is_extern: false,
                },
                vec![make_node(
                    ClangNodeKind::DeclRefExpr {
                        name: "__v".to_string(),
                        ty: CppType::Void,
                        namespace_path: vec![],
                    },
                    vec![],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("static mut __gv_value: () = ();"),
            "unit-typed global should use unit default initializer instead of unresolved placeholder, got:\n{}",
            code
        );
        assert!(
            !code.contains("static mut __gv_value: () = __v;"),
            "unit-typed global should not keep unresolved placeholder initializer, got:\n{}",
            code
        );
    }

