    fn test_range_for_prefers_declared_loop_var_and_resolves_global_range_expr() {
        let worker_ty = CppType::Pointer {
            pointee: Box::new(CppType::Named("PaxosWorker".to_string())),
            is_const: false,
        };
        let range_ty = CppType::Named("vector_shared_ptr_PaxosWorker".to_string());

        let range_for_stmt = make_node(
            ClangNodeKind::CXXForRangeStmt {
                var_name: "item".to_string(),
                var_type: worker_ty.clone(),
            },
            vec![
                make_node(
                    ClangNodeKind::VarDecl {
                        name: "worker".to_string(),
                        ty: worker_ty.clone(),
                        has_init: false,
                        is_static: false,
                        is_extern: false,
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::DeclRefExpr {
                        name: "pxs_workers_g".to_string(),
                        ty: range_ty.clone(),
                        namespace_path: vec![],
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(
                        ClangNodeKind::ExprStmt,
                        vec![make_node(
                            ClangNodeKind::DeclRefExpr {
                                name: "worker".to_string(),
                                ty: worker_ty.clone(),
                                namespace_path: vec![],
                            },
                            vec![],
                        )],
                    )],
                ),
            ],
        );

        let mut gen = AstCodeGen::new();
        gen.global_vars.insert("__gv_pxs_workers_g".to_string());
        gen.global_var_mapping.insert(
            "pxs_workers_g".to_string(),
            "__gv_pxs_workers_g".to_string(),
        );
        gen.global_var_types
            .insert("__gv_pxs_workers_g".to_string(), range_ty);
        gen.global_var_namespace_paths
            .insert("__gv_pxs_workers_g".to_string(), Vec::new());
        gen.generate_stmt(&range_for_stmt, false);
        let code = gen.output;
        assert!(
            code.contains("for worker in &(unsafe { __gv_pxs_workers_g }) {"),
            "range-for lowering should use resolved global range expression and declared loop var name, got:\n{}",
            code
        );
        assert!(
            !code.contains("for item in"),
            "range-for lowering should not keep fallback loop var when VarDecl loop var exists, got:\n{}",
            code
        );
        assert!(
            code.contains("worker;"),
            "range-for body should reference the declared loop variable in local scope, got:\n{}",
            code
        );
    }

    #[test]
    fn test_single_top_level_label_goto_rewrites_to_labeled_break() {
        let jump_ref = || {
            make_node(
                ClangNodeKind::DeclRefExpr {
                    name: "jump".to_string(),
                    ty: CppType::Bool,
                    namespace_path: vec![],
                },
                vec![],
            )
        };
        let ret_ref = || {
            make_node(
                ClangNodeKind::DeclRefExpr {
                    name: "ret".to_string(),
                    ty: CppType::Int { signed: true },
                    namespace_path: vec![],
                },
                vec![],
            )
        };
        let assign_ret = |value: i128| {
            make_node(
                ClangNodeKind::ExprStmt,
                vec![make_node(
                    ClangNodeKind::BinaryOperator {
                        op: BinaryOp::Assign,
                        ty: CppType::Int { signed: true },
                    },
                    vec![
                        ret_ref(),
                        make_node(
                            ClangNodeKind::IntegerLiteral {
                                value,
                                cpp_type: Some(CppType::Int { signed: true }),
                            },
                            vec![],
                        ),
                    ],
                )],
            )
        };

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::FunctionDecl {
                    name: "goto_epilogue".to_string(),
                    mangled_name: "goto_epilogue".to_string(),
                    is_static: false,
                    return_type: CppType::Int { signed: true },
                    params: vec![("jump".to_string(), CppType::Bool)],
                    is_definition: true,
                    is_variadic: false,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![
                        make_node(
                            ClangNodeKind::DeclStmt,
                            vec![make_node(
                                ClangNodeKind::VarDecl {
                                    name: "ret".to_string(),
                                    ty: CppType::Int { signed: true },
                                    has_init: true,
                                    is_static: false,
                                    is_extern: false,
                                },
                                vec![make_node(
                                    ClangNodeKind::IntegerLiteral {
                                        value: 0,
                                        cpp_type: Some(CppType::Int { signed: true }),
                                    },
                                    vec![],
                                )],
                            )],
                        ),
                        make_node(
                            ClangNodeKind::IfStmt,
                            vec![
                                jump_ref(),
                                make_node(
                                    ClangNodeKind::GotoStmt {
                                        label: "done".to_string(),
                                    },
                                    vec![],
                                ),
                            ],
                        ),
                        assign_ret(1),
                        make_node(
                            ClangNodeKind::LabelStmt {
                                label: "done".to_string(),
                            },
                            vec![assign_ret(2)],
                        ),
                        make_node(ClangNodeKind::ReturnStmt, vec![ret_ref()]),
                    ],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("'__fragile_goto_done: loop {"),
            "expected labeled loop for single-epilogue goto pattern, got:\n{}",
            code
        );
        assert!(
            code.contains("break '__fragile_goto_done;"),
            "expected goto to lower as labeled break, got:\n{}",
            code
        );
        let decl_pos = code
            .find("let mut ret: i32")
            .expect("expected `ret` declaration in generated function");
        let loop_pos = code
            .find("'__fragile_goto_done: loop")
            .expect("expected generated goto loop label");
        assert!(
            decl_pos < loop_pos,
            "leading declarations must stay in scope for epilogue statements, got:\n{}",
            code
        );
    }

