    #[test]
    fn test_normalize_known_union_helper_field_type_functional_hash_aliases_to_u64() {
        let sanitized =
            "_unnamed_struct_at__home_shuai_workspace_fragile_vendor_llvm_project_libcxx_include___functional_hash_h_285_7_"
                .to_string();
        let raw =
            "(unnamed struct at /home/shuai/workspace/fragile/vendor/llvm-project/libcxx/include/__functional/hash.h:285:7)"
                .to_string();

        assert_eq!(
            AstCodeGen::normalize_known_union_helper_field_type(sanitized),
            "u64"
        );
        assert_eq!(
            AstCodeGen::normalize_known_union_helper_field_type(raw),
            "u64"
        );
        assert_eq!(
            AstCodeGen::normalize_known_union_helper_field_type("u32".to_string()),
            "u32"
        );
    }

    #[test]
    fn test_union_positional_init_list_uses_named_field_initializer() {
        let union_name = "union__fixture".to_string();
        let union_ty = CppType::Named(union_name.clone());
        let rust_union_name = union_ty.to_rust_type_str();

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::UnionDecl {
                        name: union_name,
                        fields: vec![],
                    },
                    vec![
                        make_node(
                            ClangNodeKind::FieldDecl {
                                name: "freq".to_string(),
                                ty: CppType::Short { signed: false },
                                access: crate::ast::AccessSpecifier::Public,
                                is_static: false,
                                bit_field_width: None,
                            },
                            vec![],
                        ),
                        make_node(
                            ClangNodeKind::FieldDecl {
                                name: "code".to_string(),
                                ty: CppType::Short { signed: false },
                                access: crate::ast::AccessSpecifier::Public,
                                is_static: false,
                                bit_field_width: None,
                            },
                            vec![],
                        ),
                    ],
                ),
                make_node(
                    ClangNodeKind::VarDecl {
                        name: "local_union".to_string(),
                        ty: union_ty.clone(),
                        has_init: true,
                        is_static: true,
                        is_extern: false,
                    },
                    vec![make_node(
                        ClangNodeKind::InitListExpr {
                            ty: union_ty.clone(),
                        },
                        vec![make_node(
                            ClangNodeKind::IntegerLiteral {
                                value: 12,
                                cpp_type: Some(CppType::Int { signed: true }),
                            },
                            vec![],
                        )],
                    )],
                ),
            ],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains(&format!("{} {{ freq:", rust_union_name)),
            "positional union init-list should use named union field initializer, got:\n{}",
            code
        );
        assert!(
            !code.contains(&format!("{} {{ 12", rust_union_name)),
            "invalid positional union literal should not be emitted, got:\n{}",
            code
        );
    }

