    #[test]
    fn test_reference_return_assignment_overload_call_does_not_wrap_extra_mut_ref() {
        let flags_ptr = CppType::Pointer {
            pointee: Box::new(CppType::Named("Flags".to_string())),
            is_const: false,
        };
        let flags_ref = CppType::Reference {
            referent: Box::new(CppType::Named("Flags".to_string())),
            is_const: false,
            is_rvalue: false,
        };
        let int_ty = CppType::Int { signed: true };

        let make_operator_method = |name: &str| {
            make_node(
                ClangNodeKind::CXXMethodDecl {
                    class_name: "Flags".to_string(),
                    name: name.to_string(),
                    return_type: flags_ref.clone(),
                    params: vec![("rhs".to_string(), int_ty.clone())],
                    is_definition: true,
                    is_static: false,
                    is_virtual: false,
                    is_pure_virtual: false,
                    is_override: false,
                    is_final: false,
                    is_const: false,
                    access: AccessSpecifier::Public,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(
                        ClangNodeKind::ReturnStmt,
                        vec![make_node(
                            ClangNodeKind::UnaryOperator {
                                op: UnaryOp::Deref,
                                ty: CppType::Named("Flags".to_string()),
                            },
                            vec![make_node(
                                ClangNodeKind::CXXThisExpr {
                                    ty: flags_ptr.clone(),
                                },
                                vec![],
                            )],
                        )],
                    )],
                )],
            )
        };

        let make_call_fn = |fn_name: &str, op_name: &str| {
            make_node(
                ClangNodeKind::FunctionDecl {
                    name: fn_name.to_string(),
                    mangled_name: fn_name.to_string(),
                    is_static: false,
                    return_type: flags_ref.clone(),
                    params: vec![
                        ("target".to_string(), flags_ptr.clone()),
                        ("rhs".to_string(), int_ty.clone()),
                    ],
                    is_definition: true,
                    is_variadic: false,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(
                        ClangNodeKind::ReturnStmt,
                        vec![make_node(
                            ClangNodeKind::CallExpr {
                                ty: flags_ref.clone(),
                                template_instantiation: None,
                            },
                            vec![
                                make_node(
                                    ClangNodeKind::MemberExpr {
                                        member_name: op_name.to_string(),
                                        is_arrow: true,
                                        ty: CppType::Function {
                                            return_type: Box::new(flags_ref.clone()),
                                            params: vec![int_ty.clone()],
                                            is_variadic: false,
                                        },
                                        declaring_class: Some("Flags".to_string()),
                                        is_static: false,
                                    },
                                    vec![make_node(
                                        ClangNodeKind::DeclRefExpr {
                                            name: "target".to_string(),
                                            ty: flags_ptr.clone(),
                                            namespace_path: vec![],
                                        },
                                        vec![],
                                    )],
                                ),
                                make_node(
                                    ClangNodeKind::DeclRefExpr {
                                        name: "rhs".to_string(),
                                        ty: int_ty.clone(),
                                        namespace_path: vec![],
                                    },
                                    vec![],
                                ),
                            ],
                        )],
                    )],
                )],
            )
        };

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::RecordDecl {
                        name: "Flags".to_string(),
                        is_class: true,
                        is_definition: true,
                        fields: vec![],
                    },
                    vec![
                        make_operator_method("operator|="),
                        make_operator_method("operator&="),
                        make_operator_method("operator^="),
                    ],
                ),
                make_call_fn("call_or_assign", "operator|="),
                make_call_fn("call_and_assign", "operator&="),
                make_call_fn("call_xor_assign", "operator^="),
            ],
        );

        let code = AstCodeGen::new().generate(&ast);

        assert!(
            code.contains("return unsafe { (*target).op_or_assign(rhs) };"),
            "operator|= reference return should not add an extra mutable reference wrapper, got:\n{}",
            code
        );
        assert!(
            code.contains("return unsafe { (*target).op_and_assign(rhs) };"),
            "operator&= reference return should not add an extra mutable reference wrapper, got:\n{}",
            code
        );
        assert!(
            code.contains("return unsafe { (*target).op_xor_assign(rhs) };"),
            "operator^= reference return should not add an extra mutable reference wrapper, got:\n{}",
            code
        );
        assert!(
            !code.contains("return unsafe { &mut (*target).op_or_assign(")
                && !code.contains("return unsafe { &mut (*target).op_and_assign(")
                && !code.contains("return unsafe { &mut (*target).op_xor_assign("),
            "assignment-overload reference returns must not wrap call results with `&mut`, got:\n{}",
            code
        );
    }

    #[test]
    fn test_extract_assignment_lhs_from_unsafe_wrapped_assignment_expr() {
        let lhs = AstCodeGen::extract_assignment_lhs("unsafe { *__lhs = *__lhs | __rhs; *__lhs }");
        assert_eq!(lhs.as_deref(), Some("__lhs"));
    }

    #[test]
    fn test_reference_return_unsafe_assignment_expr_returns_lhs_binding_not_temp_ref() {
        let int_ty = CppType::Int { signed: true };
        let int_ref_ty = CppType::Reference {
            referent: Box::new(int_ty.clone()),
            is_const: false,
            is_rvalue: false,
        };

        let lhs_ref = || {
            make_node(
                ClangNodeKind::DeclRefExpr {
                    name: "__lhs".to_string(),
                    ty: int_ref_ty.clone(),
                    namespace_path: vec![],
                },
                vec![],
            )
        };
        let rhs_ref = || {
            make_node(
                ClangNodeKind::DeclRefExpr {
                    name: "__rhs".to_string(),
                    ty: int_ty.clone(),
                    namespace_path: vec![],
                },
                vec![],
            )
        };
        let lhs_deref = || {
            make_node(
                ClangNodeKind::UnaryOperator {
                    op: UnaryOp::Deref,
                    ty: int_ty.clone(),
                },
                vec![lhs_ref()],
            )
        };

        let assign_expr = make_node(
            ClangNodeKind::BinaryOperator {
                op: BinaryOp::Assign,
                ty: int_ty.clone(),
            },
            vec![
                lhs_deref(),
                make_node(
                    ClangNodeKind::BinaryOperator {
                        op: BinaryOp::Or,
                        ty: int_ty.clone(),
                    },
                    vec![lhs_deref(), rhs_ref()],
                ),
            ],
        );

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::FunctionDecl {
                    name: "op_or_assign_like".to_string(),
                    mangled_name: "op_or_assign_like".to_string(),
                    is_static: false,
                    return_type: int_ref_ty.clone(),
                    params: vec![
                        ("__lhs".to_string(), int_ref_ty.clone()),
                        ("__rhs".to_string(), int_ty.clone()),
                    ],
                    is_definition: true,
                    is_variadic: false,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(ClangNodeKind::ReturnStmt, vec![assign_expr])],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("return __lhs;"),
            "unsafe assignment expression in reference-return context should return lhs binding, got:\n{}",
            code
        );
        assert!(
            !code.contains("return &mut unsafe { *__lhs ="),
            "unsafe assignment expression should not return reference-to-temporary form, got:\n{}",
            code
        );
    }

    #[test]
    fn test_reference_return_direct_declref_assignment_mutates_referent() {
        let int_ty = CppType::Int { signed: true };
        let int_ref_ty = CppType::Reference {
            referent: Box::new(int_ty.clone()),
            is_const: false,
            is_rvalue: false,
        };

        let lhs_ref = || {
            make_node(
                ClangNodeKind::DeclRefExpr {
                    name: "__lhs".to_string(),
                    ty: int_ty.clone(),
                    namespace_path: vec![],
                },
                vec![],
            )
        };
        let rhs_ref = || {
            make_node(
                ClangNodeKind::DeclRefExpr {
                    name: "__rhs".to_string(),
                    ty: int_ty.clone(),
                    namespace_path: vec![],
                },
                vec![],
            )
        };

        let assign_expr = make_node(
            ClangNodeKind::BinaryOperator {
                op: BinaryOp::Assign,
                ty: int_ty.clone(),
            },
            vec![
                lhs_ref(),
                make_node(
                    ClangNodeKind::BinaryOperator {
                        op: BinaryOp::Or,
                        ty: int_ty.clone(),
                    },
                    vec![lhs_ref(), rhs_ref()],
                ),
            ],
        );

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::FunctionDecl {
                    name: "op_or_assign_direct_declref".to_string(),
                    mangled_name: "op_or_assign_direct_declref".to_string(),
                    is_static: false,
                    return_type: int_ref_ty.clone(),
                    params: vec![
                        ("__lhs".to_string(), int_ref_ty.clone()),
                        ("__rhs".to_string(), int_ty.clone()),
                    ],
                    is_definition: true,
                    is_variadic: false,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(ClangNodeKind::ReturnStmt, vec![assign_expr])],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("unsafe { *__lhs ="),
            "direct DeclRef assignment for reference return should write through referent, got:\n{}",
            code
        );
        assert!(
            !code.contains("*__lhs = __lhs | __rhs"),
            "reference-return assignment RHS should read through dereferenced lhs, got:\n{}",
            code
        );
        assert!(
            code.contains("return __lhs;"),
            "reference-return assignment should return lhs reference binding, got:\n{}",
            code
        );
        assert!(
            !code.contains("return &mut { __lhs ="),
            "reference-return assignment must not create reference-to-temporary block, got:\n{}",
            code
        );
    }

    #[test]
    fn test_variadic_stdio_shims_link_to_c_runtime() {
        let ast = make_node(ClangNodeKind::TranslationUnit, vec![]);
        let code = AstCodeGen::new().generate(&ast);

        assert!(
            code.contains("#[link_name = \"vsnprintf\"]"),
            "expected vsnprintf shim to link against libc symbol, got:\n{}",
            code
        );
        assert!(
            code.contains("fn __fragile_extern_vsnprintf"),
            "expected generated vsnprintf extern declaration, got:\n{}",
            code
        );
        assert!(
            code.contains("__fragile_extern_vsnprintf(_s, _n, _fmt, _args.as_mut_ptr())")
                || code.contains(
                    "__fragile_extern_vsnprintf(_s, (_n) as u64, _fmt, _args.as_mut_ptr())"
                ),
            "expected generated vsnprintf shim call-through, got:\n{}",
            code
        );
        assert!(
            !code.contains(
                "pub fn vsnprintf(_s: *mut i8, _n: u64, _fmt: *const i8, _args: [FragileVaList; 1]) -> i32 { 0 }"
            ),
            "unexpected hardcoded vsnprintf zero-return stub remained in output:\n{}",
            code
        );
    }

    #[test]
    fn test_va_list_args_are_cloned_for_by_value_function_calls() {
        let va_list_array_ty = CppType::Array {
            element: Box::new(CppType::Named("va_list".to_string())),
            size: Some(1),
        };

        let va_decl = || {
            make_node(
                ClangNodeKind::DeclRefExpr {
                    name: "va".to_string(),
                    ty: va_list_array_ty.clone(),
                    namespace_path: vec![],
                },
                vec![],
            )
        };

        let call_consume_i = || {
            make_node(
                ClangNodeKind::CallExpr {
                    ty: CppType::Int { signed: true },
                    template_instantiation: None,
                },
                vec![
                    make_node(
                        ClangNodeKind::DeclRefExpr {
                            name: "consume_i".to_string(),
                            ty: CppType::Function {
                                return_type: Box::new(CppType::Int { signed: true }),
                                params: vec![va_list_array_ty.clone()],
                                is_variadic: false,
                            },
                            namespace_path: vec![],
                        },
                        vec![],
                    ),
                    va_decl(),
                ],
            )
        };

        let call_consume_foo = || {
            make_node(
                ClangNodeKind::CallExpr {
                    ty: CppType::Named("Foo".to_string()),
                    template_instantiation: None,
                },
                vec![
                    make_node(
                        ClangNodeKind::DeclRefExpr {
                            name: "consume_foo".to_string(),
                            ty: CppType::Function {
                                return_type: Box::new(CppType::Named("Foo".to_string())),
                                params: vec![va_list_array_ty.clone()],
                                is_variadic: false,
                            },
                            namespace_path: vec![],
                        },
                        vec![],
                    ),
                    va_decl(),
                ],
            )
        };

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::RecordDecl {
                        name: "Foo".to_string(),
                        is_class: false,
                        is_definition: true,
                        fields: vec![],
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::FunctionDecl {
                        name: "consume_i".to_string(),
                        mangled_name: "consume_i".to_string(),
                        is_static: false,
                        return_type: CppType::Int { signed: true },
                        params: vec![("va".to_string(), va_list_array_ty.clone())],
                        is_definition: true,
                        is_variadic: false,
                        is_noexcept: false,
                        is_coroutine: false,
                        coroutine_info: None,
                    },
                    vec![make_node(
                        ClangNodeKind::CompoundStmt,
                        vec![make_node(
                            ClangNodeKind::ReturnStmt,
                            vec![make_node(
                                ClangNodeKind::IntegerLiteral {
                                    value: 0,
                                    cpp_type: Some(CppType::Int { signed: true }),
                                },
                                vec![],
                            )],
                        )],
                    )],
                ),
                make_node(
                    ClangNodeKind::FunctionDecl {
                        name: "consume_foo".to_string(),
                        mangled_name: "consume_foo".to_string(),
                        is_static: false,
                        return_type: CppType::Named("Foo".to_string()),
                        params: vec![("va".to_string(), va_list_array_ty.clone())],
                        is_definition: true,
                        is_variadic: false,
                        is_noexcept: false,
                        is_coroutine: false,
                        coroutine_info: None,
                    },
                    vec![make_node(
                        ClangNodeKind::CompoundStmt,
                        vec![make_node(
                            ClangNodeKind::ReturnStmt,
                            vec![make_node(
                                ClangNodeKind::CallExpr {
                                    ty: CppType::Named("Foo".to_string()),
                                    template_instantiation: None,
                                },
                                vec![make_node(
                                    ClangNodeKind::CXXConstructExpr {
                                        ty: CppType::Named("Foo".to_string()),
                                    },
                                    vec![],
                                )],
                            )],
                        )],
                    )],
                ),
                make_node(
                    ClangNodeKind::FunctionDecl {
                        name: "use_va_twice".to_string(),
                        mangled_name: "use_va_twice".to_string(),
                        is_static: false,
                        return_type: CppType::Int { signed: true },
                        params: vec![("va".to_string(), va_list_array_ty.clone())],
                        is_definition: true,
                        is_variadic: false,
                        is_noexcept: false,
                        is_coroutine: false,
                        coroutine_info: None,
                    },
                    vec![make_node(
                        ClangNodeKind::CompoundStmt,
                        vec![
                            make_node(ClangNodeKind::ExprStmt, vec![call_consume_i()]),
                            make_node(ClangNodeKind::ExprStmt, vec![call_consume_i()]),
                            make_node(
                                ClangNodeKind::ReturnStmt,
                                vec![make_node(
                                    ClangNodeKind::IntegerLiteral {
                                        value: 0,
                                        cpp_type: Some(CppType::Int { signed: true }),
                                    },
                                    vec![],
                                )],
                            ),
                        ],
                    )],
                ),
                make_node(
                    ClangNodeKind::FunctionDecl {
                        name: "use_va_named_return".to_string(),
                        mangled_name: "use_va_named_return".to_string(),
                        is_static: false,
                        return_type: CppType::Named("Foo".to_string()),
                        params: vec![("va".to_string(), va_list_array_ty.clone())],
                        is_definition: true,
                        is_variadic: false,
                        is_noexcept: false,
                        is_coroutine: false,
                        coroutine_info: None,
                    },
                    vec![make_node(
                        ClangNodeKind::CompoundStmt,
                        vec![make_node(
                            ClangNodeKind::ReturnStmt,
                            vec![call_consume_foo()],
                        )],
                    )],
                ),
            ],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.matches("consume_i(va.clone())").count() >= 2,
            "va_list arguments passed by value should be cloned at repeated call sites, got:\n{}",
            code
        );
        assert!(
            code.contains("return consume_foo(va.clone());"),
            "va_list argument should be cloned in named-return call path too, got:\n{}",
            code
        );
    }

    #[test]
    fn test_explicit_destructor_on_pointer_typed_dot_receiver_uses_pointer_drop_in_place() {
        let node_ptr_ty = CppType::Pointer {
            pointee: Box::new(CppType::Named("XMLNode".to_string())),
            is_const: false,
        };
        let destructor_call = make_node(
            ClangNodeKind::CallExpr {
                ty: CppType::Void,
                template_instantiation: None,
            },
            vec![make_node(
                ClangNodeKind::MemberExpr {
                    member_name: "~XMLNode".to_string(),
                    is_arrow: false,
                    ty: CppType::Function {
                        return_type: Box::new(CppType::Void),
                        params: vec![],
                        is_variadic: false,
                    },
                    declaring_class: Some("XMLNode".to_string()),
                    is_static: false,
                },
                vec![make_node(
                    ClangNodeKind::DeclRefExpr {
                        name: "node".to_string(),
                        ty: node_ptr_ty.clone(),
                        namespace_path: vec![],
                    },
                    vec![],
                )],
            )],
        );

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::FunctionDecl {
                    name: "destroy_node".to_string(),
                    mangled_name: "destroy_node".to_string(),
                    is_static: false,
                    return_type: CppType::Void,
                    params: vec![("node".to_string(), node_ptr_ty)],
                    is_definition: true,
                    is_variadic: false,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(ClangNodeKind::ExprStmt, vec![destructor_call])],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("std::ptr::drop_in_place(node)"),
            "expected pointer-typed destructor call to drop pointee via pointer value, got:\n{}",
            code
        );
        assert!(
            !code.contains("std::ptr::drop_in_place(&mut node)"),
            "unexpected mutable reference to by-value pointer parameter in destructor lowering:\n{}",
            code
        );
    }

    #[test]
    fn test_string_literal_non_ascii_emits_hex_byte_escapes_not_unicode_escapes() {
        let string_expr = make_node(
            ClangNodeKind::StringLiteral("copyright ©".to_string()),
            vec![],
        );
        let gen = AstCodeGen::new();
        let lowered = gen.expr_to_string(&string_expr);
        assert!(
            lowered.contains("b\"copyright ")
                && lowered.contains("\\x")
                && lowered.contains("\\x00\".as_ptr() as *const i8"),
            "string literal should lower as byte string with explicit byte escapes, got:\n{}",
            lowered
        );
        assert!(
            !lowered.contains("\\u{"),
            "byte-string lowering must not emit unicode escapes, got:\n{}",
            lowered
        );
    }

    #[test]
    fn test_decode_c_string_escapes_to_bytes_preserves_high_hex_escape_bytes() {
        let decoded = decode_c_string_escapes_to_bytes("<\\xD0\\xB8\\xD1\\x82>".trim());
        assert_eq!(decoded, vec![b'<', 0xD0, 0xB8, 0xD1, 0x82, b'>']);
    }

    #[test]
    fn test_expr_to_string_raw_addr_of_pointer_valued_expr_avoids_extra_borrow() {
        let cstr_ty = CppType::Pointer {
            pointee: Box::new(CppType::Char { signed: true }),
            is_const: true,
        };
        let expr = make_node(
            ClangNodeKind::UnaryOperator {
                op: UnaryOp::AddrOf,
                ty: cstr_ty,
            },
            vec![make_node(
                ClangNodeKind::StringLiteral("raw".to_string()),
                vec![],
            )],
        );

        let lowered = AstCodeGen::new().expr_to_string_raw(&expr);
        assert!(
            lowered.contains(".as_ptr() as *const i8"),
            "pointer-valued address-of should still lower to pointer cast, got:\n{}",
            lowered
        );
        assert!(
            !lowered.contains("&b\""),
            "pointer-valued address-of must not introduce extra borrow before cast, got:\n{}",
            lowered
        );
    }

    #[test]
    fn test_unary_addr_of_pointer_valued_expr_avoids_extra_borrow_in_generated_return() {
        let cstr_ty = CppType::Pointer {
            pointee: Box::new(CppType::Char { signed: true }),
            is_const: true,
        };

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::FunctionDecl {
                    name: "cstr".to_string(),
                    mangled_name: "cstr".to_string(),
                    is_static: false,
                    return_type: cstr_ty.clone(),
                    params: vec![],
                    is_definition: true,
                    is_variadic: false,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(
                        ClangNodeKind::ReturnStmt,
                        vec![make_node(
                            ClangNodeKind::UnaryOperator {
                                op: UnaryOp::AddrOf,
                                ty: cstr_ty.clone(),
                            },
                            vec![make_node(
                                ClangNodeKind::StringLiteral("cast".to_string()),
                                vec![],
                            )],
                        )],
                    )],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        let return_line = code
            .lines()
            .find(|line| line.contains("return") && line.contains(".as_ptr() as *const i8"))
            .unwrap_or_default();
        assert!(
            !return_line.contains("return &"),
            "generated pointer-valued address-of return should cast directly, got line:\n{}\nfull code:\n{}",
            return_line,
            code
        );
        assert!(
            return_line.contains("as_ptr() as *const i8"),
            "generated return should keep direct pointer cast form, got line:\n{}\nfull code:\n{}",
            return_line,
            code
        );
    }

    #[test]
    fn test_unary_addr_of_reference_typed_pointer_value_avoids_extra_borrow() {
        let cstr_ty = CppType::Pointer {
            pointee: Box::new(CppType::Char { signed: true }),
            is_const: true,
        };
        let ref_to_cstr_ty = CppType::Reference {
            referent: Box::new(cstr_ty),
            is_const: true,
            is_rvalue: false,
        };
        let expr = make_node(
            ClangNodeKind::UnaryOperator {
                op: UnaryOp::AddrOf,
                ty: ref_to_cstr_ty,
            },
            vec![make_node(
                ClangNodeKind::StringLiteral("refptr".to_string()),
                vec![],
            )],
        );

        let lowered = AstCodeGen::new().expr_to_string(&expr);
        assert!(
            lowered.contains(".as_ptr() as *const i8"),
            "reference-typed address-of over pointer-valued operand should preserve pointer value form, got:\n{}",
            lowered
        );
        assert!(
            !lowered.contains("&b\""),
            "reference-typed address-of should not add redundant borrow over pointer-valued operand, got:\n{}",
            lowered
        );
    }

    #[test]
    fn test_pointer_param_call_normalizes_addr_of_pointer_valued_argument() {
        let cstr_ty = CppType::Pointer {
            pointee: Box::new(CppType::Char { signed: true }),
            is_const: true,
        };
        let xml_elem_ptr = CppType::Pointer {
            pointee: Box::new(CppType::Named("XMLElement".to_string())),
            is_const: false,
        };

        let new_element_call = make_node(
            ClangNodeKind::CallExpr {
                ty: xml_elem_ptr.clone(),
                template_instantiation: None,
            },
            vec![
                make_node(
                    ClangNodeKind::MemberExpr {
                        member_name: "NewElement".to_string(),
                        is_arrow: false,
                        ty: CppType::Function {
                            return_type: Box::new(xml_elem_ptr.clone()),
                            params: vec![cstr_ty.clone()],
                            is_variadic: false,
                        },
                        declaring_class: Some("XMLDocument".to_string()),
                        is_static: false,
                    },
                    vec![make_node(
                        ClangNodeKind::DeclRefExpr {
                            name: "doc".to_string(),
                            ty: CppType::Named("XMLDocument".to_string()),
                            namespace_path: vec![],
                        },
                        vec![],
                    )],
                ),
                make_node(
                    ClangNodeKind::UnaryOperator {
                        op: UnaryOp::AddrOf,
                        ty: cstr_ty.clone(),
                    },
                    vec![make_node(
                        ClangNodeKind::StringLiteral("Element1".to_string()),
                        vec![],
                    )],
                ),
            ],
        );

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::RecordDecl {
                        name: "XMLElement".to_string(),
                        is_class: true,
                        is_definition: true,
                        fields: vec![],
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::RecordDecl {
                        name: "XMLDocument".to_string(),
                        is_class: true,
                        is_definition: true,
                        fields: vec![],
                    },
                    vec![make_node(
                        ClangNodeKind::CXXMethodDecl {
                            class_name: "XMLDocument".to_string(),
                            name: "NewElement".to_string(),
                            return_type: xml_elem_ptr.clone(),
                            params: vec![("name".to_string(), cstr_ty.clone())],
                            is_definition: true,
                            is_static: false,
                            is_virtual: false,
                            is_pure_virtual: false,
                            is_override: false,
                            is_final: false,
                            is_const: false,
                            access: AccessSpecifier::Public,
                        },
                        vec![make_node(
                            ClangNodeKind::CompoundStmt,
                            vec![make_node(
                                ClangNodeKind::ReturnStmt,
                                vec![make_node(ClangNodeKind::NullPtrLiteral, vec![])],
                            )],
                        )],
                    )],
                ),
                make_node(
                    ClangNodeKind::FunctionDecl {
                        name: "call_new_element".to_string(),
                        mangled_name: "call_new_element".to_string(),
                        is_static: false,
                        return_type: xml_elem_ptr.clone(),
                        params: vec![(
                            "doc".to_string(),
                            CppType::Named("XMLDocument".to_string()),
                        )],
                        is_definition: true,
                        is_variadic: false,
                        is_noexcept: false,
                        is_coroutine: false,
                        coroutine_info: None,
                    },
                    vec![make_node(
                        ClangNodeKind::CompoundStmt,
                        vec![make_node(ClangNodeKind::ReturnStmt, vec![new_element_call])],
                    )],
                ),
            ],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("NewElement(") && code.contains(".as_ptr() as *const i8"),
            "expected pointer-valued string literal argument in NewElement call, got:\n{}",
            code
        );
        assert!(
            !code.contains("NewElement(&b\"Element1"),
            "pointer-parameter call normalization should not keep redundant borrow on pointer-valued args, got:\n{}",
            code
        );
    }

    #[test]
    fn test_reference_to_pointer_param_avoids_borrow_for_pointer_valued_argument() {
        let cstr_ty = CppType::Pointer {
            pointee: Box::new(CppType::Char { signed: true }),
            is_const: true,
        };
        let cstr_ref_ty = CppType::Reference {
            referent: Box::new(cstr_ty.clone()),
            is_const: true,
            is_rvalue: false,
        };
        let consume_fn_ty = CppType::Function {
            return_type: Box::new(CppType::Void),
            params: vec![cstr_ref_ty.clone()],
            is_variadic: false,
        };

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::FunctionDecl {
                        name: "consume".to_string(),
                        mangled_name: "consume".to_string(),
                        is_static: false,
                        return_type: CppType::Void,
                        params: vec![("p".to_string(), cstr_ref_ty)],
                        is_definition: true,
                        is_variadic: false,
                        is_noexcept: false,
                        is_coroutine: false,
                        coroutine_info: None,
                    },
                    vec![make_node(ClangNodeKind::CompoundStmt, vec![])],
                ),
                make_node(
                    ClangNodeKind::FunctionDecl {
                        name: "main".to_string(),
                        mangled_name: "main".to_string(),
                        is_static: false,
                        return_type: CppType::Void,
                        params: vec![],
                        is_definition: true,
                        is_variadic: false,
                        is_noexcept: false,
                        is_coroutine: false,
                        coroutine_info: None,
                    },
                    vec![make_node(
                        ClangNodeKind::CompoundStmt,
                        vec![make_node(
                            ClangNodeKind::ExprStmt,
                            vec![make_node(
                                ClangNodeKind::CallExpr {
                                    ty: CppType::Void,
                                    template_instantiation: None,
                                },
                                vec![
                                    make_node(
                                        ClangNodeKind::DeclRefExpr {
                                            name: "consume".to_string(),
                                            ty: consume_fn_ty,
                                            namespace_path: vec![],
                                        },
                                        vec![],
                                    ),
                                    make_node(
                                        ClangNodeKind::UnaryOperator {
                                            op: UnaryOp::AddrOf,
                                            ty: cstr_ty.clone(),
                                        },
                                        vec![make_node(
                                            ClangNodeKind::StringLiteral("ptr".to_string()),
                                            vec![],
                                        )],
                                    ),
                                ],
                            )],
                        )],
                    )],
                ),
            ],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("consume(") && code.contains(".as_ptr() as *const i8"),
            "expected pointer-valued string argument in consume call, got:\n{}",
            code
        );
        assert!(
            !code.contains("consume(&b\"ptr"),
            "reference-to-pointer parameter lowering should not add redundant borrow for pointer-valued args, got:\n{}",
            code
        );
    }

    #[test]
    fn test_local_declref_shadows_function_static_mapping_for_same_identifier() {
        let cstr_ty = CppType::Pointer {
            pointee: Box::new(CppType::Char { signed: true }),
            is_const: true,
        };
        let consume_fn_ty = CppType::Function {
            return_type: Box::new(CppType::Void),
            params: vec![cstr_ty.clone()],
            is_variadic: false,
        };

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::FunctionDecl {
                        name: "consume".to_string(),
                        mangled_name: "consume".to_string(),
                        is_static: false,
                        return_type: CppType::Void,
                        params: vec![("s".to_string(), cstr_ty.clone())],
                        is_definition: true,
                        is_variadic: false,
                        is_noexcept: false,
                        is_coroutine: false,
                        coroutine_info: None,
                    },
                    vec![make_node(ClangNodeKind::CompoundStmt, vec![])],
                ),
                make_node(
                    ClangNodeKind::FunctionDecl {
                        name: "main".to_string(),
                        mangled_name: "main".to_string(),
                        is_static: false,
                        return_type: CppType::Void,
                        params: vec![],
                        is_definition: true,
                        is_variadic: false,
                        is_noexcept: false,
                        is_coroutine: false,
                        coroutine_info: None,
                    },
                    vec![make_node(
                        ClangNodeKind::CompoundStmt,
                        vec![
                            make_node(
                                ClangNodeKind::DeclStmt,
                                vec![make_node(
                                    ClangNodeKind::VarDecl {
                                        name: "test".to_string(),
                                        ty: cstr_ty.clone(),
                                        has_init: true,
                                        is_extern: false,
                                        is_static: true,
                                    },
                                    vec![make_node(
                                        ClangNodeKind::StringLiteral("static".to_string()),
                                        vec![],
                                    )],
                                )],
                            ),
                            make_node(
                                ClangNodeKind::DeclStmt,
                                vec![make_node(
                                    ClangNodeKind::VarDecl {
                                        name: "test".to_string(),
                                        ty: cstr_ty.clone(),
                                        has_init: true,
                                        is_extern: false,
                                        is_static: false,
                                    },
                                    vec![make_node(
                                        ClangNodeKind::StringLiteral("local".to_string()),
                                        vec![],
                                    )],
                                )],
                            ),
                            make_node(
                                ClangNodeKind::ExprStmt,
                                vec![make_node(
                                    ClangNodeKind::CallExpr {
                                        ty: CppType::Void,
                                        template_instantiation: None,
                                    },
                                    vec![
                                        make_node(
                                            ClangNodeKind::DeclRefExpr {
                                                name: "consume".to_string(),
                                                ty: consume_fn_ty.clone(),
                                                namespace_path: vec![],
                                            },
                                            vec![],
                                        ),
                                        make_node(
                                            ClangNodeKind::DeclRefExpr {
                                                name: "test".to_string(),
                                                ty: cstr_ty.clone(),
                                                namespace_path: vec![],
                                            },
                                            vec![],
                                        ),
                                    ],
                                )],
                            ),
                        ],
                    )],
                ),
            ],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("static mut __fsv_") && code.contains("_test_0"),
            "expected function-static symbol emission for first declaration, got:\n{}",
            code
        );
        assert!(
            code.contains("consume(test as *const i8);"),
            "local variable should be used at callsite when shadowing static name, got:\n{}",
            code
        );
        assert!(
            !code.contains("consume(unsafe { __fsv_main_test_0 })"),
            "callsite should not resolve shadowed local variable through function-static symbol mapping, got:\n{}",
            code
        );
    }

    #[test]
    fn test_scoped_pointer_hint_prefers_innermost_shadow_for_receiver_hint() {
        let mut gen = AstCodeGen::new();
        gen.push_local_scope();
        gen.declare_scoped_local_var_with_ptr_hint("doc".to_string(), Some(true));
        assert!(
            gen.is_pointer_receiver_expr_string_hint("doc"),
            "outer pointer declaration should be tracked as pointer receiver"
        );

        let doc_declref = make_node(
            ClangNodeKind::DeclRefExpr {
                name: "doc".to_string(),
                ty: CppType::Named("XMLDocument".to_string()),
                namespace_path: vec![],
            },
            vec![],
        );
        gen.push_local_scope();
        gen.declare_scoped_local_var_with_ptr_hint("doc".to_string(), Some(false));
        assert!(
            !gen.is_pointer_receiver_expr_string_hint("doc"),
            "inner non-pointer shadow should override stale pointer receiver hints"
        );
        assert!(
            !gen.is_ptr_var_expr(&doc_declref),
            "DeclRefExpr lookup should use active shadowed local pointer hint"
        );

        gen.pop_local_scope();
        assert!(
            gen.is_pointer_receiver_expr_string_hint("doc"),
            "after popping inner scope, outer pointer hint should be visible again"
        );
    }

    #[test]
    fn test_shadowed_non_pointer_local_does_not_emit_pointer_receiver_call_shape() {
        let doc_ty = CppType::Named("XMLDocument".to_string());
        let doc_ptr_ty = CppType::Pointer {
            pointee: Box::new(doc_ty.clone()),
            is_const: false,
        };
        let error_method_ty = CppType::Function {
            return_type: Box::new(CppType::Bool),
            params: vec![],
            is_variadic: false,
        };

        let inner_error_call = make_node(
            ClangNodeKind::ExprStmt,
            vec![make_node(
                ClangNodeKind::CallExpr {
                    ty: CppType::Bool,
                    template_instantiation: None,
                },
                vec![make_node(
                    ClangNodeKind::MemberExpr {
                        member_name: "Error".to_string(),
                        is_arrow: false,
                        ty: error_method_ty,
                        declaring_class: Some("XMLDocument".to_string()),
                        is_static: false,
                    },
                    vec![make_node(
                        ClangNodeKind::DeclRefExpr {
                            name: "doc".to_string(),
                            ty: doc_ty.clone(),
                            namespace_path: vec![],
                        },
                        vec![],
                    )],
                )],
            )],
        );

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::FunctionDecl {
                    name: "main".to_string(),
                    mangled_name: "main".to_string(),
                    is_static: false,
                    return_type: CppType::Void,
                    params: vec![],
                    is_definition: true,
                    is_variadic: false,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![
                        make_node(
                            ClangNodeKind::DeclStmt,
                            vec![make_node(
                                ClangNodeKind::VarDecl {
                                    name: "doc".to_string(),
                                    ty: doc_ptr_ty,
                                    has_init: false,
                                    is_extern: false,
                                    is_static: false,
                                },
                                vec![],
                            )],
                        ),
                        make_node(
                            ClangNodeKind::CompoundStmt,
                            vec![
                                make_node(
                                    ClangNodeKind::DeclStmt,
                                    vec![make_node(
                                        ClangNodeKind::VarDecl {
                                            name: "doc".to_string(),
                                            ty: doc_ty,
                                            has_init: false,
                                            is_extern: false,
                                            is_static: false,
                                        },
                                        vec![],
                                    )],
                                ),
                                inner_error_call,
                            ],
                        ),
                    ],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("doc.Error();"),
            "shadowed non-pointer local should call method through value receiver, got:\n{}",
            code
        );
        assert!(
            !code.contains("(*doc).Error();"),
            "shadowed non-pointer local must not be lowered as pointer receiver, got:\n{}",
            code
        );
    }

