    #[test]
    fn test_collect_template_definitions_with_namespace_restores_sibling_paths() {
        let templ_ty = CppType::TemplateParam {
            name: "T".to_string(),
            depth: 0,
            index: 0,
        };
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::NamespaceDecl {
                        name: Some("alpha".to_string()),
                        is_inline: false,
                    },
                    vec![make_node(
                        ClangNodeKind::ClassTemplateDecl {
                            name: "Widget".to_string(),
                            template_params: vec!["T".to_string()],
                            is_class: false,
                            parameter_pack_indices: vec![],
                            requires_clause: None,
                        },
                        vec![make_node(
                            ClangNodeKind::FieldDecl {
                                name: "value".to_string(),
                                ty: templ_ty.clone(),
                                is_static: false,
                                access: AccessSpecifier::Public,
                                bit_field_width: None,
                            },
                            vec![],
                        )],
                    )],
                ),
                make_node(
                    ClangNodeKind::NamespaceDecl {
                        name: Some("beta".to_string()),
                        is_inline: false,
                    },
                    vec![make_node(
                        ClangNodeKind::ClassTemplateDecl {
                            name: "Widget".to_string(),
                            template_params: vec!["T".to_string()],
                            is_class: false,
                            parameter_pack_indices: vec![],
                            requires_clause: None,
                        },
                        vec![make_node(
                            ClangNodeKind::FieldDecl {
                                name: "value".to_string(),
                                ty: templ_ty,
                                is_static: false,
                                access: AccessSpecifier::Public,
                                bit_field_width: None,
                            },
                            vec![],
                        )],
                    )],
                ),
            ],
        );

        let mut codegen = AstCodeGen::new();
        codegen.collect_template_info(&ast.children);

        assert!(
            codegen.template_definitions.contains_key("alpha::Widget"),
            "template-definition prepass should keep first sibling namespace path"
        );
        assert!(
            codegen.template_definitions.contains_key("beta::Widget"),
            "template-definition prepass should keep second sibling namespace path without leakage"
        );
        assert!(
            !codegen.template_definitions.contains_key("alpha::beta::Widget"),
            "namespace path stack should be restored between sibling traversals"
        );
    }

    #[test]
    fn test_collect_fn_template_candidate_keys_uses_leaf_index_entries() {
        let mut codegen = AstCodeGen::new();
        let info = FnTemplateInfo {
            template_params: vec!["T".to_string()],
            return_type: CppType::Named("T".to_string()),
            params: vec![],
            body: None,
            is_noexcept: false,
        };
        codegen
            .fn_template_definitions
            .insert("make_shared".to_string(), info.clone());
        codegen
            .fn_template_definitions
            .insert("rusty::make_shared".to_string(), info.clone());
        codegen
            .fn_template_definitions
            .insert("std::make_shared".to_string(), info);
        codegen.rebuild_fn_template_leaf_index();

        let candidates = codegen.collect_fn_template_candidate_keys("make_shared", &[]);
        let candidate_set: std::collections::HashSet<String> =
            candidates.iter().cloned().collect();
        assert!(
            candidate_set.contains("make_shared"),
            "candidate key collection should include unqualified template key"
        );
        assert!(
            candidate_set.contains("rusty::make_shared"),
            "candidate key collection should include qualified keys from leaf index"
        );
        assert!(
            candidate_set.contains("std::make_shared"),
            "candidate key collection should include all qualified keys sharing leaf name"
        );
    }

    #[test]
    fn test_fn_template_has_param_dependent_args_reuses_cached_value() {
        let mut codegen = AstCodeGen::new();
        let info = FnTemplateInfo {
            template_params: vec!["T".to_string()],
            return_type: CppType::Named("T".to_string()),
            params: vec![("value".to_string(), CppType::Named("T".to_string()))],
            body: None,
            is_noexcept: false,
        };
        codegen.set_fn_template_definition("cache::probe".to_string(), info);
        assert!(
            codegen.fn_template_has_param_dependent_args("cache::probe"),
            "first query should compute and cache template-param dependency"
        );
        assert_eq!(
            codegen
                .fn_template_param_dependency_cache
                .get("cache::probe")
                .copied(),
            Some(true),
            "cache should store computed dependency flag"
        );
        codegen
            .fn_template_param_dependency_cache
            .insert("cache::probe".to_string(), false);
        assert!(
            !codegen.fn_template_has_param_dependent_args("cache::probe"),
            "subsequent query should use cached value without recomputing"
        );
    }

    #[test]
    fn test_fn_template_inference_shape_reuses_cached_value() {
        let mut codegen = AstCodeGen::new();
        let info = FnTemplateInfo {
            template_params: vec!["T".to_string()],
            return_type: CppType::Named("T".to_string()),
            params: vec![("value".to_string(), CppType::Named("T".to_string()))],
            body: None,
            is_noexcept: false,
        };
        codegen.set_fn_template_definition("cache::shape".to_string(), info);
        let initial_shape = codegen
            .fn_template_inference_shape("cache::shape")
            .expect("inference shape should be computed for known template key");
        assert_eq!(
            initial_shape.template_param_first_param_positions,
            vec![Some(0)],
            "computed inference shape should record first parameter position"
        );
        assert!(
            codegen
                .fn_template_inference_shape_cache
                .borrow()
                .contains_key("cache::shape"),
            "shape lookup should populate inference-shape cache"
        );

        codegen.fn_template_inference_shape_cache.borrow_mut().insert(
            "cache::shape".to_string(),
            std::sync::Arc::new(FnTemplateInferenceShape {
                template_param_first_param_positions: vec![Some(7)],
                template_param_appears_in_return: vec![true],
                has_parameter_pack: false,
                has_unsized_array_ref_param: false,
                has_non_type_param_candidate: false,
            }),
        );
        let reused_shape = codegen
            .fn_template_inference_shape("cache::shape")
            .expect("second lookup should reuse cached shape");
        assert_eq!(
            reused_shape.template_param_first_param_positions,
            vec![Some(7)],
            "second lookup should reuse cached shape entry without recomputing"
        );
    }

