    #[test]
    fn test_collect_fn_template_instantiation_uses_cached_call_resolution() {
        let templ_ty = CppType::TemplateParam {
            name: "T".to_string(),
            depth: 0,
            index: 0,
        };
        let int_ty = CppType::Int { signed: true };
        let call_fn_ty = CppType::Function {
            return_type: Box::new(int_ty.clone()),
            params: vec![int_ty.clone()],
            is_variadic: false,
        };

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::FunctionTemplateDecl {
                        name: "make".to_string(),
                        template_params: vec!["T".to_string()],
                        return_type: templ_ty.clone(),
                        params: vec![
                            ("lhs".to_string(), templ_ty.clone()),
                            ("rhs".to_string(), templ_ty.clone()),
                        ],
                        is_definition: true,
                        parameter_pack_indices: vec![],
                        requires_clause: None,
                        is_noexcept: false,
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::NamespaceDecl {
                        name: Some("rusty".to_string()),
                        is_inline: false,
                    },
                    vec![make_node(
                        ClangNodeKind::FunctionTemplateDecl {
                            name: "make".to_string(),
                            template_params: vec!["T".to_string()],
                            return_type: templ_ty.clone(),
                            params: vec![("value".to_string(), templ_ty)],
                            is_definition: true,
                            parameter_pack_indices: vec![],
                            requires_clause: None,
                            is_noexcept: false,
                        },
                        vec![],
                    )],
                ),
                make_node(
                    ClangNodeKind::FunctionDecl {
                        name: "call_make".to_string(),
                        mangled_name: "call_make".to_string(),
                        is_static: false,
                        return_type: int_ty.clone(),
                        params: vec![],
                        is_definition: true,
                        is_variadic: false,
                        is_noexcept: false,
                        is_coroutine: false,
                        coroutine_info: None,
                    },
                    vec![make_node(
                        ClangNodeKind::CompoundStmt,
                        vec![make_node(
                            ClangNodeKind::ReturnStmt,
                            vec![make_node(
                                ClangNodeKind::CallExpr {
                                    ty: int_ty.clone(),
                                    template_instantiation: None,
                                },
                                vec![
                                    make_node(
                                        ClangNodeKind::DeclRefExpr {
                                            name: "make".to_string(),
                                            ty: call_fn_ty,
                                            namespace_path: vec![],
                                        },
                                        vec![],
                                    ),
                                    make_node(
                                        ClangNodeKind::IntegerLiteral {
                                            value: 7,
                                            cpp_type: Some(int_ty),
                                        },
                                        vec![],
                                    ),
                                ],
                            )],
                        )],
                    )],
                ),
            ],
        );

        let mut codegen = AstCodeGen::new();
        codegen.collect_template_definitions_with_namespace(&ast.children, &[]);
        codegen.rebuild_fn_template_leaf_index();
        let call_node = &ast.children[2].children[0].children[0].children[0];
        let call_args = &call_node.children[1..];
        let resolution_key = AstCodeGen::fn_template_call_resolution_key(
            "make",
            &[],
            &["i32".to_string()],
            "i32",
            call_args,
            false,
        );
        codegen.fn_template_call_resolution_cache.insert(
            resolution_key,
            Some(("make".to_string(), vec!["i64".to_string()])),
        );

        codegen.collect_template_usages(&ast.children);
        let pending = codegen
            .pending_fn_instantiations
            .get("make_i64")
            .cloned()
            .expect("cached call resolution should be reused for matching call-site shape");
        assert_eq!(
            pending.0, "make",
            "cached call resolution should bypass candidate loop recomputation"
        );
        assert_eq!(
            pending.1,
            vec!["i64".to_string()],
            "cached call resolution should preserve cached concrete type args"
        );
    }

    #[test]
    fn test_collect_fn_template_instantiation_fast_paths_warm_cached_resolution_without_candidate_collection(
    ) {
        let int_ty = CppType::Int { signed: true };
        let call_ty = CppType::Function {
            return_type: Box::new(int_ty.clone()),
            params: vec![int_ty.clone()],
            is_variadic: false,
        };
        let call = make_node(
            ClangNodeKind::CallExpr {
                ty: int_ty.clone(),
                template_instantiation: None,
            },
            vec![
                make_node(
                    ClangNodeKind::DeclRefExpr {
                        name: "swap".to_string(),
                        ty: call_ty,
                        namespace_path: vec![],
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::IntegerLiteral {
                        value: 7,
                        cpp_type: Some(int_ty),
                    },
                    vec![],
                ),
            ],
        );

        let mut codegen = AstCodeGen::new();
        let template_info = FnTemplateInfo {
            template_params: vec!["T".to_string()],
            return_type: CppType::Named("T".to_string()),
            params: vec![("value".to_string(), CppType::Named("T".to_string()))],
            body: None,
            is_noexcept: false,
        };
        codegen
            .fn_template_definitions
            .insert("swap".to_string(), template_info.clone());
        let candidate_cache_key = AstCodeGen::fn_template_candidate_keys_cache_key("swap", &[]);
        codegen
            .fn_template_candidate_requires_call_arg_bounds_cache
            .borrow_mut()
            .insert(candidate_cache_key, false);
        let resolution_key = AstCodeGen::fn_template_call_resolution_key(
            "swap",
            &[],
            &["i32".to_string()],
            "i32",
            &call.children[1..],
            false,
        );
        codegen.fn_template_call_resolution_cache.insert(
            resolution_key,
            Some(("swap".to_string(), vec!["i64".to_string()])),
        );

        codegen.collect_fn_template_instantiation(&call);

        assert!(
            codegen.pending_fn_instantiations.contains_key("swap_i64"),
            "warm cached call-resolution should still materialize pending instantiation from cached template/type args"
        );
        assert!(
            codegen.fn_template_candidate_keys_cache.borrow().is_empty(),
            "warm cached call-resolution fast path should bypass candidate-key collection on hot lookup path"
        );
        assert!(
            codegen
                .fn_template_candidate_keys_with_defs_cache
                .borrow()
                .is_empty(),
            "warm cached call-resolution fast path should bypass definition-backed candidate-key collection on hot lookup path"
        );
    }

