    #[test]
    fn test_collect_fn_template_instantiation_skips_resolution_cache_when_no_candidates() {
        let int_ty = CppType::Int { signed: true };
        let call_ty = CppType::Function {
            return_type: Box::new(int_ty.clone()),
            params: vec![int_ty.clone()],
            is_variadic: false,
        };
        let call = make_node(
            ClangNodeKind::CallExpr {
                ty: int_ty.clone(),
                template_instantiation: None,
            },
            vec![
                make_node(
                    ClangNodeKind::DeclRefExpr {
                        name: "__fragile_unique_no_template_candidate_01".to_string(),
                        ty: call_ty,
                        namespace_path: vec![],
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::IntegerLiteral {
                        value: 7,
                        cpp_type: Some(int_ty),
                    },
                    vec![],
                ),
            ],
        );

        let mut codegen = AstCodeGen::new();
        codegen.fn_template_definitions.clear();
        codegen.fn_template_keys_by_leaf.clear();
        codegen.fn_template_candidate_keys_cache.borrow_mut().clear();
        codegen.collect_fn_template_instantiation(&call);

        assert!(
            codegen.pending_fn_instantiations.is_empty(),
            "no template candidates should not queue function-template instantiations"
        );
        assert!(
            codegen.fn_template_call_resolution_cache.is_empty(),
            "no template candidates should bypass call-resolution cache key creation/insertions, cache keys: {:?}",
            codegen
                .fn_template_call_resolution_cache
                .keys()
                .cloned()
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn test_collect_fn_template_instantiation_same_ptr_fallback_without_candidates() {
        let bool_ty = CppType::Bool;
        let const_char_ptr_ty = CppType::Pointer {
            pointee: Box::new(CppType::Char { signed: true }),
            is_const: true,
        };
        let same_call_ty = CppType::Function {
            return_type: Box::new(bool_ty.clone()),
            params: vec![
                const_char_ptr_ty.clone(),
                CppType::LongLong { signed: false },
                const_char_ptr_ty.clone(),
            ],
            is_variadic: false,
        };
        let call = make_node(
            ClangNodeKind::CallExpr {
                ty: bool_ty,
                template_instantiation: None,
            },
            vec![
                make_node(
                    ClangNodeKind::DeclRefExpr {
                        name: "same".to_string(),
                        ty: same_call_ty,
                        namespace_path: vec![],
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::DeclRefExpr {
                        name: "str".to_string(),
                        ty: const_char_ptr_ty.clone(),
                        namespace_path: vec![],
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::DeclRefExpr {
                        name: "size".to_string(),
                        ty: CppType::LongLong { signed: false },
                        namespace_path: vec![],
                    },
                    vec![],
                ),
                make_node(ClangNodeKind::StringLiteral("~".to_string()), vec![]),
            ],
        );

        let mut codegen = AstCodeGen::new();
        codegen.fn_template_definitions.clear();
        codegen.fn_template_keys_by_leaf.clear();
        codegen.fn_template_candidate_keys_cache.borrow_mut().clear();
        codegen.collect_fn_template_instantiation(&call);

        let synthesized = codegen
            .pending_fn_instantiations
            .get("same_ptr_const_i8")
            .expect("same_ptr fallback should still synthesize helper when no template candidates exist");
        assert_eq!(
            synthesized.0, "__fragile_yaml_same_literal_cmp",
            "same_ptr fallback should map to fragile literal-compare helper"
        );
        assert!(
            codegen.fn_template_call_resolution_cache.is_empty(),
            "same_ptr fallback path should not populate call-resolution cache when candidate set is empty"
        );
    }

    #[test]
    fn test_set_fn_template_definition_invalidates_param_dependency_cache() {
        let mut codegen = AstCodeGen::new();
        let dependent_info = FnTemplateInfo {
            template_params: vec!["T".to_string()],
            return_type: CppType::Named("T".to_string()),
            params: vec![("value".to_string(), CppType::Named("T".to_string()))],
            body: None,
            is_noexcept: false,
        };
        let non_dependent_info = FnTemplateInfo {
            template_params: vec!["T".to_string()],
            return_type: CppType::Named("T".to_string()),
            params: vec![("value".to_string(), CppType::Int { signed: true })],
            body: None,
            is_noexcept: false,
        };
        codegen.set_fn_template_definition("cache::swap".to_string(), dependent_info);
        assert!(
            codegen.fn_template_has_param_dependent_args("cache::swap"),
            "first cached dependency flag should reflect dependent definition"
        );
        assert!(
            codegen.fn_template_inference_shape("cache::swap").is_some(),
            "inference shape cache should populate for known template key"
        );
        let _ = codegen.fn_template_requires_call_arg_bounds("cache::swap");
        assert_eq!(
            codegen
                .fn_template_requires_call_arg_bounds_cache
                .get("cache::swap")
                .copied(),
            Some(false),
            "call-arg-bound requirement cache should populate alongside inference-shape cache"
        );
        codegen.fn_template_call_resolution_cache.insert(
            "cache-key".to_string(),
            Some(("cache::swap".to_string(), vec!["i32".to_string()])),
        );
        let candidate_namespace = vec!["cache".to_string()];
        let _ = codegen.collect_fn_template_candidate_keys("swap", &candidate_namespace);
        assert!(
            !codegen.fn_template_candidate_keys_cache.borrow().is_empty(),
            "candidate-key cache should populate after first lookup"
        );
        let _ = codegen.collect_fn_template_candidate_keys_with_defs("swap", &candidate_namespace);
        assert!(
            !codegen
                .fn_template_candidate_keys_with_defs_cache
                .borrow()
                .is_empty(),
            "definition-backed candidate-key cache should populate after first lookup"
        );
        let candidate_cache_key =
            AstCodeGen::fn_template_candidate_keys_cache_key("swap", &candidate_namespace);
        let candidate_keys_with_defs =
            codegen.collect_fn_template_candidate_keys_with_defs("swap", &candidate_namespace);
        let _ = codegen.fn_template_candidate_set_requires_call_arg_bounds(
            "swap",
            &candidate_namespace,
            &candidate_keys_with_defs,
        );
        assert_eq!(
            codegen
                .fn_template_candidate_requires_call_arg_bounds_cache
                .borrow()
                .get(&candidate_cache_key)
                .copied(),
            Some(false),
            "candidate-set call-arg-bound cache should populate alongside candidate-key caches"
        );
        let concrete_type_args = vec!["i32".to_string()];
        assert!(
            codegen
                .fn_template_concrete_match_shape("cache::swap", &concrete_type_args)
                .is_some(),
            "concrete shape cache should populate for known template key"
        );
        assert_eq!(
            codegen
                .fn_template_param_dependency_cache
                .get("cache::swap")
                .copied(),
            Some(true),
            "dependency cache should contain computed value"
        );

        codegen.set_fn_template_definition("cache::swap".to_string(), non_dependent_info);
        assert!(
            !codegen
                .fn_template_param_dependency_cache
                .contains_key("cache::swap"),
            "replacing template definition should invalidate cached dependency flag"
        );
        assert!(
            !codegen
                .fn_template_inference_shape_cache
                .borrow()
                .contains_key("cache::swap"),
            "replacing template definition should invalidate cached inference shape"
        );
        assert!(
            !codegen
                .fn_template_requires_call_arg_bounds_cache
                .contains_key("cache::swap"),
            "replacing template definition should invalidate cached call-arg-bound requirement"
        );
        assert!(
            codegen.fn_template_call_resolution_cache.is_empty(),
            "replacing template definition should invalidate cached call-resolution entries"
        );
        assert!(
            codegen.fn_template_candidate_keys_cache.borrow().is_empty(),
            "replacing template definition should invalidate cached candidate-key entries"
        );
        assert!(
            codegen
                .fn_template_candidate_keys_with_defs_cache
                .borrow()
                .is_empty(),
            "replacing template definition should invalidate cached definition-backed candidate-key entries"
        );
        assert!(
            codegen
                .fn_template_candidate_requires_call_arg_bounds_cache
                .borrow()
                .is_empty(),
            "replacing template definition should invalidate cached candidate-set call-arg-bound requirements"
        );
        let concrete_cache_key =
            AstCodeGen::fn_template_concrete_match_shape_key("cache::swap", &concrete_type_args);
        assert!(
            !codegen
                .fn_template_concrete_match_shape_cache
                .contains_key(&concrete_cache_key),
            "replacing template definition should invalidate concrete-shape cache entries for key"
        );
        assert!(
            !codegen.fn_template_has_param_dependent_args("cache::swap"),
            "recomputed dependency flag should reflect replacement definition"
        );
    }

    #[test]
    fn test_collect_fn_template_candidate_keys_deduplicates_and_keeps_priority_order() {
        let mut codegen = AstCodeGen::new();
        codegen.fn_template_keys_by_leaf.insert(
            "make_shared".to_string(),
            vec![
                "rusty::make_shared".to_string(),
                "make_shared".to_string(),
                "std::make_shared".to_string(),
                "rusty::make_shared".to_string(),
            ],
        );

        let namespace_path = vec!["rusty".to_string()];
        let candidates = codegen.collect_fn_template_candidate_keys("make_shared", &namespace_path);
        assert_eq!(
            candidates.as_ref(),
            &vec![
                "rusty::make_shared".to_string(),
                "make_shared".to_string(),
                "std::make_shared".to_string(),
            ],
            "candidate-key collection should deduplicate while preserving deterministic priority order"
        );

        codegen.fn_template_keys_by_leaf.insert(
            "make_shared".to_string(),
            vec![
                "rusty::make_shared".to_string(),
                "make_shared".to_string(),
                "std::make_shared".to_string(),
                "extra::make_shared".to_string(),
            ],
        );
        let cached_candidates =
            codegen.collect_fn_template_candidate_keys("make_shared", &namespace_path);
        assert!(
            Arc::ptr_eq(&cached_candidates, &candidates),
            "second lookup should reuse cached Arc-backed candidate-key vector allocation"
        );
        assert_eq!(
            cached_candidates.as_ref(),
            candidates.as_ref(),
            "second lookup should reuse cached candidate-key vector without recomputing from mutated leaf index"
        );
    }

    #[test]
    fn test_collect_fn_template_candidate_keys_with_defs_reuses_cached_subset() {
        let mut codegen = AstCodeGen::new();
        codegen.fn_template_keys_by_leaf.insert(
            "swap".to_string(),
            vec!["swap".to_string(), "std::swap".to_string()],
        );
        let template_info = FnTemplateInfo {
            template_params: vec!["T".to_string()],
            return_type: CppType::Named("T".to_string()),
            params: vec![("value".to_string(), CppType::Named("T".to_string()))],
            body: None,
            is_noexcept: false,
        };
        codegen
            .fn_template_definitions
            .insert("swap".to_string(), template_info.clone());

        let with_defs = codegen.collect_fn_template_candidate_keys_with_defs("swap", &[]);
        assert_eq!(
            with_defs.as_ref(),
            &vec!["swap".to_string()],
            "definition-backed candidate subset should include only keys with known template definitions"
        );

        // Mutate underlying maps without invalidating caches; second lookup
        // should reuse the cached subset computed from the original state.
        codegen.fn_template_keys_by_leaf.insert(
            "swap".to_string(),
            vec![
                "swap".to_string(),
                "std::swap".to_string(),
                "extra::swap".to_string(),
            ],
        );
        codegen
            .fn_template_definitions
            .insert("std::swap".to_string(), template_info);
        let cached_with_defs = codegen.collect_fn_template_candidate_keys_with_defs("swap", &[]);
        assert!(
            Arc::ptr_eq(&cached_with_defs, &with_defs),
            "second lookup should reuse cached Arc-backed definition-backed candidate subset allocation"
        );
        assert_eq!(
            cached_with_defs.as_ref(),
            with_defs.as_ref(),
            "second lookup should reuse cached definition-backed subset without recomputing from mutated maps"
        );
    }

    #[test]
    fn test_collect_fn_template_candidate_keys_prewarms_definition_backed_subset_cache() {
        let mut codegen = AstCodeGen::new();
        codegen.fn_template_keys_by_leaf.insert(
            "swap".to_string(),
            vec!["swap".to_string(), "std::swap".to_string()],
        );
        codegen.fn_template_definitions.insert(
            "swap".to_string(),
            FnTemplateInfo {
                template_params: vec!["T".to_string()],
                return_type: CppType::Named("T".to_string()),
                params: vec![("value".to_string(), CppType::Named("T".to_string()))],
                body: None,
                is_noexcept: false,
            },
        );

        let cache_key = AstCodeGen::fn_template_candidate_keys_cache_key("swap", &[]);
        let candidates = codegen.collect_fn_template_candidate_keys("swap", &[]);
        assert_eq!(
            candidates.as_ref(),
            &vec!["swap".to_string(), "std::swap".to_string()],
            "candidate-key collection should preserve deterministic lookup ordering"
        );

        let prewarmed_with_defs = {
            let cache_ref = codegen.fn_template_candidate_keys_with_defs_cache.borrow();
            cache_ref.get(&cache_key).cloned().expect(
                "candidate-key collection should prewarm definition-backed subset cache for matching lookup shape",
            )
        };
        assert_eq!(
            prewarmed_with_defs.as_ref(),
            &vec!["swap".to_string()],
            "prewarmed definition-backed subset should include only keys with known template definitions"
        );

        let with_defs = codegen.collect_fn_template_candidate_keys_with_defs("swap", &[]);
        assert!(
            Arc::ptr_eq(&with_defs, &prewarmed_with_defs),
            "definition-backed lookup should reuse prewarmed subset cache allocation"
        );
    }

