    #[test]
    fn test_resolve_existing_fn_template_path_prefers_pending_and_falls_back_to_generated() {
        let template_info = FnTemplateInfo {
            template_params: vec!["T".to_string()],
            return_type: CppType::Named("T".to_string()),
            params: vec![("value".to_string(), CppType::Named("T".to_string()))],
            body: None,
            is_noexcept: false,
        };
        let mut codegen = AstCodeGen::new();
        codegen.generated_functions.insert("swap_i32".to_string(), 1);
        codegen.pending_fn_instantiations.insert(
            "swap_i32".to_string(),
            (
                "swap".to_string(),
                vec!["i32".to_string()],
                template_info,
            ),
        );

        assert_eq!(
            codegen
                .resolve_existing_fn_template_path(&[], "swap_i32")
                .as_deref(),
            Some("swap_i32"),
            "pending instantiations should satisfy template path resolution without requiring generated-function lookup"
        );

        codegen.pending_fn_instantiations.clear();
        assert_eq!(
            codegen
                .resolve_existing_fn_template_path(&[], "swap_i32")
                .as_deref(),
            Some("swap_i32"),
            "generated-function lookup should remain a fallback when no pending instantiation exists"
        );
        assert_eq!(
            codegen
                .resolve_existing_fn_template_path(&[], "swap::i32")
                .as_deref(),
            Some("swap::i32"),
            "resolver helper should preserve sanitized generated-function fallback lookups for namespaced identifier shapes"
        );
        assert_eq!(
            codegen.resolve_existing_fn_template_path(&[], "swap_i64"),
            None,
            "resolver helper should report None when no pending/generated symbol exists"
        );
    }

    #[test]
    fn test_identifier_requires_sanitization_matches_identifier_shapes() {
        assert!(
            !AstCodeGen::identifier_requires_sanitization("swap_i32"),
            "already-sanitized identifier shapes should bypass sanitization probes"
        );
        assert!(
            !AstCodeGen::identifier_requires_sanitization("_swap9"),
            "leading underscore and alnum identifier shapes should bypass sanitization probes"
        );
        assert!(
            AstCodeGen::identifier_requires_sanitization("swap::i32"),
            "namespaced lookup shapes should require sanitization fallback probing"
        );
        assert!(
            AstCodeGen::identifier_requires_sanitization("9swap_i32"),
            "non-identifier-leading shapes should require sanitization fallback probing"
        );
        assert!(
            AstCodeGen::identifier_requires_sanitization("swap-i32"),
            "symbol-containing shapes should require sanitization fallback probing"
        );
    }

    #[test]
    fn test_sanitize_identifier_if_needed_borrows_clean_names_and_rewrites_symbolic_names() {
        let clean = AstCodeGen::sanitize_identifier_if_needed("swap_i32");
        assert!(
            matches!(clean, std::borrow::Cow::Borrowed("swap_i32")),
            "clean identifier shapes should stay borrowed and avoid rewrite allocation"
        );
        let namespaced = AstCodeGen::sanitize_identifier_if_needed("swap::i32");
        assert_eq!(
            namespaced.as_ref(),
            "swap_i32",
            "symbolic identifier shapes should still sanitize to generated-function spelling"
        );
        assert!(
            matches!(namespaced, std::borrow::Cow::Owned(_)),
            "symbolic identifier shapes should allocate rewritten sanitized spelling"
        );
    }

