    #[test]
    fn test_byte_requires_type_sanitization_dispatch_matches_legacy_for_all_bytes() {
        fn legacy(byte: u8) -> bool {
            matches!(
                byte,
                b'*'
                    | b':'
                    | b'-'
                    | b' '
                    | b'<'
                    | b'>'
                    | b','
                    | b'['
                    | b']'
                    | b';'
                    | b'('
                    | b')'
                    | b'"'
                    | b'&'
            )
        }

        for byte in 0u8..=u8::MAX {
            assert_eq!(
                byte_requires_type_sanitization_dispatch(byte),
                legacy(byte),
                "dispatch trigger mismatch for byte value {byte}",
            );
        }
    }

    #[test]
    fn test_type_sanitization_action_table_matches_legacy_for_all_bytes() {
        fn legacy_action(byte: u8) -> u8 {
            match byte {
                b'*' => SANITIZE_ACTION_STAR,
                b':' => SANITIZE_ACTION_COLON,
                b'-' => SANITIZE_ACTION_MINUS,
                b' ' | b'<' | b',' | b'[' | b']' | b';' | b'(' | b')' | b'"' => {
                    SANITIZE_ACTION_UNDERSCORE
                }
                b'>' => SANITIZE_ACTION_DROP,
                b'&' => SANITIZE_ACTION_REF,
                _ => SANITIZE_ACTION_PASS,
            }
        }

        for byte in 0u8..=u8::MAX {
            assert_eq!(
                type_sanitization_action(byte),
                legacy_action(byte),
                "action code mismatch for byte value {byte}",
            );
        }
    }

    #[test]
    fn test_collect_template_usages_descends_default_branch_with_children() {
        let templ_ty = CppType::TemplateParam {
            name: "T".to_string(),
            depth: 0,
            index: 0,
        };
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::ClassTemplateDecl {
                        name: "Widget".to_string(),
                        template_params: vec!["T".to_string()],
                        is_class: false,
                        parameter_pack_indices: vec![],
                        requires_clause: None,
                    },
                    vec![make_node(
                        ClangNodeKind::FieldDecl {
                            name: "value".to_string(),
                            ty: templ_ty,
                            is_static: false,
                            access: AccessSpecifier::Public,
                            bit_field_width: None,
                        },
                        vec![],
                    )],
                ),
                make_node(
                    ClangNodeKind::Unknown("wrapper".to_string()),
                    vec![make_node(
                        ClangNodeKind::VarDecl {
                            name: "w".to_string(),
                            ty: CppType::Named("Widget<int>".to_string()),
                            has_init: false,
                            is_static: false,
                            is_extern: false,
                        },
                        vec![],
                    )],
                ),
            ],
        );

        let mut codegen = AstCodeGen::new();
        codegen.collect_template_info(&ast.children);
        assert!(
            codegen.pending_template_instantiations.contains("Widget<int>"),
            "default recursion branch should still descend non-empty children and collect template usage"
        );
    }

